window.HB_TR["judges"]["ks"]=["1.\\tیشوع سٕندِ مرنہٕ پَتہٕ سپُد یہِ زِ بنی اسرٲیلِیو پرژھ خداوند سٕندِس خٕلافس سٍتـ̡ کُس گژھہِ اسہِ خٲطرٕ گۅڈٕ کنعانی خٕلاف تِمن خلاف لڑنہٕ خٲطرٕ۔\n2. تہٕ خداوند ووٚن زِ یہوداہ گژھہِ تھوٚد: وچھ میہ دِژ زمین تٔمۍ سٕندِس اتھس منز۔\n3. تہٕ یہوداہَن ووٚن پننِس بٲیِس شمعون سٍتـ̡ یێلہِ میانہِ سٍتـ̡ یێلہِ سٍتـ̡ یێلہِ أسـ̡ کنعانی سٍتـ̡ لڑُن۔ تہٕ بہٕ تہٕ یِتھٕ پٲٹھۍ گژھٕ ژے سٍتۍ چانہِ لاٹس منز۔ چنانچہ شمعون گوٚو أمس سۭتۍ۔\n4. تہٕ یہوداہ ووت تھوٚد۔ تہٕ خداوند دِژ کنعانی تہٕ پیریزی پننِس اتھس منٛز، تہٕ تِمو مارۍ تِمو منزٕ داہ ساس نفر۔\n5.\\tتہٕ تِمو لوٚب بیزیقس مَنٛز: تہٕ تِمو لوٚب أمِس خٕلاف، تہٕ تِمو مارِکھ کنعانی تہٕ پریزی۔\n6.\\tمگر ایڈونیبیزیک ژوٚل۔ تہٕ تِمو لٔگۍ أمِس پَتہٕ پَتہٕ، تہٕ رٔٹِتھ تہٕ ژٔٹِکھ تٔمۍ سٕندِ نوٚنگجہ تہٕ بٔڈۍ کھۄر ژٹِتھ۔\n7. تہٕ اڈونیبیزیکن ووٚن، تریہ تہٕ داہ بادشاہو کٔر پنٕنۍ انگوٹھہٕ تہٕ بٔڈۍ کھورِ ژٹِتھ تہٕ تِہُند ماز جمع کٔرِتھ میٲنِس ٹیبلس تَل جمع کٔرِتھ، یِتھٕ کٔنۍ میہ کٔرِتھ تہٕ خداین دِژ میہ بدلہٕ۔ تہٕ تِمو أنۍ سُہ یروشلم، تہٕ تتہِ موٗد سُہ ۔ {تہند انگوٹھ...: ہیب۔ تہندٮن اتھن تہ کھۅرن ہندۍ انگوٹھ} {جمع کٔرتھ: یا، ژٹنہِ}\n8. وۅنۍ اوس یہوداہ کیو اولادو یروشلمس خلاف جنگ کورمُت، تہٕ کورُکھ اتھ پیٹھ قبضہ تہٕ تلوار ہٕندِ دھار سٍتـ̡ مارُکھ تہٕ شہرس نار دِژمُت۔\n9. تہٕ امہِ پتہٕ گٔیہِ یہوداہٕکۍ بچہٕ کنعانین خلاف لڑنہٕ خٲطرٕ، یِم پہاڑس مَنٛز تہٕ جنوبس مَنٛز تہٕ وادی مَنٛز روزان ٲسۍ۔ {وادی: یا، زیریں ملک}\n10.\\tتہٕ یہوداہ گۆو کنعانین خلاف یُس ہیبرونس منز روزان اوس: (وۅنۍ اوس ہیبرون سُند ناو {اوس} کرجاتاربا:) تہٕ تِمو مارۍ شیشایی تہٕ اہیمان تہٕ تلمایی ۔\n11.\\tتہٕ تتہِ گۆو سُہ دیبیر کین بسکینن خلاف تہٕ دیبیر سُند ناو {اوس} کرجاتسیفر:\n12.\\tتہٕ کالبن ووٚن، یُس کرجاتھ سیفرس مارِ دِیہ، تہٕ نِیہ، بہٕ دِیہ أمِس پنٕنۍ کورِ خانٛدارِنہِ ہٕندِس دِنہٕ۔\n13.\\tتہٕ کیلب سٕندِس لۄکٹِس بٲیِس کیناز سٕندِس نیچوِس اوتھنیئلَن روٚٹ، تہٕ تٔمۍ دِژ أمِس پنٕنۍ کوٗر خانٛدارِنہِ خٲطرٕ۔\n14.\\tتہٕ سپُد ییلہ سۅ أمِس نِش آیہ، تٔمۍ کٔر أمِس مٲلِس نِش کھیت پرژھنہٕ خٲطرٕ، تہٕ تٔمۍ کٔر پننِس گَرٕ سٍتـ̡ گاش۔ تہٕ کالبَن ووٚن أمِس کیا کرُن؟\n15. تہٕ تٔمۍ ووٚن أمِس دِیُت، مے دِژ دُعا دِنہٕ، کیازِ ژے چھے مے اکھ جنوبُک زمین دِژمٕژ۔ میہ دِیو آبُک چشمہ تہِ۔ تہٕ کالبن دیت تس پیٹھم چشمہٕ تہٕ نیدر چشمہٕ۔\n16.\\tتہٕ موسیٰ سُند مول کینی سٕندِ شُرۍ دراو یہوداہ کِس شُرین سٍتـ̡ کھجور کُلـ̡ شہرٕ منزہ نیبر یہوداہ کِس بیابانس مَنٛز، یُس اراد کِس جنوبس مَنٛز چُھ۔ تہٕ تِم گٔیہِ لُکن مَنٛز روزان۔\n17.\\tتہٕ یہوداہ گۆو پننِس بٲیِس شمعون سٍتـ̡ تہٕ یِمو مٲرِتھ کنعانی یُس زیفتھس منز آباد اوس، تہٕ کوٚرُن یہِ پوٗرٕ پٲٹھـ̡ تباہ۔ تہٕ شہرک ناو اوس ہورمہ وننہٕ یوان۔\n18.\\tیہوداہ کٔر غزہ بٹھہِ سٍتـ̡ تہٕ اَمہ کِس بٹھِس سٍتـ̡ تہٕ ایکرون تہٕ اَمہ کِس بٹھِس سٍتـ̡ رٔٹِتھ ۔\n19. تہٕ خداوند اوس یہوداہ سٍتـ̡ ۔ تہٕ تٔمۍ کٔر پہاڑ کِس بسکینس کٔڈِتھ۔ مگر وادی ہٕندۍ روزن وٲلۍ ہیوٚک نہٕ کٔڑِتھ، تکیازِ تمن ٲس ششتٕرٕکۍ رتھ ۔ {ڈراو...: یا، پہاڑ اوس}\n20. تہٕ تِمو دِژ حبرون کالبس نِش، یِتھ کٔنۍ موسیٰ ہن ووٚنمُت: تہٕ تٔمۍ کٔرِن اَتھ نِش اناک سٕندِ تریہ نیچوۍ کٔڑِتھ۔\n21.\\tتہٕ بنیامین سٕندیو اولادو کٔر نہٕ یبوسیس یُس یروشلمس منز آباد اوس۔ مگر یبوسی چھہِ از تام یروشلمس منز بنیامین سٕندٮ۪ن شُرین سٍتـ̡ روزان۔\n22.\\tتہٕ یوسف سٕندِس گرس تہِ گٔیہِ تِم بیتھلس سٍتـ̡ تہٕ خداوند اوس تِمن سٍتـ̡ سٍتـ̡ ۔\n23.\\tتہٕ یوسف سٕندِ گرٕ سوزُن بیتھلس بیان کرنہٕ خٲطرٕ۔ (وۅنۍ چھہ شہرک ناو {was} Luz۔)\n24.\\tتہٕ جاسوسو وُچھ اکھ شخٕص شہرٕ منزٕ نیبر نیران، تہٕ تِمو وونُن أمِس ہاو، اسہِ ہٲوِو اسہِ، أسۍ دُعا کٔرِو شہرس منز اژُن، تہٕ أسۍ کرو ژے رحمت۔\n25.\\tتہٕ ییلہ تٔمۍ تِمن شہرس مَنٛز اژُن ہٲو، تِمو دِژ شہرس تلوار ہٕندِ کُنہِ کُنہِ سٍتـ̡ ۔ مگر تِمو ترٛٲو یہِ نفر تہٕ أمۍ سُنٛد سورُے عیال۔\n26.\\tتہٕ یہِ شخٕص گوٚو حِتِین ہٕندِس سرزمینس مَنٛز، تہٕ بَنوو اَکھ شہر، تہٕ وَنُن اَتھ ناو لُز: یُس از تام اَمیُک ناو چُھ۔\n27.\\tمنشاہن کٔر بیت شیان تہٕ تٔمۍ سٕندِس شہرن ہٕندِس بسکین، تہٕ تٔمۍ سٕندِس قصبن تہٕ نہ ڈور تہٕ تٔمۍ سٕندِس قصبن ہٕندِس بسکین، تہٕ نہ میگیڈو تہٕ تٔمۍ سٕندٮ۪ن قصبن ہٕندِس بسکین، مگر کنعانی ٲسۍ اَتھ زمینس منز روزان۔\n28.\\tتہٕ سپُد یێلہِ یێلہِ اِسرٲیل مضبوط اوس، تِمو دِژ کنعانی خراج دِنہٕ خٲطرٕ، تہٕ کٔرِکھ نہٕ تِم پوٗرٕ پٲٹھۍ۔\n29.\\tنہ کٔر افرائیم کٔڈِتھ کنعانی یِم گیزرس منز روزان ٲسۍ۔ مگر کنعانی ٲسۍ تمن منز گیزرس منز روزان۔\n30.\\tزبولونن کٔر نہ کِترون کین بسکینن تہ نہ نہلول کین بسکینن کٔڈِتھ ژٔلِتھ۔ مگر کنعانی رودۍ تمن منز روزان، تہٕ بنییہِ خراج دِنہٕ۔\n31.\\tآشرن کٔر نہ اچو کین بسکین، نہ زیدونکۍ بسکین، نہ احلب کِس بسکین، نہ اقصبکۍ بسکین، نہ حلبہ، نہ افیک تہ نہ ریہوبکۍ بسکین۔\n32.\\tمگر اشریسی ٲسۍ کنعانین مَنٛز روزان، یُس زمینہٕ کین بسکینن اوس، تکیازِ تِمو کٔر نہٕ تِم کٔڈِتھ کٔڈِتھ۔\n33.\\tنفتالین کٔر بیت شیمش کین بسکینن تہٕ نہ بیتھاناتھ کین بسکینن کٔڈِتھ۔ مگر سُہ اوس کنعانین مَنٛز روزان، یُس زمینہٕ کین بسکینن اوس، بہر حال بنییہِ بیت شمیش تہٕ بیتھاناتھٕکۍ بسکیٖن در تِمن ہٕندِ خٲطرٕ خراج دِنہٕ۔\n34. تہٕ اموریو کٔر دان سٕندِ بچہٕ پہاڑس منز زبردست، تکیازِ تِمو دِژ نہٕ تِمن وادی منز وسنہٕ خٲطرٕ۔\n35.\\tمگر امورِی ٲسۍ ایجالونس مَنٛز تہٕ شالبیمس مَنٛز روزان، توتہِ روٗد یوسف سٕندِس گرس ہُند اَتھ، یێلہِ بنییہِ تِم خراج دِنہٕ۔ {غالب: ہیب۔ اوس گوٚب}\n36.\\tتہٕ امورین ہُند ساحل اوس اکربم تام کھسنہٕ پیٹھ، کنہِ پتھرٕ پیٹھٕ تہٕ ہیرِ کُن۔ {دی گوئنگ...: یا، Maalehacrabbim}","1. تہٕ خداوند سُند اکھ فرشتہ آو گلگل پیٹھہٕ بوخیم تام تہٕ وونُن، مے بنوو ژے مصرہٕ منزٕ نیبر نیرنہٕ خٲطرٕ، تہٕ چُھکھ ژے تتھ زمینس تام واتنوومُت یُس بہٕ چُھس پننین آبن سٍتـ̡ حلف دِوان۔ تہٕ میہ ووٚن، بہٕ کٔرٕ نہٕ ژےٚ سٍتۍ پنُن عہد زانٛہہ تہِ۔ {فرشتہ: یا، میسنجر}\n2. تہٕ یَتھ زمینہٕ کِس روزن والٮ۪ن سٍتـ̡ کٔرِو نہٕ کانٛہہ تہِ اتحاد۔ تُہۍ ترٲوِو تِہٕنزِ قربان گاہ مگر ژے چُھکھ نہٕ میانہِ آوازِ ہٕنز اطاعت کٔرمٕژ: ژے کیازِ کوٚر یہِ؟\n3. اَمہِ مۄکھٕ چُھس مے یہِ تہِ ووٚنمُت زِ بہٕ کٔرٕ نہٕ تِم ژےٚ برونہہ کُن کٔڑِتھ۔ مگر تِم آسن تۅہہِ اندۍ پکھۍ کانٹۍ، تہٕ تِہٕندِ دیوتا آسن تۅہہِ خٲطرٕ جال۔\n4. تہٕ سپُد یێلہِ یێلہِ خداوند سٕندِ فرشتن یِم کلام سارِنٕے بنی اسرٲیلِس سٍتـ̡ وَننہٕ آمٕتـ̡ تہٕ لوکو کٔر آواز تُلِتھ تہٕ رووُن۔\n5. تہٕ تِمو ووٚن اَتھ جایہِ ہُند ناو بوچم: تہٕ تِمو کٔر اَتہِ خداوند سٕندِ خٲطرٕ قربانی۔ {بوچم: یعنی ویپرز}\n6.\\tیێلہِ یێلہِ یشوع یێلہِ لُکھ دِژ، بنی اسرٲیلِیو گۆو پرٮ۪تھ أکِس سٍتـ̡ زمینہٕ حٲصِل کرنہٕ خٲطرٕ پننِس وراثتس کُن۔\n7. تہٕ لوکو کٔر خداوند سٕنز خدمت یشوع سٕندِ سارِنٕے دۅہہٕ، تہٕ بزرگن ہٕندِس سارِنٕے دۅہن یِمو یشوع سٕندِ خٲطرٕ سارِنٕے بٔڈ کٲم وُچھمٕژ ٲس۔ {آؤٹ لائیوڈ: ہیب۔ واریاہن دۅہن پتہٕ}\n8.\\tتہٕ خداوند سُند خادم یُس نون سُند نیچو یشوع گۆو ہتھ تہٕ داہ وُہُر وٲنسہِ۔\n9.\\tتہٕ تِمو دفن سُہ تِمنتھیرس مَنٛز، افرائیم کِس پہاڑس مَنٛز، گاش بالہٕ کِس شمالس کُن۔ {ٹِمنتھارس: تِم مَناتھسِراہ تہِ وَننہٕ یِوان}\n10.\\tتہٕ سُہ سارِوٕے نسل گٔیہِ پننین مٲلن سٍتـ̡ جمع کرنہٕ، تہٕ تِمن پَتہٕ بێیہِ بیاکھ نسل پٲدٕ، یُس نہٕ خداوند سٕندِ سٍتـ̡ زانان اوس، تہٕ تِم کٲم یِم تٔمۍ اسرٲیلـ̡ خٲطرٕ کٔرمٕژ ٲس۔\n11. تہٕ بنی اسرٲیلو کٔر خداوند سٕندِس نظرس منز بُرکاری تہٕ کٔرٕکھ بعلیمٕچ خدمت۔\n12.\\tتہٕ تِمو ترٲوِکھ پننین آباؤ اجدادن ہُند خداوند خدا، یُس تِم مصر کہِ سرزمینہٕ منزٕ نیبر کٔرِتھ تہٕ باقین دیوتاہن ہٕنز، یِمن اندۍ پٔکھۍ لُکن ہٕندِس دیوتاہن ہٕنز، تہٕ کٔرٕکھ تِمن برونہہ کُن نمُن، تہٕ کٔرٕکھ خداوند سٕندِس شرارتس سٍتـ̡ دِنہٕ۔\n13.\\tتہٕ تِمو ترٲوِکھ خداوند تہٕ بعل تہٕ اشتروتھٕچ خدمت۔\n14.\\tتہٕ خداوند سُند غصہٕ اوس اسرٲیلِس سٍتـ̡ سٍتـ̡ سٍتـ̡ تِمن ہٕندِس اتھس مَنٛز دِنہٕ آمُت، تہٕ تِمو کُنُن تِمن ہٕندِس دُشمن ہٕندِس اتھس مَنٛز، یُتھ نہٕ تِم پننین دُشمنن برونہہ کُن کھڑا گژھِتھ۔\n15.\\tییتہِ تہِ تم نیبر نیرِ، خداوند سُند اتھہ اوس تمن خلاف بدی خٲطرٕ، یِتھ کٔنۍ خداوند اوس ووٚنمُت، تہٕ یِتھ کٔنۍ خداوند اوس تمن سٍتـ̡ حلف کورمُت، تہٕ تِم گٔیہِ سٮ۪ٹھاہ پریشان۔\n16.\\tبہر حال کٔر خداوند قاضی بیدار، یِمو تِمن ہٕندِ اتھہٕ نِش نجات دِژ یِمو تِم خراب کٔرۍ۔ {ڈیلیورڈ: ہیب۔ محفوظ}\n17.\\tتہٕ توتہِ ٲسۍ نہٕ تِم پننین ججن ہٕنز کتھ بوزان بلکہ گٔیہِ تِم باقین دیوتاہن ہٕندِس پٲٹھۍ، تہٕ تِمن برونہہ کُن نمُن: تِم گٔیہِ تِمن ہٕندِس مٲلِس سٍتـ̡ پکان تہٕ خداوند سٕندِس حُکمن ہٕنز فرمانبرداری کٔرِتھ ژٔلِتھ ۔ {مگر} تِمو کوٚر نہٕ یہ۔\n18.\\tتہٕ یێلہِ خداوند یێلہِ تِم قاضی سٍتـ̡ تھوٚد، تہٕ دِتُن تِمن دُشمن ہٕندِ اتھہٕ نِش نجات دِنہٕ، تِکیازِ یێلہِ تِمن سٍتـ̡ ظلم تہٕ پریشان کٔرِتھ کٔرٕن تِمن ہٕندِس دُشمن سٍتـ̡ تِمن ہٕندِس دُشمن سٍتـ̡ توبہ کرنہٕ۔\n19.\\tتہٕ سپُد ییلہ قاضی سُند مرُن اوس، تِمو آو واپس، تہٕ کٔرٕکھ پننین مٲلن ہٕندِ کھۅتہٕ زیادٕ بد عنوان، باقین دیوتاہن ہنز پیروی کرنہٕ خٲطرٕ، تہٕ تِمن برونہہ کُن سجدہ کرنہٕ خٲطرٕ۔ تِمو کٔر نہٕ پننیو کامہٕ نِش تہٕ نہ پننہٕ ضد طریقہٕ سۭتۍ۔ {corrupted...: یا، ٲسۍ بدعنوان} {بند...: ہیب۔ تِمن ہٕندِس نِش گژھہِ نہٕ کانہہ تہِ پیُن}\n20. تہٕ خداوند سُند غصہٕ اوس اسرٲیلِس سٍتـ̡ گٔژھمُت۔ تہٕ تٔمۍ ووٚن، تکیازِ یِمو لُکن کٔر میانہِ معاہدٕچ خلاف ورزی یُس میہ تِہندین مٲلن ہُند حُکُم اوس دِژمُت، تہٕ چُھکھ نہٕ میانہِ آواز بوزمٕژ۔\n21. بہٕ تہِ کٔرٕ نہٕ یِمن برونہہ کُنہِ تہِ قومن منزٕ یِم یشوع سٕندِ مرنہٕ وِزِ ترٲومٕتۍ:\n22.\\tیُتھ بہٕ یِمن ہٕندِ ذٔریعہٕ اسرٲیلِس ثٲبت کٔرِتھ، یِتھٕ پٲٹھـ̡ تِمن ہٕندِس مٲلِس ماجہ سٍتـ̡ پٔکِتھ کِنہٕ نہٕ۔\n23. تێمہِ کِنۍ کٔر خداوند تِمن قومن ہٕندِس دٔسۍ ژٔلِتھ ۔ نۂ تہٕ دِژ تِم یشوع سٕندِس اتھس منز۔ {دٔچھُن: یا، مصیبت}","1. وۅنۍ چِھ یِم قومہٕ یِم خداوند تِمو سٍتـ̡ اسرٲیلـ̡ ثٲبت کرنہٕ مۅکھہٕ دِژمٕتـ̡ {حتیٰ کہ} تِمن ہٕندِس سٍتـ̡ یێلہِ نہٕ کنعانٕچ سارِنٕے جنگہٕ زانان آسہِ۔\n2. صرف یێلہِ زِ بنی اِسرٲیلـ̡ ہٕندِس نسلس پى۪ٹھ، یێلہِ تِمن جنگ ہیچھناوٕنـ̡ تہٕ کم از کم یێلہِ آسہِ نہٕ امہِ سٍتـ̡ کانہہ تہِ زانان۔\n3. {یعنی}، فلسطینین ہٕندِ پانژھ مالک، تہٕ تمام کنعانی تہٕ سِدونِی، تہٕ حِوی یِم کوہ لبنان کِس پہاڑس مَنٛز روزان ٲسۍ، پہاڑ بعلحرمون پیٹھٕ حمتھ کِس دٲخلس تام۔\n4.\\tتہٕ تِم ٲسۍ تِمو سٍتـ̡ اسرٲیلـ̡ ثٲبت کرُن، یہِ زاننہٕ مۅکھہٕ زِ کیا تِم کَرٕ خداوند سٕندِس حُکمس سٍتـ̡ یُس تٔمۍ موسىٰ سٕندِ اتھہٕ سٍتـ̡ پننین مٲلن ہُند حُکُم دِیُتمُت اوس۔\n5. تہٕ بنی اسرائیل ٲسۍ کنعانی، حتی، امورین تہٕ پیرزی، حویین تہٕ یبوسین مَنٛز روزان۔\n6. تہٕ تِمو رٔٹۍ پنٕنۍ کورِ پنٕنۍ زنانہٕ تہٕ دِژٕکھ پنٕنۍ کورِ پننین نیچوین تہٕ دِژٕکھ پننین دیوتاہن ہٕنز خدمت۔\n7. تہٕ بنی اِسرٲیلِو کٔر خداوند سٕندِس نظرس مَنٛز بدکار تہٕ کٔرٕکھ خداوند پَنُن خدا، تہٕ کٔرٕکھ بعلیم تہٕ باغن ہٕنز خدمت۔\n8. تَمہِ کِنۍ اوس خداوند سُند غصہٕ اسرٲیلِس خٕلاف، تہٕ تٔمۍ کُن تِم میسوپوٹیمیا کِس بادشاہ چوشانریشتھیم سٕندِس اتھس مَنٛز۔ {میسوپوٹیمیا: ہیب۔ آرامنہاریم}\n9. تہٕ یێلہِ بنی اِسرٲیلِیو خداوند سٕندِس کُن فریاد کٔر، خداوند دِژ اِسرٲیلِس نِش نجات دِنہٕ وول تہٕ یێمہِ تِمن نجات دِژ، حتیٰ کہ کلب سُند لۄکُٹ بٲیِس کیناز سُند نیچو تہِ۔ {ڈیلیور: ہیب۔ نجات دہندہ}\n10.\\tتہٕ خداوند سُند روح آو أمِس پیٹھ، تہٕ تٔمۍ دِژ اسرٲیلُک فیصلہ تہٕ جنگہٕ خٲطرٕ درٛاوُن: تہٕ خداوند دِژ میسوپوٹیمیاہُک بادشاہ چوشانریشتھیم پننِس اتھس منٛز۔ تہٕ تٔمۍ سُنٛد اَتھٕ اوس چوشنریشتھیمس خٕلاف۔ {آو: ہیب۔ اوس} {میسوپوٹیمیا: ہیب۔ آرام}\n11. تہٕ زمینس ٲس ژتٲجی ؤری آرام کٔرمٕژ۔ تہٕ کیناز سُند نیچو اوتھنیئل موٗد۔\n12. تہٕ بنی اسرٲیلو کٔر خداوند سٕندِس نظرس منز دُبارٕ بُرکار تہٕ خداوند کٔر موآب کِس بادشاہ ایگلونس اسرٲیلِس خٕلاف مضبوط، تکیازِ تِمو اوس خداوند سٕندِس نظرس منز بُد کٲم کٔرمٕژ۔\n13. تہٕ تٔمۍ کٔر عمون تہٕ امالیک سٕندِ بچہٕ پانس نِش جمع تہٕ گٔیہِ اسرٲیلِس پیٹھ حملہٕ، تہٕ کوٚرُن کھجور کُلٮ۪ن ہُند شہر۔\n14.\\tیێلہِ کٔر بنی اسرائیل موآب کِس بادشاہ ایگلونس ارداہ وُہرۍ خدمت۔\n15. مگر ییلہ بنی اسرٲیلیو خداوند کُن فریاد کٔر، خداوند کٔر تِمن نجات دِنہٕ وول یُس گیرہ سُند نیچو ایہود اوس، یُس اکھ بنیجمیت اوس، تہٕ تٔمِس سٍتـ̡ سوز بنی اسرٲیلِیو موآب کِس بادشاہ ایگلونس نِش اکھ تحفہٕ۔ {a Benjamite: یا، Jemini سُند نیچو} {کھوورِ اتھہ: ہیب۔ تٔمۍ سٕنٛدِ دٔچھنِس اتھٕ بنٛد کٔرِتھ}\n16.\\tمگر ایہودن بنوو أمس اکھ خنجر یتھ زٕ کُنہِ کُنہِ زیچھرس پیٹھ ٲس۔ تہٕ تٔمۍ لوٚگ یہِ پننہِ دٔچھنِس رانس پیٹھ پلوَس تلہ کنہِ۔\n17.\\tتہٕ سُہ اوٚن موآب کِس بادشاہ ایگلونس نِش تحفہٕ: تہٕ ایگلون اوس سٮ۪ٹھاہ موٚٹُر انسان۔\n18.\\tتہٕ ییلہ تٔمۍ تحفہٕ پیش کرنہٕ خٲطرٕ ختم کٔر، تٔمۍ سوٗزۍ تِم لُکھ یِم تحفہٕ دِنہٕ آمٕتۍ ٲسۍ۔\n19.\\tمگر سُہ پھیُر پانہ تِمن کانن نِش یُس گلگلس سٍتـ̡ اوس، تہٕ وونُن، اے بادشاہ، مے چُھس ژے خٲطرٕ اکھ خفیہ کٲم کٔرمٕژ، اے بادشاہ: یُس ووٚن، ژھۄپہٕ تھاوُن۔ تہٕ یُس سٲری أمس سیتۍ کھڑا اوس، سہ گوٚو أمس نِش نیبر۔ {کانہٕ: یا، کٔرِتھ تصویر}\n20. تہٕ ایہود آو أمِس نِش۔ تہٕ سُہ اوس أکِس رٮ۪تہٕ کالہِ ہٕندِس پارلرس منز بِہتھ، یُس تٔمِس پانس خٲطرٕ اوس۔ تہٕ ایہودن ووٚن، میہ چُھ خدایہِ سُند پیغام۔ تہٕ سُہ ووٚتھ {پننہِ} سیٹہِ پیٹھ۔ {اکھ موسم گرما...: ہیب۔ ٹھنڈک اکھ پارلر}\n21.\\tتہٕ ایہود ترووُن کھوورِ اتھہٕ تہٕ کٔرِن دٔچھنِس رانہِ منزٕ خنجر تہٕ ترووُن پننِس یٔڈ مَنٛز۔\n22.\\tتہِ ژاو تلوارِ پتہ۔ تہٕ چربی لوٚگ تلوارِ پیٹھ بند، تاکہ سُہ ہیوٚک نہٕ خنجر پننہِ یٔڈ منزٕ کٔڈِتھ۔ تہٕ گندٕ دراو نیبر۔ {گند ...: یا، یہ آو کولہِ پیٹھ نیبر}\n23.\\tامہِ پتہٕ دراو ایہود دٲرِ منز، تہٕ کٔرٕن پارلٕکۍ دروازٕ پانس پیٹھ بند تہٕ بند کٔرِتھ بند کٔرِتھ۔\n24.\\tییلہ سُہ نیبر نیرِ، تٔمۍ سٕندِ نوکر آیہ۔ تہٕ ییلہ تمو وُچھ زِ پارلٕکۍ دروازٕ ٲسۍ بنٛد کٔرتھ، تمو ووٚن، یقینا سُہ چُھ پننِس رٮ۪تہٕ کالہٕ کِس کمرس منٛز پنٕنۍ کھۅر ؤلتھ۔ {کور کرُن...: یا، تٔمۍ سٕنز آسانی}\n25.\\tتہٕ روٗدۍ تِم توٚت تام رٔٹِتھ یوٚت تام تِم شرم گٔیہِ: تہٕ وُچھِتھ کٔر نہٕ تٔمۍ پارلرٕکۍ دروازٕ کھولنہٕ۔ تێمہِ کِنۍ تِمو تُل اکھ کُنز، تہٕ کھولُکھ تِمن ہُند رب زمینس پیٹھ پیوٚو۔\n26. تہٕ ایہود ژوٚل ییلہ تم رٔٹۍ، تہٕ ژوٚل کانو نیبر تہٕ ژول سیراتھس کُن۔\n27.\\tتہٕ ییلہ سُہ آو تمہِ سٍتـ̡ افرایم کِس پہاڑس مَنٛز بۄر وُن، تہٕ بنی اسرائیل گٔیہِ أمِس سٍتـ̡ پہاڑ پیٹھٕ بۄن تہٕ سُہ گۆو تِمن برونہہ کُن۔\n28. تہٕ تٔمۍ ووٚن تِمَن پَتہٕ پَتہٕ پٔکِو، یِکیازِ خداوند چُھ تُہٕندِس دُشمن موآب تُہنٛدِس اتھس مَنٛز دِژمُت۔ تہٕ تِم گٔیہِ أمِس پَتہٕ بۄن، تہٕ اردن ہٕندِس فورڈس نِش موآب کُن تہٕ دِژُکھ نہٕ کٲنسہ تہِ انسانس اپارِ نیرُن۔\n29.\\tتہٕ تِمو مارۍ تمہِ وِزِ تقریباً داہ ساس نفر، سٲری ہوس تہٕ سارِنٕے بہادر نفر۔ تہٕ اَتہِ ژٔلِتھ ژٔلِتھ کانٛہہ تہِ انسان۔ {lusty: Heb. چربی}\n30. چنانچہ موآب آو تمہِ دۅہہ اسرٲیلِس تل زیر کرنہٕ۔ تہٕ زمینس ٲسۍ ژور ؤری آرام دوان۔\n31.\\tتہٕ أمِس پَتہٕ اوس انات سُند نیچو شمگر، یٔمۍ فلسطینی شیہ ہتھ نفر أکِس بیلہٕ سٍتۍ مارِ۔ تہٕ تٔمۍ کٔر اسرٲیلِس تہِ بچٲو۔","1. تہٕ بنی اسرائیلو کٔر خداوند سٕندِس نظرس منز دُبارٕ بُر، ییلہِ ایہود اوس مٔرِتھ۔\n2. تہٕ خداوند کُن یِم کنعان کِس بادشاہ یابین سٕندِس اتھس مَنٛز، یُس حزورس مَنٛز راج کران اوس۔ یٔمۍ سٕندِ میزبان سُند کپتان اوس سیسیرا، یُس غیر قومن ہٕندِس ہاروشتھس منز روزان اوس۔\n3. تہٕ بنی اسرائیل کٔر خداوند سٕندِ نِش فریاد کرنہٕ، کیازِ أمِس ٲس ششتٕرٕکۍ نو ہتھ رتھ۔ تہٕ وُہن ؤرین کٔر تٔمۍ بنی اسرائیلن پیٹھ زبردست ظلم۔\n4.\\tتہٕ دبورہ، اکھ پیغمبر، لاپیڈوت سٕنز زنانہٕ، تمہ وقتہٕ کٔر اسرٲیلُک فیصلہٕ۔\n5.\\tتہٕ سۅ ٲس افرایم کِس پہاڑس مَنٛز رامہ تہٕ بیت ایلس درمیان دبورہ کِس کھجور کُلِس تل روزان، تہٕ بنی اسرائیلہٕ آیہِ أمِس نِش فیصلہٕ خٲطرٕ۔\n6. تہٕ تٔمۍ سوٗز تہٕ بُلووُن ابینوام سُند نیچو بارک، تہٕ وونُن تٔمِس زِ کیا نہٕ اسرٲیلِکِس خداہِ سُند حکم دِیُتمُت، {ونُن}، گژھ تہٕ تیبور کِس کُن نیرُن، تہٕ پانس سٍتـ̡ نفتالی ہٕندِس بُلِس تہٕ زبولون ہٕندِس بُلِس سٍتـ̡ نِیُن؟\n7. تہٕ بہٕ کٔرٕ ژےٚ کُن دٔریاوٕ کِشون سیسرا یُس جابین سٕندِ فوجُک کپتان چھُ، پنٕنۍ رتھٕ تہٕ تٔمۍ سٕندِس بٔڑِس سٍتـ̡ ۔ تہٕ بہٕ دِیہٕ سُہ چانہِ اتھس منٛز۔\n8.\\tتہٕ بارکن ووٚن أمِس زِ اگر ژٕ میہ سٍتۍ گژھِ، تیلہِ گژھٕ بہٕ نیرُن، مگر اگر ژٕ نہٕ میہ سٍتۍ گژھِ، تیلہِ گژھٕ نہٕ بہٕ نیران۔\n9. تہٕ تٔمۍ ووٚن، بہٕ گژھٕ یٔقیٖنی طور ژےٚ سٍتۍ: یُس سفر تہٕ ژے نیرِ، سُہ گژھِ نہٕ چانہِ عزتہٕ خٲطرٕ۔ تکیازِ خداوند کٕنُن سیسیرا زنانہِ ہٕندِس اتھس منز۔ تہٕ دبورہ ووٚتھ تہٕ گٔیہِ بارکَس سٍتۍ کیدیش کُن۔\n10.\\tتہٕ بارکن بُلوُن زبولُن تہٕ نفتالی کیدیش نِش۔ تہٕ سُہ ووت داہ ساس نفر ہٮ۪تھ پننین قدمن پیٹھ: تہٕ ڈیبورہ گٔیہِ أمِس سٍتۍ۔\n11.\\tوۅنۍ اوس ہیبر کینی، یُس موسیٰ سٕندِس مٲلس ہوباب سٕندِس اولادس منزٕ اوس، اوس کینین نِش الگ کورمُت، تہٕ کوٚرُن پنُن خیمہ زانایم کِس مٲدانس مَنٛز، یُس قدیش سٕندِ دٔسۍ {چُھ}۔\n12.\\tتہٕ تِمو ہٲو سیسیرا زِ ابینوام سُند نیچو برک اوس تبور کِس پہاڑس تام ووتمُت۔\n13.\\tتہٕ سِسیراہن کٔر پنٕنۍ تمام رتھ، حتیٰ کہِ ششتٕرٕکۍ نَو ہتھ رتھ، تہٕ تِم سٲری لُکھ یِم أمِس سٍتـ̡ ٲسۍ، غیر قومن ہٕندِس ہاروشتھ پیٹھٕ کِشون کِس دریاوس تام۔ {یکوٹہٕ: ہیب۔ فریاد کٔرِتھ، یا، اعلان}\n14.\\tتہٕ دیبوراہن ووٚن بارکَس پیٹھ۔ یێمہِ دۅہہٕ چُھہ سُہ دۅہ یێمہِ سٍتـ̡ خداوند چُھہ تُہٕندِس اتھس مَنٛز دِژمُت: کیا خداوند چُھنہٕ ژے برونہہ کُن دِژمُت؟ چنانچہ ووت بارک کوہ ٹیبور پیٹھٕ بۄن، تہٕ أمِس پتہٕ دَہ ساس نفر۔\n15.\\tتہٕ خداوند کٔر سیسیرا تہٕ سارِنٕے رتھ، تہٕ سارِنٕے سٍتـ̡ سٍتـ̡ تلوارِ ہٕندِس اندس سٍتـ̡ برکَس برونہہ کُن دِنہٕ۔ تہ سیسیرا ژوٚل پنن رتھ گاش تہ ژوٚل پننین قدمن پیٹھ۔\n16.\\tمگر برک لوٚگ رتھن پتہٕ تہٕ میزبانس پتہٕ غیر قومن ہٕندِس ہاروشتھس تام، تہٕ سیسیراہُک سورُے لشکر پیوٚو تلوار ہٕندِس اندس پیٹھ۔ {تہٕ} اوس نہٕ کانٛہہ نفر باقی۔ {اکھ مرد: ہیب۔ اَکہِ کُنہِ خٲطرٕ}\n17.\\tبہٕ ژوٚل سیسیرا پننین قدمن پیٹھ ہیبر کینی سٕنزِ زنانہِ جایِل سٕندِس خیمس کُن، تکیازِ حزور کِس بادشاہ جابین تہٕ ہیبر کِنی سٕندِس گرس درمیان اوس صلح۔\n18.\\tتہٕ یائل دراو سیسیرا ہس سمکھنہِ تہٕ وونُن أمِس زِ میانہِ آقا، میہ کُن پھیرُن۔ خوفہٕ نہٕ۔ تہٕ ییٚلہ سُہ أمس نِش خیمہ منٛز اژان اوس، تٔمۍ لوٚگ أمس اکھ پردٕ لٲگتھ۔ {مینٹل: یا، قالین یا، کمبل}\n19.\\tتہٕ تٔمۍ ووٚن أمِس دِیُن، بہٕ دِیُس ژےٚ دِیُس رژھ رژھ آب چیٚنہٕ خٲطرٕ۔ تکیازِ میہ چھیہ ترش۔ تہٕ تٔمۍ کھول دۄدٕچ اکھ بوتل، تہٕ دِژن أمس چیٚنہٕ تہٕ تھوٚپ دِتھ۔\n20.\\tبییہِ ووٚن أمِس خیمہ کِس دروازس پیٹھ کھڑا روزُن، تہٕ یێلہِ کانہہ نفر ییہ تہٕ تۅہہِ پرژھہِ تہٕ ونُن، کیا یتہِ چھا کانہہ انسان؟ یُس ژیہ ونُن، نہ۔\n21.\\tاَمہِ پتہٕ رٔٹ یایل ہیبر سٕنزِ زنانہِ خیمُک کیل، تہٕ رٔٹِن ہتھوڑٕ اتھس منز، تہٕ لوٚگ أمِس نِش، تہٕ لوٚگُن أمِس نِش تہٕ لوٚگُن أمِس نِش تہٕ لوٚگُن تٔمِس پٲٹھۍ، تکیازِ سُہ اوس شوٚنگِتھ تہٕ تھوٚکمت اوس۔ چنانچہ سُہ موٗد۔ {تہٕ تُل: ہیب۔ تہٕ پُٹ}\n22.\\tتہٕ وُچھِتھ یێلہِ بارک سیسیرا ہُند پَتہٕ لوٚگ، یَعل آو أمِس مِلنہٕ خٲطرٕ تہٕ وونُن أمِس یُس ژے ژھاران چھُ، بہٕ ہٲوِس ژے سُہ شخٕص یُس ژے ژھاران چھُ۔ تہٕ ییلہ سُہ تٔمۍ سٕندِس {خیمَس} منز آو، وُچھ سِسیرا موٗدمُت، تہٕ کیل اوس تٔمۍ سٕندِس مندرن منز۔\n23. یێمہِ دۅہہ دِژ خداین کنعانُک بادشاہ یابین یُس بنی اسرٲیلِس برونہہ کنہِ زیر گۆو۔\n24. تہٕ بنی اسرٲیلُک اَتھٕ سپُد ترقی تہٕ کٔرٕن کنعان کِس بادشاہ یابِنس پیٹھ غلبہٕ، یوتام تِمو کٔر کنعانُک بادشاہ یابین تباہ کرنہٕ۔ {خوشحال...: ہیب۔ گَژھُن گٔیہِ تہٕ اوس مُشکِل}","1.\\tتمہِ دۅہہ گۆو دیبورہ تہٕ ابینوام سُند نیچو براک،\n2. اسرٲیلُک انتقام حٲصل کرنہٕ خٲطرٕ کٔرِو خداوند سٕنز تعریف، یێلہِ لوکو پننہِ مرضی سٍتـ̡ پان پیش کٔر۔\n3. بوزو، اے بادشاہو؛ اے شہزادو کٔرِو کَن؛ بہٕ، {حتیٰ کہ} بہٕ گٮ۪وٕ خداوند سٕندِ خٲطرٕ؛ بہٕ گٮ۪وٕ اِسرٲیلِکِس خدایہِ سٕندِ خٲطرٕ {تعریف}۔\n4.\\tاے خداوند، ییلہ ژے سیر منزہ نیبر نیرِ، ییلہ ژے ادوم کِس میدانس منزہ نیبر نیرِ، زمین لٔج تھرتھر تہٕ آسمانن پیوٚو آب۔\n5.\\tپہاڑ گٔیہِ خداوند سٕندِ برونہہ کُن پٔہلِتھ، {حتیٰ کہ} سُہ سینا یُس اسرٲیلِکِس خدایہِ سٕندِس برونہہ کُن۔ {پگھل: ہیب۔ بہاؤ}\n6.\\tانتھ سٕندِس نیچوِس شمگر سٕندِس زمانس منز، یایل سٕندِس زمانس منز ٲس شاہراہٕ خالی تہٕ مسافر ٲسۍ وتہٕ کِنۍ پکان ۔ {مسافر: ہیب۔ پَتہٕ پَکَن وٲلۍ} {byways: Heb. ٹیڑھی وتہٕ}\n7. {گامن ہٕندِس بسکین} گٔیہِ بند، تِم گٔیہِ اسرٲیلِس مَنٛز بند، یوتام میہ دِبورہ پٲدٕ سپٕز، یُس بہٕ اسرٲیلِس مَنٛز موج پٲدٕ گٔیہِ۔\n8. تِمو کوٚر نٔوۍ دیوتاہن ہُند انتخاب۔ تیلہِ اوسا دروازن منز جنگ: اسرٲیلِس منز چھا ژتٲجی ساسن منز کانہہ ڈھال یا نیزہ وُچھنہٕ آمُت؟\n9.\\tمیون دِل چُھہ اسرائیلٕکین گورنرن کُن، یِمو پننہ مرضی سٍتـ̡ لوکن مَنٛز پیش کٔر۔ خداوند سُند برکت کرُن۔\n10.\\tکتھ کرو اے یُس سفیدٕ گٔرِس پیٹھ سوار چھُ، یُس فیصلس منز بِہتھ تہٕ وتہِ پکان چھُ۔ {کتھ: یا، مراقبہ}\n11. یِم آب کھینچ جاین پیٹھ تیر اندازن ہٕندِ شورٕ نِش نجات دِنہٕ آمٕتۍ، تتہِ گژھن تِم خداوند سٕندِ نیکی کامہِ ہٕنز پرناوٕن، حتیٰ کہ اسرائیلس مَنٛز تٔمۍ سٕندِس گامن ہٕندِس بسکینن سٍتـ̡ نیکی کامہِ ہٕنز پرناوٕن: تیلہٕ گژھن خداوند سٕندِ لُکھ دروازن تام بۄن۔ {راستباز...: حب۔ نیکی }\n12.\\tبیدار، بیدار، دیبورہ: بیدار، بیدار، اکھ گیون: وۅتھ، بارک، تہٕ پانس قٲد کرُن، اے ابینوام سُند نیچو۔\n13. پَتہٕ بنوو سُہ یُس لُکن مَنٛز رئیسن پیٹھ رٔٹِتھ روزان چُھ، خداوند بنوو مے طاقتورن پیٹھ غلبہٕ۔\n14.\\tافرائیم سٍتـ̡ اوس تِمن ہُند اکھ مول عمالیقس خلاف ۔ تۅہہِ پتہٕ، بینجمنی، پننین لوکن منز؛ ماچیر منزہ آو گورنرن تہ زبولون منزہ دراو تم یم مصنف سند قلم سنبھالان چھہِ۔ {ہینڈل: ہیب۔ ڈرا کٔرِتھ }\n15.\\tتہٕ اِساکرٕکۍ شہزادٕ ٲسۍ دبوراہس سٍتۍ۔ حتیٰ کہ اِساکر تہٕ بارک تہِ: سُہ آو پیدل وادی منز سوزنہٕ۔ روبن سٕنزِ تقسیمہٕ خٲطرٕ ٲسۍ دِلٕکۍ بٔڈۍ خیال۔ {فٹ: ہیب۔ تٔمۍ سٕندِس قدمن } {خیالات: Heb. تاثرات} {for: or, in}\n16.\\tژیہ کیازِ چھکھ کۅکرِ منز رژھ بٔنِتھ؟ روبن سٕنزِ تقسیمہٕ خٲطرٕ ٲس واریاہ دِلٕچ تلاش۔ {for: or, in}\n17. گلعاد اردن نیبر روزن: تہٕ ڈین کیازِ روٗد جہازن منز؟ آشر روٗد سمندر کِس بٹھس پیٹھ جٲری، تہٕ روٗد پننین خلاف ورژن منز روزان۔ {ساحل: یا، بندرگاہ} {خلاف ورزی: یا، کریکس}\n18.\\tزبولُن تہٕ نفتالی ٲسۍ تِتھۍ لُکھ یِمو کھیت کِس تھزرس مَنٛز مرنس تام پنٕنۍ زُو خطرس منز ترٛٲو۔ {خطرٕ: ہیب۔ ملامت ہُند شکار گٔیہِ}\n19.\\tبادشاہ آو {تہٕ} لوٚڑ، پتہٕ لوٚڑکھ کنعان کین بادشاہن سٍتـ̡ میگیڈو کِس آبس نِش تانچس منز۔ تِمو ہیوٚت نہٕ پٲنسہٕ ہُند کانہہ فٲیدٕ۔\n20. تِمو لوٚڑ آسمانہٕ پیٹھ۔ پننین کورسن منز لوٚگ ستارو سیسیرا ہس خلاف۔ {کورس: ہیب۔ وَتھ}\n21.\\tدٔریاوِ کِشَن دٔریاو، سُہ قدیم دٔریاو، دٔریاوٕ کِشون۔ اے میانہِ روح، ژے کٔر طاقت۔\n22.\\tاَمہ پتہٕ گُرِ کھُرِ پھُٹرٲوِتھ تہندٮ۪ن طاقتورن ہٕندِ دٔسۍ پھُٹراونہٕ۔ {پرنسنگ: یا، لتہٕ، یا، ڈوب}\n23.\\tخداوند سٕندِ فرشتہٕ ووٚن زِ میروزَس کٔرِو لعنت، یێمہِ ہٕندِس بسکینن ہٕندِس سٍتـ̡ دِیُن دُعا دِیُن۔ تِکیازِ تِم آیہ نہٕ خداوند سٕندِ مددٕ خٲطرٕ، طاقتورَن خٕلاف خداوند سٕندِ مددٕ خٲطرٕ۔\n24.\\tزنانہِ پیٹھۍ بابرکت گژھہِ یٲیل ہیبر سٕنزِ زنانہِ ہٕنزِ زنانہٕ سٍتـ̡ بابرکت آسہِ۔\n25.\\tتٔمۍ منگ آب، {تہٕ} تٔمۍ دِژ {أمِس} دۄد۔ تٔمۍ اوٚن أکِس شاہی ڈِشس منٛز مکھن ۔\n26. تٔمۍ تھوو پنُن اتھہٕ کیلس پیٹھ، تہٕ پنُن دٔچُھن اتھٕ کامہٕ والن ہتھوڑس پیٹھ۔ تہٕ ہتھوڑٕ سۭتۍ لوٚگ تٔمۍ سِسیرا سٕنٛدِس کلہٕ، ییٚلہ تٔمۍ أمۍ سٕنٛدِس مندرن منٛز زَد تہٕ لٔگۍ۔ {with...: Heb. تٔمۍ کٔر ہتھوڑ}\n27.\\tتٔمۍ سٕندِس قدمن نِش گٔیہِ سُہ نمُن، سُہ پیوٚو تٔمۍ سٕندِس قدمن نِش نمُن، سُہ پیوٚو سُہ پیوٚو۔ {پیٹھ: ہیب۔ درمیان} {مردہ: ہیب۔ تباہ}\n28.\\tسِسیرا سٕنزِ ماجہ وُچھن دارِ کُن تہٕ وُچھُن دٲرِ منز، تٔمۍ سُند رَتھ کیازِ چُھ یِنہٕ وُن؟ پننین رتھن ہندۍ چکر کیازِ چھہِ رژھران؟\n29.\\tتسٕنزِ دانشمند زنانہٕ دِژ أمِس جواب، آ، تٔمۍ دِژ پانس جواب دِنہٕ، {جواب: ہیب۔ تٔمۍ سٕنٛدۍ الفاظ}\n30. کیا تِمو چُھ نہٕ تیز رفتار؟ کیا تمو {نہ} شکارس تقسیم کورمُت۔ پرٮ۪تھ أکِس انسانس خٲطرٕ اکھ لڑکی {یا} زٕ؛ سیسیرا چھہ مختلف رنگن ہند شکار، سژنہِ ہندین مختلف رنگن ہند شکار، دۅشوے طرفہ سژنہِ ہندین مختلف رنگن ہند شکار، {مِلُن} تمن ہنزن گردن ہندِ خاطرہ یُس غنیمت رٹان چھہِ؟ {پرٮ۪تھ کُن...: ہیب۔ انسان سُند کلہ}\n31.\\tاے خداوند، تێلہِ گژھہِ پنُن سٲری دُشمن ختم گژھُن، مگر یێلہِ سُہ پننِس طاقتس سٍتـ̡ نیرِ، تِم گژھن آفتابٕکۍ پٲٹھۍ۔ تہٕ زمینس ٲس ژتٲجی ؤری آرام دِوان۔","1. تہٕ بنی اسرٲیلو کٔر خداوند سٕندِس نظرس منز بد کار تہٕ خداوند دِژ تِم ستن ؤرین مدیان کِس اتھس مَنٛز۔\n2.\\tتہٕ مدیانُک اَتھٕ سپُد اسرٲیلِس پیٹھ غالب: {تہ} مدیانیو سٍتـ̡ بنیوو تِمن گۅپھن تہٕ گۅپھن مَنٛز گۅپھ تہٕ مضبوط۔ {غالب: ہیب۔ اوس مضبوط}\n3. تہٕ یێلہِ ییلہ اسرٲیلِن بُووت ، مدیانی تہٕ مشرقٕکۍ اولاد تہٕ تِم تہِ آیہِ تِمن خلاف ۔\n4.\\tتہٕ تِمو کٔرِکھ تِمن خٕلاف ڈیرٕ ترٲوِتھ تہٕ زمینہِ ہُند اضافہٕ کوٚرُکھ تباہی، یوتام تُہۍ غزہ وٲتِتھ تہٕ اسرٲیلِس خٲطرٕ ترووُکھ نہٕ کُنہِ رزق، نہ کۅکر، تہٕ داند تہٕ گَرد۔ {کٹہٕ: یا ژھاوٕل}\n5.\\tتکیازِ تِم آیہ پنٕنۍ چاروٲے تہٕ خیمہ ہٮ۪تھ، تہٕ تِم آیہِ بٔڑِس بٔڑِس خٲطرٕ ٹڈِ۔ {تکیازِ} تِم تہٕ تِہٕندِ اوُنٹھ ٲسۍ بے تعداد: تہٕ تِم ژاو اتھ تباہ کرنہٕ خٲطرٕ زمینس منز۔\n6.\\tتہٕ مدیانیو سٍتـ̡ سپُد اسرٲیلِس سٍتـ̡ سٮ۪ٹھاہ غریب۔ تہٕ بنی اسرٲیلِو کٔر خداوند سٕندِ نِش فریاد ۔\n7. تہٕ سپُد سپُد، یێلہِ بنی اِسرٲیلِیو مدیانن ہٕندِ مۅکھہٕ خداوند سٕندِس سٍتـ̡ فریاد کٔر،\n8. یێلہِ خداوند سُہ اوس اِسرٲیلِس نِش اکھ پیغمبر سوزمُت، یێمہِ سٍتـ̡ تِمن وونُن زِ یِتھٕ پٲٹھـ̡ چُھہ اِسرٲیلِیُک خدا، یێمہِ سٍتـ̡ چُھہ یێلہِ تہٕ یێلہِ چُھہ یێلہِ تہٕ یێلہِ بێیہِ تُہٕندِس گَرٕ پى۪ٹھہٕ بێیہِ۔ {اکھ پیغمبر: ہیب۔ اکھ انسان اکھ پیغمبر}\n9. تہٕ مے کٔر ژے مصری ہٕندِ اتھہٕ نِش تہٕ تِمن سارِنٕے سٍتـ̡ یِمو سٍتـ̡ ظُلم کٔرِتھ نِش نِش تہٕ دِژُکھ تِہٕنز زمین۔\n10. تہٕ میہ ووٚن ژےٚ، بہٕ چُھس خداوند تُہند خدا۔ امورین ہٕندِس دیوتاہن سٍتـ̡ مہٕ خوفہٕ، یێمہِ سٕندِس سرزمینس مَنٛز تہٕ تُہۍ روزان چھِو، مگر تێہہ چُھہ نہٕ میانہِ آوازِ ہٕنز فرمانبرداری کٔرمٕژ۔\n11.\\tتہٕ آو خداوند سُند اکھ فرشتہ، تہٕ بیوٹھ أکِس بلوطس تل یُس اوفراہَس مَنٛز اوس، یُس یواش ابیزریٹس سٍتـ̡ اوس، تہٕ تٔمۍ سٕندِس نیچوِس گِدعونن کٔر شرابہٕ کِس دباونہٕ سٍتـ̡ کٕنُک کٕنُک کُنُن، یُس مدیانن نِش ژوٗرِ تھاونہٕ مۅکھہٕ۔ {گیڈیون: Gr. Gedeon} {چھپاونہٕ خٲطرٕ...: ہیب۔ یہ ژلنہٕ خٲطرٕ}\n12. تہٕ خداوند سُند فرشتہ آو أمِس نِش ظٲہر تہٕ وونُن تٔمِس سٍتـ̡ خداوند چُھہ توے سٍتـ̡ ، اے بہادر انسان۔\n13. تہٕ گدعونن ووٚن أمِس زِ اے خداوند، یێلہِ خداوند اسہِ سٍتـ̡ آسہِ، تیلہِ کیازِ چُھہ اسہِ سٍتـ̡ یێلہ تہٕ تٔمۍ سٕندِ تمام معجزات کتہِ چھِ یِم سانہِ آباؤ اجداد اسہِ ونان چھِ، کیا خداوند اوس نہٕ اسہِ مصرہٕ پیٹھٕ تُلنہٕ آمُت؟ مگر وۅنۍ چُھ خداوند اسہِ ترٲومُت، تہٕ دِژُن اسہِ مدیانن ہٕندِس اتھس مَنٛز۔\n14. تہٕ خداوند کٔر أمِس وُچھِتھ تہٕ وونُن، یێمہِ سٍتـ̡ گژھ پنہٕ نِس طاقتس مَنٛز، تہٕ ژے کٔرِو اسرٲیلِس مدیانن ہٕندِ اتھہٕ نِش بچاوُن: کیا مے چُھہ نہٕ ژے سوزمُت؟\n15. تہٕ تٔمۍ ووٚن أمِس زِ اے میانہِ خدا، بہٕ کَمہِ سٍتـ̡ بچاوٕ اسرٲیل؟ وچھو میون عیال چھہ منسیہس منز غریب، تہٕ بہٕ چھُس مٲلہِ سٕندِس گرس منز کم کھوتہ کم۔ {میون خاندان...: ہیب۔ میون ساس چھہ کمزور}\n16.\\tتہٕ خداوند ووٚن أمِس زِ یٔقیٖنی طور آسہٕ بہٕ تہٕ تہٕ ژے کٔرٕ مدیانین أکِس نفرس سٍتـ̡ مار۔\n17.\\tتہٕ تٔمۍ ووٚن أمِس زِ اگر وُنہِ میہ چانہِ نظرِ منز فضل میلہِ، تیلہِ ہٲو مے اکھ نشانی زِ ژے کٔرِو میانہِ سٍتـ̡ کتھ کرنہٕ۔\n18. بہٕ چُھس ژےٚ دُعا کَران، یوٚت تام نہٕ بہٕ ژےٚ نِش یِنہٕ تہٕ پنُن تحفہٕ برونہہ کُن اَن، تہٕ یہِ ژےٚ برونہہ کُن تھاوُن۔ تہٕ تٔمۍ ووٚن، بہٕ روزٕ توٚت تام یوٚت تام نہٕ ژٕ یِنہٕ۔ {موجودٕ: یا، ماز پیش کَرُن}\n19.\\tتہٕ گِدعون ژاو اژُن، تہٕ کوٚرُن اکھ شُر، تہٕ آٹہٕ ہٕندِس خمیرس روٚس کیک تیار، یُس ماز تٔمۍ أکِس ٹوٗکرِ مَنٛز تھووُن، تہٕ تٔمۍ تھووُن أکِس بانس مَنٛز، تہٕ أنِن أمِس نِش بلوطس تَل تہٕ دِژُن دِنہٕ۔ {اکھ بچہ: ہیب۔ ژھاوُن ہُنٛد اکھ شُر}\n20.\\tتہٕ خدایہِ سٕندِ فرشتن ووٚن أمِس ماز تہٕ خمیر روٚس تہٕ یِمن کٔرِن اتھ کٔنہِ پتھرس پیٹھ، تہٕ ترووُن شوربہٕ۔ تہٕ تٔمۍ کوٚر یہِ۔\n21. تێمہِ پَتہٕ ترووُن خداوند سٕندِ فرشتہٕ سٕندِس اتھس مَنٛز، تہٕ لوٚگُن مازس تہٕ خمیرٕ روٚس کیک۔ تہٕ تتہِ ووٚتھ کٔنہِ منزٕ نار تہٕ کھیوٚن ماز تہٕ خمیر روٚس کیک کھٮ۪وان۔ اَمہِ پَتہٕ گۆو خداوند سُند فرشتہٕ تٔمۍ سٕنزِ نظرِ نِش درٛاو۔\n22. تہٕ ییلہ جدعونن وُچھ زِ سُہ چُھ خداوند سُند فرشتہٕ، گدعونن ووٚن، اے خدایہ! تکیازِ میہ چھہ خدایہ سند اکھ فرشتہ بتھہِ بتھہِ وچھمت۔\n23.\\tتہٕ خداوند ووٚن تٔمِس سٍتـ̡ سلام۔ خوفہٕ مہٕ کرُن: ژٕ گژھ نہٕ مرُن۔\n24.\\tپَتہٕ بَنوو گِدعونن اَتہِ خداوند سٕندِ خٲطرٕ اَکھ قربان گاہ، تہٕ وَنُن یہِ یہِ از تام اَبِزریَن ہٕندِس اوفراہس مَنٛز۔ {یہوواہشالوم: یعنی، خداوند سوز امن}\n25.\\tتہٕ امی رٲژ گۆو خداوندِ أمِس وۆن، پننِس مٲلہِ سُند بچہٕ بیل نِن، یُس ستن وُہُر وٲنسہِ ہُند دوٚیِم بیل تہٕ تراوُن بعلُک قربان گاہ یُس تہندِس مٲلس نِش اوس، تہٕ ژٹُن باغہٕ یُس {حتیٰ چُھ} تہٕ ژٹُن یُس {حتیٰ چُھ} تہٕ\n26.\\tتہٕ یَتھ کَنہِ پَنِس پَنٕنِس پٲٹھۍ، مُقرر جایہِ پى۪ٹھ، تہٕ دۆیِم بیل رٔٹِتھ تہٕ کٔرِو تَمہِ باغہٕ کِس لٔکرِ سٍتـ̡ دزنہٕ آمٕژ قربانی یُس ژے ژٹنہٕ یُن۔ {راک: ہیب۔ مَضبوٗط جاے} {مَضموٗن مَنٛز...: یا، اَکھ مَضموٗن مَنٛز}\n27.\\tتێلہِ رٔٹۍ جدعونن پننین نوکروں منزٕ داہ نفر تہٕ یُتھ کٔرِن خداوند أمِس وونُن، تہٕ یێلہِ اوس یہِ تہٕ یێلہِ سُہ پننِس مٲلہِ سٕندِس گرس تہٕ شہرٕکین نفرن کھوژان زِ سُہ ہیوٚک نہٕ دۅہلہٕ تہٕ رٲژ کٔرِتھ۔\n28.\\tتہٕ ییلہ شہرٕکۍ مرد صُبحے سُلہِ وۅتھان وُچھِتھ آو بعلُک قربان گاہ تراونہٕ، تہٕ باغ آو ژٹنہٕ یُس {اوس} تہٕ دۆیِم بیل آو قربان گاہس پیٹھ پیش کرنہٕ۔\n29.\\tتہٕ تِمو ووٚن اَکھ أکِس أکِس سٍتـ̡ یہِ کٔمۍ کٔرِمُت؟ تہٕ ییلہ تِمو پرژھ گٲر تہٕ پرژھن، تِمو ووٚن زِ یوآش سٕندِس نیچوِس گِدعونن چھُ یہِ کٲم کٔرمٕژ۔\n30. اَمہِ پَتہٕ ووٚن شہرٕکیو لوکو یواشس زِ پَنُن نیچو أنِو یُتھ سُہ مَرُن، تِکیازِ تٔمۍ چھُ بعلُک قربان گاہ ترٛٲومُت، تہٕ تٔمۍ چھُ سُہ باغ ژٹمُت یُس اَتھ سٍتـ̡ اوس۔\n31.\\tتہٕ یوآشَن ووٚن تِمن سارِنٕے سارِنٕے سٍتـ̡ یُس أمِس خلاف کھڑا اوس، کیا تُہۍ کٔرِو بعل خٲطرٕ التجا کرنہٕ؟ کیا تُہۍ بچٲوِکھ أمِس؟ یُس أمِس خٲطرٕ درخواست کرِ، سُہ گژھہِ مارنہٕ یُن، یێلہِ سُہ خدا آسہِ، سُہ گژھہِ پانس خٲطرٕ التجا کرُن، کیازِ {أکہِ} چُھ پنُن قربان گاہ ترٛٲومُت۔\n32. تَمہِ دۅہہ ووٚن أمِس یِربعل وَنُن تہٕ وَنُن زِ بعل گٔژھ أمِس خٕلاف التجا کٔرِتھ، تِکیازِ تٔمۍ چھُ پَنُن قربان گاہ ترٛٲومُت۔ {یرُبعل: یعنی بعل گُزٲرِ} {یروبیشتھ: یعنی، شرمناک چیز گژھہِ التجا کرُن}\n33.\\tپتہٕ گٔیہِ سٲری مدیانی تہٕ امالیکی تہٕ مشرقٕکۍ شُرۍ جمع تہٕ گٔیہِ یزریل کِس وادی مَنٛز رٔلِتھ۔\n34. مگر خداوند سُند روح آو جدعونس پیٹھ، تہٕ تٔمۍ وُن بُرٕ۔ تہٕ ابیزر آو أمِس پتہٕ جمع کرنہٕ۔ {آو...: ہیب۔ لباس} {جمع کٔرتھ: ہیب۔ بلاو}\n35.\\tتہٕ سُہ سُہ سٲرِسٕے منسیٰ سٍتـ̡ قاصد سٍتـ̡ سٍتـ� یُس تہِ أمِس پَتہٕ جمع سپُد: تہٕ تٔمۍ سوٗزۍ آشرس تہٕ زبولُن تہٕ نفتالی کُن قاصد۔ تہٕ تِم آیہِ تِمن سمکھنہِ۔ {جمع: ہیب۔ بلاو}\n36. تہٕ جدعونن ووٚن خدایس سٍتۍ، یێلہِ ژے میانہِ اتھہٕ سٍتـ̡ اسرٲیلِس بچٲوِتھ، یِتھہٕ کٔنۍ ژے وَنُن چُھ،\n37. وچھ بہٕ تھوو فرشس منز اون ہُند اکھ اون۔ {تہ} اگر شبنم صرف اونس پیٹھ آسہِ، تہٕ {یہ} آسہِ سارِنٕے زمینس پیٹھ خشک گژھہِ، تیلہِ گژھہِ میہ معلوم زِ ژے کٔرِکھ اسرٲیلِس میانہِ اتھہٕ سٍتـ̡ بچاوُن، یِتھہٕ کٔنۍ ژے وَنُن چُھ۔\n38.\\tتہٕ یہِ اوس یۅہے زِ سُہ ووٚتھ پگہہ سُلہِ تہٕ دِژُن اون سُلہٕ سٍتـ̡ تہٕ لٔگِن آبہٕ سٍتـ̡ بٔرِتھ شُنمُک پیالہٕ۔\n39. تہٕ جدعونن ووٚن خدایس زِ چانہِ غصہٕ گژھہِ نہ میہ سٍتـ̡ گرم تہٕ بہٕ کَرٕ یہ اکہِ لٹہِ: بہٕ کرٕ ثٲبت کرُن، بہٕ چُھس ژے دُعا کران، مگر یہِ اکہِ لٹہِ یێلہِ ہٕندِس سٍتـ̡ ۔ وۅنۍ گژھہِ یہ صرف اونس پیٹھ خشک تہ سارِنٕے زمینس پیٹھ گژھہِ شبنم۔\n40.\\tتہٕ خداین کٔر تمہِ رٲژ یۅہے کٔرِتھ، تکیازِ یہ اوس صرف اونس پیٹھ خشک تہٕ سارِنٕے زمینس پیٹھ اوس شبنم۔","1.\\tیُس جِدعون تہٕ تِم سٲری لُکھ یُس أمِس سٍتـ̡ ٲس، سُلہٕ ووٚتھ، تہٕ ووت ہارود کِس کۅرَس نِش۔\n2. تہٕ خداوند ووٚن گدعونس زِ یِم لُکھ تۅہہِ سٍتـ̡ چِھہ، تِم چِھہ میانہِ خٲطرٕ واریاہ زیادٕ یِم مدیانی پننین اتھن منز دِنہٕ، یێلہِ اسرٲیلِس میانہِ خلاف پانس سٍتـ̡ دِنہٕ تہٕ وَنُن زِ میانہِ اَتھن چُھ مے بچٲومُت۔\n3. تێمہِ کِنۍ گژھ لوکن ہندین کنن منز اعلان کرُن، یُس تہِ خوفزدہ تہٕ خوفزدہ آسہِ، سُہ گژھہِ واپس تہٕ جلعاد پہاڑ پیٹھٕ سُلی نیرُن۔ تہٕ تتہٕ لوکو واپس، وُہ زٕ ساس۔ تہٕ تتہِ رودۍ داہ ساس۔\n4. تہٕ خداوند ووٚن گدعونس زِ لُکھ چِھ {تہِ} توتہِ واریاہ ۔ تِم أنِو آبس پیٹھ، تہٕ بہٕ کرٕ تتہِ تِمن آزمٲیش: تہٕ یہِ آسہِ، یٔمِس متعلق بہٕ ژےٚ وَنُن، یہِ گژھہِ ژےٚ سٍتۍ، سُہ گژھہِ ژےٚ سٍتۍ۔ تہٕ یُس تہِ بہٕ ژےٚ ونان چھُس، یہِ گژھِ نہٕ ژےٚ سٍتـ̡ نیرُن، سُہ گژھِ نہٕ سٍتـ̡ نیرُن۔\n5. یێمہِ سٍتـ̡ لُکھ آبس کُن واتناوُن، تہٕ خداوند وۆنُن گِدعونس زِ یُس یُس پننہِ زیٚوِ سٍتـ̡ آبہٕ سٍتـ̡ چُھہ، یِتھٕ پٲٹھـ̡ ہوُن چُھہ تھپھ کٔرِتھ، سُہ گژھہِ پانَے سٍتـ̡ دِنہٕ۔ یتھے پاٹھۍ چھہ پریتھ کانہہ یُس کۅٹھن پیٹھ بٔرتھ چیوان چھہ۔\n6.\\tتہٕ یِمن ہُند تعداد یِمو ٲسس پیٹھ اتھہٕ تھٲوِتھ، تِمن ہُند تعداد اوس تریہ ہتھ نفر: مگر باقٕے سارِوٕے لُکھ گٔیہِ آب چنہٕ خٲطرٕ کۅٹھن پیٹھ نَمان۔\n7.\\tتہٕ خداوند ووٚن گدعونس زِ یِمو تریہ ہتھ نفرو سٍتـ̡ بہٕ ژے بچٲوِتھ تہٕ مدیانی پننِس اتھس مَنٛز واتناوُن، تہٕ باقٕے سارِنٕے لُکھ گژھن پرٮ۪تھ أکِس پننہِ جایہِ نِش۔\n8.\\tیێمہِ لُکہٕ رٔٹِتھ رٔٹِتھ تہٕ تِمن ہٕندِس بُرقس سٍتـ̡ تہٕ سوٗزِن سارِنٕے اِسرٲیلِس پنہٕ نِس خیمس مَنٛز، تہٕ تِم ترے ہتھ نفر رٔٹِتھ تھٲوِتھ تہٕ مدیانُک لشکر اوس أمِس بۅنہ کنہِ وادی مَنٛز۔\n9.\\tتہٕ امی رٲژ سپد یێمہِ رٲژ زِ خداوند ووٚن أمِس وۆن، وۅتھ، وُچھِو تہٕ لشکرس نِش بۄن وُن۔ تکیازِ میہ چھہ یہ چانہِ اتھس منز واتنوومت۔\n10. مگر اگر ژیہ بۄن گژھنہٕ نِش خوفزدہ چھِو، تیٚلہِ گژھِو پَنٕنِس نوکرس سٍتـ̡ فروہس سٍتـ̡ لشکرس نِش۔\n11.\\tتہٕ تِمن ہٕندِ کتھ بوزٕنۍ۔ تہٕ امہِ پتہٕ گژھن پنٕنۍ اتھہٕ میزبانس تام گژھنہٕ خٲطرٕ مضبوٗط کرنہٕ۔ تمہ پتہ ووت سہ پننس نوکر فورہ سٍتۍ، یُس میزبانس منز موجود مسلح نفرن نیبر کُن اوس۔ {مسلح نفر: یا، پانژھ درجہٕ}\n12.\\tتہٕ مدینی، امالیکی تہٕ مشرقٕکۍ سٲری شُرۍ ٲسۍ وادی مَنٛز ٹڈِن ہٕندۍ پٲٹھۍ۔ تہٕ تِہٕندِ اوُنٹھ ٲسۍ بے تعداد، یِتھے پٲٹھۍ سمندرس بٔٹھۍ بٔڈۍ۔\n13.\\tتہٕ ییلہ جدعون آو اَکھ شخٕص یمۍ پننِس سٲتھیس اکھ خواب ووٚن تہٕ ووٚنن، وُچھ، میہ آو اکھ خواب، تہٕ وُپھ مِدیان کِس لشکرس منز، تہٕ ووت أکِس خیمس منز، تہٕ دِژُن سُہ پیوٚو تہٕ لوٚٹ تہٕ لوٚٹ تہٕ خیمہٕ پیوٚو۔\n14.\\tتہٕ تٔمۍ سٕندِس سٲتھین دیُت جواب تہٕ وونُن، یہِ چُھہ نہٕ یُس یوآش سٕندِس نیچوِس سٕنزِ تلوار سٍتـ̡ بێیہِ تہٕ یُس اسرٲیلُک آدمی چُھ، یێلہِ خداین دِژ مِدیان تہٕ سارِنٕے لشکر پننِس اتھس مَنٛز۔\n15.\\tتہٕ یێلہِ گِدعونن خوابٕچ کتھ تہٕ تٔمِچ تعبیر بوز، تٔمۍ کٔر عبادت تہٕ ووت اسرٲیلِس کِس لشکرس مَنٛز واپس، تہٕ وونُن، وُپھ وُپھ۔ تکیازِ خداوند چُھ تُہندس اتھس منز مدیانُک لشکر دِژمُت۔ {تشریح: ہیب۔ بریکنگ}\n16.\\tتہٕ تٔمۍ کٔر تریہ ہتھ نفر ترٮ۪ن کمپنین منز تقسیم، تہٕ تٔمۍ تھووُن پرٮ۪تھ نفرٕ سٕندِس اتھس منز اکھ بُر، یتھ منز خٲلی گٹہٕ تہٕ چراغ ٲسۍ۔ {اکھ ٹرمپیٹ...: ہیب۔ یمن سارنی ہٕندِس اتھس منز ٹرمپیٹ} {لیمپ: یا، آتش برانڈ، یا، ٹارچ}\n17.\\tتہٕ تٔمۍ ووٚن تِمن وُچھِتھ تہٕ یِتھٕ پٲٹھۍ کرُن، تہٕ یێلہِ بہٕ خٲمہٕ نیبرِمِس کُن واتہِ، تہٕ یێلہِ بہٕ یِتھٕ پٲٹھۍ بہٕ تہٕ یێلہِ تہِ کرُن۔\n18.\\tییلہ بہٕ بُرِ سٍتـ̡ وُپھ دِوان، بہٕ تہٕ سارِنٕے سٍتـ̡ یێلہِ سٍتـ̡ سارِنٕے خٲمہٕ سٍتـ̡ تہٕ وَنُن تہٕ وَنُن خداوند سٕنز تلوار تہٕ گِدعونس سٍتـ̡ ۔\n19.\\tیێلہِ گِدئون تہٕ ہتھ نفر یِم أمِس سٍتـ̡ ٲسۍ، درمیانی پہرٕ کِس شروعاتس مَنٛز آیہ کیمپس نیبرمِس کُن۔ تہٕ تِمو ٲس نٔوۍ پَرِ تھوٚد کٔرمٕژ: تہٕ تِمو دِژ بُرِ تہٕ تِمن ہٕندِس اتھس منز {ٲس} گِلہٕ پھِرۍ۔\n20.\\tتہٕ ترشویو کمپنیو وُپھ دِژٕن، تہٕ دٔچھنِس اتھس مَنٛز رٔٹِتھ تہٕ دٔچھنِس اتھس مَنٛز لٔگِتھ دٔچھنِس اتھس مَنٛز، تہٕ تِمو کٔرٕکھ دٔچھنِس اتھس مَنٛز، تہٕ تِمو کٔرٕکھ خدایہِ سٕنز تلوار، تہٕ گِدعونس سٕنز تلوار۔\n21.\\tتہٕ تِمو کھڑا پرٮ۪تھ أکِس شخصس پننہِ جایہِ خٲمس اندۍ کھڑا۔ تہٕ سارِوٕے میزبان ژٔلِتھ تہٕ وُپھ ژٔلِتھ ژٔلِتھ۔\n22.\\tتہٕ تریہ ہتن وُپھ بُن، تہٕ خداوند کٔر پرٮ۪تھ أکِس انسانس تلوار پننِس سٲتھیس سٍتـ̡ تہٕ سارِنٕے لشکرس سٍتـ̡ تہٕ لشکر ژوٚل زرارتس کِس بیت شیتس کُن، تہٕ ابیلمہولا کِس سرحدس کُن تہٕ تبت کُن۔ {منز: یا، کُن} {بارڈر: ہیب۔ لپ}\n23.\\tتہٕ اِسرٲیلٕکۍ مرد گٔیہِ نفتالی منز، آشیر تہٕ سارِنٕے منسیٰ منزٕ جمع تہٕ لٔگۍ مدیانین ہُند پَتہٕ پَتہٕ۔\n24.\\tتہٕ گدعونن سوٗزۍ تمام پہاڑ افرائیم سٍتـ̡ قاصد تہٕ وونُن زِ مدیانن پیٹھ آو تہٕ تِمن برونہہ کُن نِو بیت بارہ تہٕ اردن کُن آب۔ اَمہِ پتہٕ گٔیہِ افرائیم سٕندِ سارِوٕے نفر جمع تہٕ نِیوُکھ آب بیت بارہ تہٕ اردن کُن۔\n25.\\tتہٕ تِمو رٔٹۍ مدیانین ہٕندِ زٕ شہزادہٕ، اوریب تہٕ زیب۔ تہٕ تِمو مٲرِکھ اوریب کِس کَنہِ پتھرس پیٹھ، تہٕ زیب مٲرِتھ زیب سٕندِس شرابَس پیٹھ تہٕ مِدیان ہُند تعاقب کٔرِتھ أنِکھ اوریب تہٕ زیب سٕندِ کلہٕ دوٚیمہِ طرفہٕ اردن کِس کُنہِ طرفہٕ جدعونس نِش۔","1.. تہٕ افرائیم سٕندیو لوکو ووٚن أمِس زِ ژے کیازِ کٔر اسہِ یِتھٕ پٲٹھۍ خدمت، یێلہِ تہٕ ژے چُھکھ نہٕ اسہِ بُلاونہٕ آمُت، ییلہ تہٕ ژے مدیانن سٍتـ̡ لڑنہٕ خٲطرٕ یێلہِ تہٕ ژے چُھہ اسہِ بُلاونہٕ آمُت۔ تہٕ تِمو کٔر أمِس سٍتۍ سختی سان طعنہٕ۔ {کیازِ...: ہیب۔ یہ کیا چُھ ژے اسہِ سٍتـ̡ کورمُت} {تیز: Heb. مضبوطی سان}\n2. تہٕ تٔمۍ ووٚن تِمَن زِ مےٚ کیا چُھ ژےٚ مُقابلہٕ کٔرِتھ؟ {کیا افرائیم سٕندِ انگورن ہُند ژٹُن چُھ نہٕ ابیزر سٕندِ ونٹیج کھوتہٕ بہتر؟\n3.\\tخداین دِژ مدیان، عارب تہٕ زیبٕکۍ شہزادٕ تہٕ ژے ہٕندِس اتھس مَنٛز دِژمٕتۍ: تہٕ بہٕ کیا ہیوٚک تہٕ ژے ہٕندِس مقابلس مَنٛز کٔرِتھ۔ تمہ پتہ گوٚو تہند شرارت تس کُن کم، ییلہ تمۍ یہ وونمت اوس۔ {غصہٕ: ہیب۔ روح}\n4. تہٕ جدعون آو اردن کُن، {تہٕ} گٔیہِ سُہ تہٕ ترے ہتھ نفر یِم أمِس سٍتـ̡ ٲسۍ، بێہوش گٔیہِ، توتہِ گٔیہِ تِمن ہُند تعاقب کٔرِتھ۔\n5. تہٕ تٔمۍ ووٚن سوکوتھ کین نفرن دِیُن، بہٕ دِیُس میانہِ پٲروکار لُکن ہٕندِس روٹِس دِیُن۔ تکیازِ تِم چھِ بے ہوش گٔمٕتۍ، تہٕ بہٕ چُھس مدیانٕکۍ بادشاہ زیباح تہٕ زلمنا ہُند تعاقب کران۔\n6.\\tتہٕ سوکوتھ ہٕندِس شہزادن ووٚن زِ کیا زیبہ تہٕ زلمنہ سٕندِ اتھہٕ چھِہ وۅنۍ تۅہہِ ہٕندِس اتھس منز، زِ أسۍ پزِ چانہِ فوجس روٹی دِنہٕ؟\n7. تہٕ گدعونن ووٚن، تێمہِ کِنۍ ییلہ خداوند زیباح تہٕ زلمنا میٲنس اتھس منز دِژ، تیلہِ ژٔٹۍ بہٕ چانہِ ماز بیابانن ہٕندِس کانٹَو سٍتـ̡ تہٕ برِیَو سٍتـ̡ ژٔٹِتھ ۔ {ٹیئر: ہیب۔ تھریش}\n8.\\tتہٕ سُہ ووت تتہِ پینویلس نِش، تہٕ تِمن سٍتـ̡ کٔرٕن یِتھٕ پٲٹھۍ کتھ کرنہٕ۔\n9. تہٕ تٔمۍ ووٚن پینویل کین نفرن سٍتـ̡ تہِ وونُن، ییلہ بہٕ دُبارٕ امن سٍتـ̡ یِنہٕ تہٕ بہٕ پھُٹراوٕ یہِ مینار پھُٹراوُن۔\n10.\\tوۅنۍ ٲسۍ زیب تہٕ زلمنہ کرکورس منز، تہٕ تِہند لشکر ٲسۍ تِمن سٍتـ̡ تقریباً پنٛدہ ساس نفر، یُس مشرقٕکۍ بچن ہٕندِس سارِنٕے لشکرس منز باقٕے روٗدمُت، تکیازِ تتہِ گٔیہِ اکھ ہتھ ساس نفر یِمو تلوار تُلان۔ {مرد یُس...: یا، پریتھ کانہہ تلوار کڈان چُھ}\n11.\\tتہٕ گِدعون ووت تِمن ہٕندِس وتہِ سٍتـ̡ یِم نوبہ تہٕ جوگبیہ کِس مشرقس کُن خیمن منز روزان ٲسۍ، تہٕ لٔگِن میزبانس تھپھ کٔرِتھ، تکیازِ میزبان اوس محفوٗظ۔\n12.\\tییلہ زیباح تہٕ زلمنا ژٔلۍ، تٔمۍ لوٚگ تِمن پتہٕ، تہٕ رٔٹِن مدیانٕکۍ زٕ بادشاہ، زیباح تہٕ زلمنا تہٕ کورُن سارِنٕے لشکر پریشان۔ {discomfited: Heb. خوفزد}\n13.\\tتہٕ یواش سُند نیچو گِدعون آو آفتاب کھسنہٕ برونہہ جنگہٕ پیٹھٕ واپس۔\n14.\\tتہٕ رٔٹِتھ رٔٹِتھ أکِس نوجوانَس تہٕ پرژھُن أمِس سُکوتھٕکۍ شہزادٕ تہٕ تِمن ہٕندِس زِٹھہٕ تہٕ سَداہ نفر۔ {بیان کرنہٕ آمُت: ہیب۔ رِٹ}\n15.\\tتہٕ سُہ آو سُکوتھ کین نفرن نِش تہٕ وونُن، وُچھِو زِباح تہٕ زلمُنا، یِمن سٍتـ̡ ژےٚ ژےٚ سٍتـ̡ دِژمٕژ ٲس، زِ أسـ̡ چُھہ تُہندِس اتھس مَنٛز، زِ أسـ̡ پَنٕنـ̡ تُہٕندِس نفرن روٹی دِنہٕ یِنـ̡ یِمن ہٕندِس اَتھَس مَنٛز؟\n16.\\tتہٕ تٔمۍ نیو شہرٕکۍ زِٹھۍ تہٕ بیابانن تہٕ برِیَن ہٕندۍ کانٹ، تہٕ تِمن سٍتـ̡ ہیٚچھناوُن سُکوتھ ہٕندِس نفرس سٍتـ̡ ۔ {ہیچھناوُن: ہیب۔ زاننہٕ خٲطرٕ بناونہٕ آمُت}\n17.\\tتہٕ تٔمۍ دِژ پینویلُک مینار تہٕ مارِن شہرٕکۍ نفر۔\n18.\\tتَمہِ وۆنُن زَباح تہٕ زَلمنَس زِ تِم کَمہِ قٕسمٕکۍ لُکھ یِم تِمَن تِمَن مَنٛز مٲرِتھ چھِ۔ تہٕ تِمو دِژ جواب، یِتھے پٲٹھۍ تُہۍ {چھِ}، تِتھے پٲٹھۍ ٲسۍ تِم؛ پرٮ۪تھ اکھ اوس بادشاہ سٕنٛدٮ۪ن شُرین ہِش ہِش آسان۔ {مشابہ...: ہیب۔ فارم مطٲبق وغیرہ}\n19.\\tتہٕ تٔمۍ ووٚن، تِم ٲسۍ میٲنۍ بٲے، میانہِ ماجہ ہٕندِ نیچوۍ تہِ: یێلہِ تہٕ یێلہِ ژے یِم زندٕ بچٲوِتھ، بہٕ کٔرٕ نہٕ ژے مارُن۔\n20.\\tتہٕ تٔمۍ ووٚن یتھرس پنُن گۅڈنیُک زامُت، اوپ، {تہٕ} مارُن۔ مگر نوجوانن کٔر نہ تلوار، تکیازِ تس اوس کھوژان، تکیازِ سہ اوس وُنہِ تہِ جوان۔\n21.\\tزیباح تہٕ زلمنا وۆن، ووٚتھ تہٕ اسہِ پیٹھ پٔسِو، تکیازِ یِتھٕ پٲٹھۍ انسان چُھ، تِتھے پٲٹھۍ چھُ تٔمۍ سٕنز طاقت تہِ۔ تہٕ جدعون ووٚتھ، تہٕ زیباح تہٕ زلمنا مٲرِتھ تہٕ نِیُن تِم زیور یِم تِمن ہٕندِس اونٹَن ہٕندِس گردنَس پیٹھ ٲسۍ۔ {زیورات: یا، زونہِ ہیو زیورات}\n22. اَمہِ پَتہٕ ووٚن اسرٲیلِیو گِدعونس زِ تُہۍ تہٕ پنٕنِس نیچوِس تہٕ پننِس نیچوِس سٕندِس نیچوِس پیٹھ تہِ کٔرٕکھ حُکوٗمَت، تِکیازِ ژے چھُکھ اسہِ مدیان سٕندِ اتھہٕ نِش بچاومُت۔\n23. تہٕ جدعونن ووٚن تِمن زِ بہٕ کَرٕ نہٕ تۅہہِ پیٹھ حکوٗمت، تہٕ نہ کرٕ میون نیچو تہٕ تۅہہِ پیٹھ حکوٗمت۔\n24. تہٕ جدعونن ووٚن تِمَن زِ بہٕ کَرٕ ژےٚ نِش اکھ درخواست زِ ژٕ دِیہ مےٚ پرٮ۪تھ أکِس شِکارٕچ بالہٕ۔ (تکیازِ تمن ٲس سنہری بالہٕ، تکیازِ تم ٲسۍ اسماعیلۍ۔)\n25.\\tتہٕ تِمو دِژ جواب، أسۍ دِیہ پننہِ مرضی سٍتـ̡ {تِم}۔ تہٕ تِمو پھٔہلٲوِکھ اکھ پلو، تہٕ اَتھ منٛز ترٛٲوِکھ پرٮ۪تھ أکِس شِکارٕچ بالہٕ۔\n26.\\tتہٕ سۅنہٕ بالہِ ہُند وزن یُس تٔمۍ درخواست کٔر، سُہ اوس ساس ستھ ہتھ {شیکل} سۄن۔ زیورات تہ کالر تہ واگن پوشہ یُس مدیان کین بادشاہن پیٹھ {اوس} تہ زنجیرن سیتۍ یُس تہندٮن اونٹٮن ہنزن گردن منز {اوس}۔ {کالر: یا، میٹھۍ جواہرات}\n27.\\tتہٕ گدعونن بنوو اَمہ سٍتـ̡ اکھ ایفوڈ تہٕ تھووُن پننِس شہرس مَنٛز، عفراہس مَنٛز، تہٕ سارِوٕے اِسرٲیل گٔیہِ اَتھ پَتہٕ کُنہِ سٍتـ̡ گِدعونس تہٕ تٔمۍ سٕندِس گَرَس مَنٛز پھنس۔\n28.\\tیِتھے پٲٹھۍ آو مدیان بنی اسرائیل برونہہ کنہِ زیر کرنہٕ، یُتھ زن تِمو کلہٕ تُلِتھ تُلِتھ۔ تہٕ گِڈیون سٕندِس دۅہس منز اوس مُلُک ژتٲجی ؤری خاموشی منز۔\n29.\\tتہٕ یواش سُند نیچو یرُبعل گۆو پننِس گرس مَنٛز روزُن۔\n30. تہٕ جدعونس زاے تٔمۍ سٕندِس جسمس منز ترے تہٕ داہ نیچوۍ، تکیازِ أمس آسہٕ واریاہ زنانہٕ۔ {تٔمۍ سٕندِ...: ہیب۔ پننہ رانہ منزہ نیبر نیران}\n31.\\tتہٕ تٔمۍ سٕنز لونڈی یۄس شیخمس مَنٛز ٲس، أمِس زاو أمِس اکھ نیچو تہِ، یٔمِس ناو تٔمِس ابیمیلک ناو وَنُن۔ {وننہٕ آمُت: ہیب۔ سیٹ}\n32.\\tتہٕ یوآش سُند نیچو گِدعون گۆو بُزرگ وٲنسہِ منز، تہٕ آو پننِس مٲلِس یوآش سٕندِس قبرس مَنٛز دفن کرنہٕ۔\n33.\\tتہٕ یێلہِ گِدعونس مٔرِتھ سپُد یہِ سپُد زِ بنی اسرٲیلِس پھیُر پھیُر تہٕ بعلیم سٍتـ̡ بێیہِ بێرِتھ پَنُن خدا۔\n34. تہٕ بنی اسرٲیلِس اوس نہٕ خداوند پنُن خدا یاد، یٔمۍ تِم پرٮ۪تھ طرفہٕ تِمن سارِنٕے دُشمنن ہٕندِ اتھہٕ نِش بچٲومٕژ ٲس۔\n35.\\tیِمو کٔر یروبعل سٕندِس گرس سٍتـ̡ رحمدٲری یُس تٔمۍ اسرٲیلس سٍتـ̡ ہٲومٕژ ٲس۔","1.\\tتہٕ ابیمیلک نیچو یروبعل سُند نیچو شیکیمس نِش پننہِ ماجہ ہٕندِس باین نِش تہٕ تِمن سٍتـ̡ تہٕ کورُن ماجہ ہٕندِس مٲلہِ سٕندِس گرس سٍتـ̡ سارِنٕے عیالس سٍتـ̡ کتھ باتھ کٔرِتھ وونُن،\n2.\\tکتھ کرُن، بہٕ چھُس ژے شیکیم کین سارِنٕے نفرن ہٕندِس کنن منز، کیا تۅہہِ خٲطرٕ چھا بہتر، یا تہٕ یروبعل سٕندِ سارِنٕے نیٚچوۍ، یِم تریہ تہٕ داہ نفر چھِ، تۅہہِ پیٹھ راج کٔرِتھ، یا سُہ چُھہ تۅہہِ پیٹھ راج کرُن؟ یہ تہِ یاد تھاوُن زِ بہٕ چُھس تُہند اڈجہ تہٕ تُہند ماز۔ {کیا...: ہیب۔ اصل کیا چُھ؟ کیا وغیرہ}\n3.\\tتہٕ تٔمۍ سٕنزِ ماجہ ہٕندِس بٲے کٔر أمِس مُتلق یِم سارِنٕے لفٕظ شیکیم کین سارِنٕے نفرن ہٕندِس کنن منز، تہٕ تِہُند دِل گٔیہِ ابیملکٕچ پیروی کرنہٕ خٲطرٕ۔ تکیازِ تِمو ووٚن، سُہ چُھ سون بوے ۔ {پیروی کرنہٕ خٲطرٕ: ہیب۔ پتہٕ}\n4.\\tتہٕ تمِس دِژ بعلبیرتھ کِس گرٕ منزٕ ترے تہٕ داہ رۄپہٕ رۄپہٕ، یِمو سٍتـ̡ ابیمیلک بیکار تہٕ ہلکہٕ نفر رٔٹۍ، یِم أمِس پتہٕ گٔیہِ۔\n5.\\tتہٕ سُہ گۆو پننِس مٲلہِ سٕندِس گَرَس منز، تہٕ مارِن پننین بٲے یروبعل سٕندِ نیچوۍ، یُس تریہ تہٕ داہ نفر ٲسِتھ، أکِس کٔنِس پیٹھ۔ تکیازِ تمۍ اوس پانس ژوٗر۔\n6.\\tتہٕ شیکیمٕکۍ سٲری مرد جمع گٔیہ، تہٕ میلو سُند سورُے گرٕ گٔیہ، تہٕ بنووُکھ ابیمیلک بادشاہ، تتھ ستونہٕ کِس میدانس سٍتـ̡ یُس شیکیمس مَنٛز اوس۔ {سادٕ: یا، بلوط}\n7.\\tتہٕ ییلہ تِمو جوتھمس ووٚن، سُہ گوٚو تہٕ گٔیہِ گریزِم کِس تھزرس پیٹھ، تہٕ تٔمۍ کٔرٕن پنٕنۍ آواز تھوٚد تہٕ وُنُن تہٕ وونُن، اے شیکیمٕکۍ لوکو، یُتھ خدا کرِ تۅہہ بوزنہٕ۔\n8.\\tکُلۍ دراو تمن پیٹھ اکھ بادشاہ مسح کرنہٕ خٲطرٕ۔ تہٕ تِمو ووٚن زیتون کُلِس سٍتـ̡ اسہِ پیٹھ راج کرُن۔\n9.\\tمگر زیتون کُلِس ووٚن تِمن زِ بہٕ پزیا پنُن چربی تراوُن، یُس میانہِ ذریعہٕ خدایہ تہٕ انسانس عزت کران چھِ، تہٕ کُلٮ۪ن پیٹھ ترقی دِنہٕ خٲطرٕ گژھُن؟ {گژھو...: یا، باقی کُلٮ۪ن خٲطرٕ ہیوٚر بۄن گژھِ}\n10.\\tتہٕ کُلۍ ووٚن انجیر کُلِس وَنُن، آ تہٕ اسہِ پیٹھ راج کرُن۔\n11.\\tمگر انجیر کُلِس ووٚن تِمن زِ بہٕ پزیا پنُن مٹھاس تہٕ اصل پھل تراوُن تہٕ کُلٮ۪ن پیٹھ ترقی دِنہٕ خٲطرٕ؟\n12. پتہٕ ووٚن کُلۍ کُلِس کُلِس کُن، یێلہِ چُھہ اسہِ پیٹھ بادشاہی کٔرِو۔\n13.\\tتہٕ بیلن ووٚن تِمن زِ بہٕ پزیا پنُن شراب، یُس خدایہ تہٕ انسانس خۅش کران چھُ، تہٕ گژھ کُلٮ۪ن پیٹھ ترقی دِنہٕ خٲطرٕ؟\n14.\\tاَمہِ پتہٕ ووٚن سارِنٕے کُلۍ کُلِس کُن، یِمو تہٕ اسہِ پیٹھ کٔرِو بادشاہت۔ {بریمبل: یا، تھیسٹل}\n15.\\tتہٕ کُلٮ۪ن ووٚن کُلٮ۪ن زِ یێلہِ پٔزۍ پٲٹھـ̡ ژے مے پانس پیٹھ بادشاہ مسح کٔرِو، {تیلہِ} یِو میٲنِس ژھایہِ پیٹھ بھروسہ تہٕ اگر نہٕ تیلہِ گژھہِ نار نیرُن تہٕ لبنان کِس دیودارس کھٮ۪نہٕ۔\n16. تێلہِ چُھہ تێلہِ یێلہِ پٔزۍ پٲٹھـ̡ تہٕ اَمہ سٍتـ̡ چُھہ ابیمیلک بادشاہ بنوومُت، تہٕ یێلہِ ژے یروبعل تہٕ تٔمۍ سٕندِس گرس سٍتـ̡ رٔژ سٍتـ̡\n17.\\t(میانہِ مٲلہِ سٍتـ̡ لوٚڈ تۅہہِ خٲطرٕ، تہٕ کٔرٕن ژے مدیان سٕندِ اتھہٕ نِش نجات دِنہٕ: {ایڈونچر...: حب۔ تٔمۍ سٕنٛز زندگی ترٛاو}\n18.\\tتہٕ تُہۍ چھِو اَز دۅہہ میٲنِس مٲلہِ سٕندِس گرس خلاف کھڑا گٔمٕتۍ، تہٕ تٔمۍ سٕندِس نیچوِس تریہ تہٕ داہ نفر مٲرِتھ أکِس کٔنہِ پیٹھ، تہٕ بنووُکھ ابیملک، یُس پننہِ نوکرِ ہُند نیچو چھُ، شیکم کین مردن پیٹھ بادشاہ بنووومُت، کیازِ سُہ چُھ تُہند بوے ۔)\n19. یێلہِ تێلہِ یێلہِ یروبعلس تہٕ تٔمۍ سٕندِس گرس سٍتـ̡ پٔزۍ پٲٹھـ̡ تہٕ پٔزۍ پٲٹھـ̡ سٍتـ̡ پٔزۍ پٲٹھـ̡ سٍت\n20.\\tمگر اگر نہٕ تیلہِ گژھہِ ابیمیلکہٕ سٍتـ̡ نار نیرُن، تہٕ شیکیمٕکۍ مرد تہٕ مِلو سٕندِس گرس کھٮ۪نہٕ۔ تہٕ شیکیم کِس مردو نِش تہٕ میلو سٕندِ گرٕ سٍتـ̡ نار نیرُن تہٕ ابیمیلک کھٮ۪نہٕ۔\n21.\\tتہٕ یوتھم ژوٚل تہٕ ژوٚل تہٕ بیٖرس کُن تہٕ روٗد اَتہِ روزُن، پننِس بٲیِس ابیمیلک سٕندِ خوفہٕ سٍتـ̡ ۔\n22. ییلہ ابیمیلک تریہ ؤری اسرائیلس پیٹھ حکومت کٔر،\n23. پتہٕ سوز خداین ابیمیلک تہٕ شیکیم کین مردن درمیان اکھ بد روح۔ تہٕ شیکیمٕکۍ نفرو کوٚر ابیمیلکس سٍتۍ غداری سٍتۍ:\n24.\\tیُس یروبعل سٕندِس تریہ تہٕ دہن نیچوین سٍتـ̡ سپدُن یُس ظُلم سپدُن، تہٕ تِہُند خوُن ییہِ تِہندِس بٲیِس ابیمیلخس پیٹھ تراونہٕ، یٔمۍ تِم مارنہٕ آو۔ تہٕ شیکیم کین نفرن پیٹھ، یمو أمس پننین باین ہٕندِس مارنس منٛز مدد کٔر۔ {مدد...: ہیب۔ مارنہٕ خٲطرٕ کٔرٕن پنٕنۍ اتھہٕ مضبوٗط}\n25.\\tتہٕ شیکیمٕکۍ نفرو تھوو پہاڑن ہٕندِس تھزرس پیٹھ أمِس خٲطرٕ لُٹنہٕ، تہٕ یِمو لُٹٲوۍ تِمن ہٕندِ طرفہٕ یِنہٕ وٲلِس سارِنٕے چیٖزس لُٹِتھ، تہٕ یہِ آو ابیمیلک وَننہٕ۔\n26.\\tتہٕ گال یُس عیبد سُند نیچو آو پننین باین سٍتـ̡ تہٕ ووت شیکیمس نِش۔\n27.\\tتہٕ تِم گٔیہِ کھاہن مَنٛز، تہٕ کٔرٕکھ پنٕنۍ انگور جمع کٔرِتھ، تہٕ کٔرٕکھ خۅش تہٕ گٔیہِ پننِس خدایہ سٕندِس گَرَس مَنٛز، تہٕ کھٮ۪وان تہٕ کٔرٕکھ ابیملکَس لعنت۔ {مٔرۍ: یا، نغمہٕ}\n28.\\tتہٕ عبید سٕندِس نیچوِس جال ووٚن، ابیملک کُس چُھہ تہٕ کُس چُھہ شیکیم، زِ أسـ̡ پَزِ تٔمِس سٕنز خدمت کرٕنـ̡؟ {یہ} چھُنہٕ یروبعل سُند نیٚچُو؟ تہٕ زیبُل تٔمۍ سُند افسر؟ شیکیم سٕندِس مٲلِس ہَمور سٕندِس مردَن ہٕنز خدمت کٔرِو: کیازِ پَزِ أسۍ أمِس خدمت کٔرِتھ؟\n29. تہٕ کاش یہ لُکھ میانہِ اتھس تل آسن! اَمہِ پَتہٕ کَرٕ بہٕ ہٹٲوِتھ اَبیمیلِک۔ تہٕ تٔمۍ ووٚن ابیمیلکس زِ پَنُن لشکر ہُرراوُن تہٕ نٮ۪بر نیرُن۔\n30.\\tتہٕ ییلہ شہرٕکۍ حکمران زبُل عیبد سٕندِس نیچوِس گال سٕنز کتھ بوز، تٔمِس ہُند شرارت ہیوٚت دِنہٕ۔ {کٔرِتھ: یا، گرم}\n31.\\tتہٕ سوٗزۍ ابیمیلکس نِش پیغمبر تہٕ وونُن زِ وُچھو، ایبید سُند نیچو گال تہٕ تٔمۍ سٕندِس بٲے یِن شیکیمس کُن۔ تہٕ وچھ، تم چِھ شہر توے خلاف قلعہ بندی کران۔ {پرائیویلی: ہیب۔ چالاکی سان یا، تورماہ کُن}\n32.\\tتێلہِ وۆن رٲژ ژے تہٕ یُس لُکھ پانس سٍتـ̡ چُھہ، تہٕ میدانس مَنٛز پیارٕ کٔرِتھ:\n33.\\tتہٕ یہ گژھہِ زِ صبحس ییلہ آفتاب کھسُن، سُلہِ وۅتھان تہٕ شہرس کُن نیرُن، تہٕ وُچھِو، ییلہ سُہ تہٕ أمِس سٍتـ̡ لُکھ یُس تۅہہِ سٍتـ̡ نیرِ، تیلہٕ کٔرِو تِمن سٍتـ̡ یُتھ موقعہٕ میلہِ۔ {یتھہ پاٹھۍ ژیہ کرُن...: ہیب۔ یتھہ پاٹھۍ چانہِ اتھہ لٔبِتھ}\n34.\\tتہٕ ابیمیلک ووٚتھ تہٕ سارِوٕے لُکھ یِم أمِس سٍتـ̡ رٲژ ٲس، تہٕ تِمو کٔر ژۄن جمٲژن منز شیکیمس خلاف انتظار۔\n35.\\tتہٕ گال نیچو عبید سُند نیچو درٛاو تہٕ ووت شہرٕ کِس دروازس منز اژنہٕ کِس دروازس منز، تہٕ ابیمیلک ووٚتھ تہٕ یِم لُکھ أمِس سٍتـ̡ ٲسۍ، پیارٕ نِش گٔیہِ۔\n36. تہٕ ییلہ گال لُکھ وُچھ، تٔمۍ ووٚن زبولس زِ وُچھِو لوکھ بالہٕ پیٹھٕ بۄن وسان۔ تہٕ زبُلن ووٚن أمِس زِ ژے چھُکھ پہاڑن ہُند ژھایہ وُچھان یِتھ زن تِم انسان آسن۔\n37.\\tتہٕ گال کٔر بییہ کتھ تہٕ وونُن، وُچھ تتہِ چھِ زمینہِ منزۍ لوکھ یِوان، تہٕ بیاکھ اکھ جمٲژ ییہ میوننم کِس میدانس منز۔ {منزم: ہیب۔ ناف} {Meonenim: یا، زمانک حوالہٕ}\n38.\\tاَمہِ پَتہٕ ووٚن زِبُل أمِس کَتہِ چُھہ تُہُند ٲس، یَتھ سٍتـ̡ ژے وَنُن زِ أسـ̡ کُس چُھہ ابیمیلِک، یێلہِ أسـ̡ أمِس خدمت کرٕنـ̡ ۔ {کیا یہ} چھُنہٕ تِم لُکھ یِمن تۅہہ حقارت کٔرمٕژ چھِ؟ نٮبر نیرُن، بہٕ چھُس وۅنۍ دعا کران تہٕ تمن سٍتۍ لڑان۔\n39.\\tتہٕ گال دراو شیکیم کین نفرن برونہہ کُن، تہٕ لوٚگ ابیمیلکس سٍتـ̡ ۔\n40.\\tتہٕ ابیملکن لوٚگ أمِس پتہٕ، تہٕ سُہ ژوٚل أمِس برونہہ کُن، تہٕ واریاہ گٔیہِ زخمی، {حتیٰ کہ} دروازس منز اژنہٕ تام۔\n41.\\tتہٕ ابیمیلک اوس ارومہ ہس مَنٛز روزان: تہٕ زبولن کٔر گال تہٕ تٔمۍ سٕندِس بٲے کٔڑِتھ زِ تِم گژھن نہٕ شیکیمس مَنٛز روزنہٕ۔\n42.\\tتہٕ پَگہہ سپُد یہِ زِ لُکھ گٔیہِ کھاہس مَنٛز۔ تہٕ تِمو ووٚن ابیمیلک۔\n43. تہٕ تٔمۍ رٔٹِتھ لُکھ تہٕ تِم ترٚین جمٲژن مَنٛز تقسیٖم کٔرِتھ، تہٕ وُچھُن لُکھ شہرٕ منزٕ نیبر۔ تہٕ سُہ ووت تِمن خٕلاف تہٕ دِژُن تِمن ہٕندِس خٕلاف۔\n44.\\tتہٕ ابیمیلک تہٕ یُس کمپنی أمِس سٍتـ̡ ٲس، دٔژ برونہہ کُن تہٕ کھٔژ شہرٕ کِس دروازس منز اژنہٕ: تہٕ دۅشوے {باقٕے} کمپنیہِ ژٔلِتھ سارِنٕے {لُک} یِم کھہَن مَنٛز ٲسۍ، تہٕ مارٕکھ تِم مٲرِتھ۔\n45.\\tتہٕ ابیمیلک لوٚڈ تمہِ دۅہہ شہرس خٕلاف۔ تہٕ تٔمۍ کوٚر شہرس پیٹھ قبضہٕ، تہٕ مٲرِن تِم لُکھ یِم اَتھ منٛز ٲسۍ، تہٕ شہر مار دِژُن تہٕ ووت نونہٕ سٍتۍ۔\n46.\\tتہٕ ییلہ شیکیم کِس مینار ہٕندِس سارِنٕے نفرو بوز، تِمو ژاو دیوتا بیرتھ سٕندِس گرس مَنٛز۔\n47.\\tتہٕ ابیمیلکس آو وننہٕ زِ شیکیم کِس برجٕکۍ سٲری نفر آیہ جمع کرنہٕ۔\n48.\\tتہٕ ابیمیلک ووت أمِس زلمون کِس پہاڑس تام، سُہ تہٕ تِم سٲری لُکھ یِم أمِس سٍتـ̡ ٲسۍ۔ تہٕ ابیمیلکن رٔٹ پننس اتھس منز اکھ کلہٕ، تہٕ کُلیٛو منزٕ ژٹُن اکھ کلہٕ، تہٕ تھووُن پننِس پھیکس پیٹھ، تہٕ وونُن لوکن یُس میہ سٍتـ̡ وُچھمُت چُھ، یُس ژے مے کران چُھ، جلدی کٔرِو، {تہٕ} یُتھ میہ {کورمُت}۔ {میہ کرُن: ہیب۔ مے چُھ کورمُت}\n49.\\tتہٕ سارِوٕے لوکو ژٔٹِتھ ژٔٹِتھ پرٮ۪تھ أکِس انسانس سٕندِس لٔگِس تہٕ لٔگِتھ لٔگِتھ تہٕ دِژُکھ تِمن ہُند تھپھ۔ یِتھٕ پٲٹھۍ گٔیہِ شیکیمٕکۍ مینار ہٕندۍ سٲری مرد تہِ، تقریباً اکھ ساس مرد تہٕ زنانہٕ۔\n50.\\tپتہٕ گوٚو ابیمیلک تھیبزس کُن، تہٕ کوٚرُن تھیبیزس خلاف ڈیرٕ ترٲوِتھ تہٕ کوٚرُن یہِ قبضہٕ۔\n51.\\tمگر شہرس اندر اوس اکھ مضبوط مینار، تہٕ تتہِ ژٔلِتھ سارِنٕے مرد تہٕ زنانہٕ تہٕ شہرٕکۍ سٲری ژٔلِتھ تہٕ تِمن ہٕندِس خٲطرٕ بند کٔرِتھ تہٕ تِمن ہٕندِس مینار کِس تھزرس تام واتناوُن۔\n52.\\tتہٕ ابیمیلک آو مینارس نِش تہٕ لوٚگ اتھ خلاف تہٕ دِژ مینار کِس دروازس تام زالنہٕ خٲطرٕ۔\n53.\\tتہٕ أکۍ زنانہِ ترووُن ابیمیلک سٕندِس کلس پیٹھ مِلہٕ کٔنِس کُنہِ ٹُکرٕ تہٕ سارِوٕے تٔمۍ سٕندِس کلہٕ کھورِ پھُٹراونہٕ خٲطرٕ۔\n54.\\tاَمہِ پتہٕ بُلوو تٔمِس نوجوانَس پنُن ہتھیار بردار تہٕ وونُن پنٕنۍ تلوار تہٕ مٲرِتھ مٲرِتھ زِ مرد چھُنہٕ میانہِ مُتلِق وَنُن، أکِس زنانہِ ہُند مٲرِتھ مٲرِتھ۔ تہٕ أمۍ سٕنٛدِ نوجوانَن دِژ أمِس ژٔٹِتھ تہٕ سُہ موٗد۔\n55.\\tییلہ اسرٲیلِیو وُچھ زِ ابیمیلک چُھ موٗدمُت، تِمو دِژ پرٮ۪تھ أکِس شخصس پننہِ جایہِ کُن۔\n56. یِتھٕ پٲٹھـ̡ کٔر خداین ابیمیلک سٕنز بدکاری یُس تٔمۍ پننِس مٲلِس سٍتـ̡ پننین ستتھ باین ہُند قتل کٔرِتھ کٔر:\n57.\\tتہٕ شیکیم کین انسانن ہٕنز سارِنٕے بُردی کٔر خداین تہندِس کلس پیٹھ، تہٕ یِمن پیٹھ آو یروبعل سٕندِس نیچو یوتھام سٕنز لعنت۔","1. تہٕ ابیمیلک پَتہٕ ووت اسرٲیلِس بچاونہٕ خٲطرٕ، یُس ڈوڈو سُند نیچو، یُس اِساکر سُند نیچو اوس۔ تہٕ سُہ اوس کوہ افرائیم کِس شامیرس مَنٛز روزان۔ {دفاع: یا، ڈیلیور: ہیب۔ محفوظ کٔرِو}\n2.\\tتہٕ تٔمۍ کٔر اسرٲیلُک فیصلہ وُہن تہٕ تریٛوو ؤرین تہٕ مٔرِتھ سپُد شامیرس مَنٛز دفن کرنہٕ۔\n3.\\tتہٕ أمِس پَتہٕ ووت یائر، یُس اکھ جلعادی، تہٕ کوٚرُن اسرٲیلُک وُہُن وُہُن وُہُن وُہُن۔\n4.\\tتہٕ أمِس ٲسۍ ترٕہ نیچوۍ یِم ترٕہن گَرٮ۪ن پیٹھ سوار ٲسۍ، تہٕ تِمن ٲسۍ ترٕہ شہر، یِمن از تام حَوثجیر ونان چھِ، یِم جلعاد کِس سرزمینس مَنٛز چھِ۔ {Havothjair: یا، Jair کِس گام}\n5.\\tتہٕ یَر موٗد تہٕ سُہ آو کامنس مَنٛز دفن کرنہٕ۔\n6. تہٕ بنی اسرٲیلِو کٔر خداوند سٕندِس نظرس مَنٛز دُبارٕ بُر، تہٕ کٔرٕکھ بعلیم، اشتاروت، تہٕ شام کین دیوتاہن تہٕ زِدونٕکۍ دیوتاہن تہٕ موآب کِس دیوتاہن تہٕ عمون کِس اولادَن ہٕندِس دیوتاہن تہٕ فلسطینن ہٕندِس دیوتاہن ہٕنز خدمت، تہٕ کٔرٕکھ نہٕ خداوند سٕنز خدمت۔\n7.\\tتہٕ خداوند سُند غصہٕ اوس اسرٲیلِس سٍتـ̡ سٍتـ̡ سٍتـ̡ تہٕ کُنُن تِم فلسطینن ہٕندِس اتھس تہٕ عمون کِس بچن ہٕندِس اتھس مَنٛز۔\n8. تہٕ تمہ ؤری کٔر تِمو اسرائیلٕکۍ بُلِس ناراض تہٕ ظُلم: ارداہ ؤری، اِسرٲیلٕکۍ سارِنٕے اولاد یِم امورین ہٕندِس سرزمینس مَنٛز اردن کِس دوٚیمہِ طرفہٕ ٲسۍ، یُس جلعادس مَنٛز {چُھ}۔ {مظلوم: ہیب۔ کرشڈ}\n9.\\tامہِ علاوٕ گٔیہِ عمون سٕندِ بچہٕ یُوداہَس سٍتـ̡ یہوداہَس سٍتـ̡ تہٕ بنیمنَس خٕلاف، تہٕ افرائیم سٕندِس گھرس خٕلاف۔ تہ اسرٲیلِس اوس پریشان گومُت۔\n10. تہٕ بنی اِسرٲیلِیو کٔر خداوند سٕندِس نِش فریاد زِ أسـ̡ چُھہ تۅہہِ سٍتـ̡ گۅناہ کورمُت، دۅنوے کیازِ أسـ̡ چُھہ پنُن خدا ترٲومُت تہٕ بعلیمٕچ خدمت کٔرمٕژ۔\n11. تہٕ خداوند ووٚن بنی اسرٲیلِس نِش، {بہٕ چُھس نہٕ تۅہہِ مصری نِش، اموریو نِش، عمون سٕندِس اولادس نِش تہٕ فلسطینن نِش نجات دِژمٕژ؟\n12.\\tزیدونیو تہٕ امالیکیو تہٕ ماونی تہِ کٔر تۅہہِ پیٹھ ظلم۔ تہٕ ژے کٔر میہ وُن، تہٕ مے کٔر ژے تِہندِ اتھہٕ نِش نِش۔\n13.\\tتوتہِ چھُکھ میہ ترٲومُت، تہٕ باقین دیوتاہن ہٕنز خدمت کٔرِتھ، اَمہِ مۄکھٕ کٔرٕ نہٕ بہٕ ژےٚ مزید نجات دِنہٕ۔\n14. گژھ تہٕ تمن دیوتاہن نِش کٔرِو یِم ژٲرِمٕتۍ چھِ۔ تِم دِیُن تُہٕندِس مصیبت وِزِ نجات دِنہٕ۔\n15. تہٕ بنی اسرٲیلیو ووٚن خداوند سٍتـ̡ زِ أسـ̡ چُھہ گۅناہ کورمُت: یُس تہٕ تۅہہِ سٍتـ̡ بہتر باسان چُھہ تہٕ کٔرِو اسہِ سٍتـ̡ یُس تہِ چُھہ تُہٕندِس سٍتـ̡ سٍتـ̡ سٍتـ اسہِ کٔرِو نجات دِنہٕ، أسۍ چھِ از دۅہہٕ ژےٚ دُعا کران۔ {سیمیتھ...: ہیب۔ چُھس چُھس اچھن منز اچھ}\n16.\\tتہٕ تِمو کٔرِکھ پانس منزٕ عجیب دیوتاہن ہُند دُبارٕ تہٕ کٔرٕکھ خداوند سٕنز خدمت، تہٕ تٔمۍ سُند روح گۆو اسرٲیلِچ مصیبت خٲطرٕ غم۔ {عجیب...: ہیب۔ اجنبین ہٕندۍ دیوتا} {غمگین: ہیب۔ ژھوٚٹ}\n17.\\tامہ پتہ آیہ عمون سٕندِ شُرۍ جمع کٔرِتھ جلعادس مَنٛز ڈیرٕ ترٲوِتھ۔ تہٕ بنی اسرٲیلِو جمع تہٕ لوٚگ مزپہس مَنٛز ڈیرٕ۔ {جمع: ہیب۔ کٔرۍ}\n18.\\tتہٕ جلعادٕکۍ لوکو ووٚن اَکھ أکِس أکِس سٍتـ̡ کُس انسان چُھہ یُس عمون سٕندِس شُرین سٍتـ̡ لڑُن شروع کرِ۔ سُہ آسہِ گلعاد کین سارنٕے بسکینن ہُند سردار۔","1.\\tیفتاح گلعاد اوس اکھ طاقتور بہادر انسان، تہٕ سُہ اوس أکِس بدکار سُند نیٚچُو، تہٕ گلعاد اوس یفتاح زٲومُت۔ {یفتاح: Gr. Jephthae} {اکھ بدکار: ہیب۔ اکھ زنانہٕ اکھ بدکار}\n2. تہٕ گلعاد سٕنزِ زنانہِ زاے أمِس نیٚچوۍ۔ تہٕ تٔمۍ سٕنزِ خانٛدارِنہِ ہٕندِ نیچوۍ گٔیہِ بٔڑۍ، تہٕ تِمو کٔر یفتاح کٔڈِتھ تہٕ وونُن تٔمِس زِ ژے گژھ نہٕ سٲنِس مٲلہِ سٕندِس گرس مَنٛز وٲرث۔ تکیازِ ژے چھکھ أکِس عجیب زنانہِ ہُند نیچو۔\n3. اَمہِ پَتہٕ ژوٚل یفتاح پننٮ۪ن باین نِش تہٕ بٔسِتھ گٔیہِ تٔمِس سٍتـ̡ یفتاہس نِش بیکار لُکھ جمع تہٕ گٔیہِ أمِس سٍتـ̡ نٮ۪بر۔ {از: ہیب۔ بُتھِس پیٹھ}\n4. تہٕ ووت وقتس سٍتـ̡ سپُد زِ عمون سٕندیو اولادو کٔر اسرٲیلِس سٍتـ̡ جنگ۔ {عملہِ منز...: ہیب۔ دۅہن پتہٕ}\n5. تہٕ یِتھٕ پٲٹھۍ سپُد یێلہِ عمون سٕندیو اولادَو اسرٲیلِس سٍتـ̡ جنگ کٔر، جلعادٕکۍ زِٹھۍ گٔیہِ یفتاح طوب کِس سرزمینہٕ منزٕ نِنہِ۔\n6. تہٕ تِمو ووٚن یفتاہس زِ یِمو تہٕ بٔنِو سٲنۍ کپتان، یُتھ أسۍ عمون سٕندٮ۪ن شُرین سٍتـ̡ لڑٲے کٔرِتھ۔\n7. تہٕ یفتاہن ووٚن جلعاد کین بزرگن زِ کیا ژیہ نہٕ میہ سۭتۍ نفرت کٔرِتھ تہٕ کٔرِکھ میہ مٲلہِ سٕندِ گرٕ منزٕ کٔڑِتھ؟ تہٕ ژٕ کیازِ چھِو وُنۍ میہ نِش آمٕتۍ؟\n8.\\tتہٕ گلعادٕکۍ بزرگو ووٚن یفتاہس زِ تێلہِ چُھہ أسۍ وُنہِ ژے کُن پھیرِتھ، یُتھ ژے گژھِو اسہِ سٍتـ̡ تہٕ عمون کین شُرین خلاف جنگ کٔرِتھ تہٕ گِلعاد کین سارِنٕے بسکینن ہٕندِس سٍتـ̡\n9. تہٕ یفتاہن ووٚن جلعاد کین بزرگن زِ اگر تم میہ دُبارٕ گرٕ انِتھ عمون کین بچن خلاف لڑنہٕ خٲطرٕ، تہٕ خداوند کرٕ تِم میانہِ برونہہ کنہِ بچاون، کیا بہٕ بنہٕ تُہند سر؟\n10. تہٕ گلعادٕکۍ بزرگو ووٚن یفتاہس زِ خداوند گژھہِ اسہِ درمیان گواہ روزُن، اگر أسۍ تہندِ کلامَس مُطٲبق یہِ نہٕ کرِ۔ {گواہ...: ہیب۔ اسہِ درمیان بوزن والۍ}\n11. پتہٕ گۆو یفتاح جلعاد کین بزرگن سٍتـ̡ تہٕ لوکو بنوو أمِس کلہٕ تہٕ تِمن ہٕندِس کُنہِ کُنہِ سٍتـ̡ تہٕ یفتاہن کٔر مِزپہ مَنٛز خداوند سٕندِس برونہہ کُن پنٕنـ̡ سٲری کلام۔\n12.\\tتہٕ یفتاہن سوٗزۍ عمون کِس اولادس نِش پیغمبر تہٕ وونُن زِ ژے کیا چُھکھ مےٚ سٍتـ̡ میانہِ سرزمینس مَنٛز لڑنہٕ خٲطرٕ آمُت؟\n13.\\tتہٕ عمون کِس اولادَن ہٕندِس بادشاہن دیُت یفتاح کین رسولن جواب، کیازِکہ اسرائیلن نِش میٲنۍ زمین، ییلہ تم مصرہٕ منزٕ نیبر آو، ارنون پیٹھہٕ یبوق تام تہٕ اردن تام تہٕ اردن تام نِیومُت، وۅنۍ کٔرِو تِم زمینہٕ دُبارٕ امن سان بحال۔\n14. تہٕ یفتاہن سوٗزۍ عمون کِس اولادَس نِش دُبارٕ قاصد:\n15. تہٕ ووٚنُن أمِس یِتھٕ پٲٹھۍ، یفتاح چُھ ونان زِ اسرائیلن نِش نہٕ موآب سٕنز زمین تہٕ نہ عمون سٕندِس بُلِس ہٕنز سرزمین۔\n16.\\tمگر ییلہ اسرٲیل مصر پیٹھہ ووت تہ بیابان منزہ ووت بحرِ احمرس کُن تہ ووت قادیش۔\n17.\\tاَمہِ پَتہٕ سوٗزۍ اِسرٲیلَن ادوم کِس بادشاہس نِش قاصد تہٕ وونُن زِ بہٕ چُھس ژےٚ دُعا کٔرِتھ پننہِ زمینہِ مٔنزۍ نیرُن، مگر اَدومُک بادشاہ بوزُن نہٕ۔ تہٕ یِتھے پٲٹھۍ سوٗز تِمو موآب کِس بادشاہس نِش، مگر سُہ اوس نہٕ رضامندی دِژمُت، تہٕ اِسرٲیلِس روٗد قادیشس مَنٛز روزنہٕ۔\n18.\\tپَتہٕ گٔیہِ تِم بیابان مٔنزۍ تہٕ ادوم کِس سرزمینس تہٕ موآب کِس سرزمینس اندۍ پکھۍ، تہٕ موآب کِس سرزمینہٕ کِس مشرقس کُن وٲتِتھ تہٕ آرنون کِس دوٚیمہِ طرفہٕ وٲتِتھ مگر موآب کِس سرحدس اندر آو نہٕ۔\n19. تہٕ اسرٲیلَن سوٗزۍ سِحون کِس بادشاہ سِحونَس نِش یُس ہیشبون کِس بادشاہس سٍتـ̡ ۔ تہٕ اسرٲیلَن ووٚن أمِس زِ أسۍ پٔزِو تہٕ چُھہ پننہِ سرزمینہٕ کِنۍ میانہِ جایہِ مَنٛز دُعا کٔرِتھ۔\n20.\\tمگر سِحونَن کٔر نہٕ اِسرٲیلِس پَنٕنہِ بٔٹھہِ کِنۍ پَکُن پَنٕنـ̡ سٍتـ̡\n21. تہٕ خداوند اسرٲیلِک خداہن دِژ سیحون تہٕ تٔمۍ سٕندِس سارِنٕے لُکھ اسرٲیلِس اتھس مَنٛز، تہٕ تِمو دِژ تِمن ہٕندِس سٍتـ̡ مارٕ۔\n22.\\tتہٕ تِمن ٲس امورین ہٕندِس سارِنٕے ساحلس پیٹھ قبضہٕ، ارنون پیٹھٕ یبوکس تام تہٕ بیابان پیٹھٕ اردن تام تہِ۔\n23. تێلہِ چُھ وُنہِ اِسرٲیلِکِس خداہِ سٕندِس امورِیَن پَنٕنـ̡ أسرٲیلـ̡ نِش بے دخل کٔرِمُت، تہٕ کیا تێہہ چُھہ یہِ حٲصِل کٔرِتھ؟\n24.\\tکیا تۅہہِ آسہِ نہٕ سُہ یُس کیموش تُہند خدایہ دِوان چھُ؟ تێلہِ یُس تہِ خداوند سُند خدا اسہِ برونہہ کُن کڈِ، سُہ گژھہِ اسہِ نِش۔\n25.\\tتہٕ وۅنۍ کیا ژیہ موآب کِس بادشاہ زیپور سٕندِس نیچوِس بالک سٕندِ نیچو کھوتہٕ بہتر کانہہ چیز؟ کیا تٔمۍ اوسا زانہہ اسرٲیلِس خلاف کوشش کٔرمٕژ، یا تِمن خلاف اوسا زانہہ جنگ کٔرمٕژ،\n26.\\tییلہ زن اسرائیل ہیشبون تہٕ تٔمۍ سٕندِس شہرس منز، تہٕ آروئر تہٕ تٔمۍ سٕندِس قصبن منز، تہٕ تِمن سارِنٕے شہرن مَنٛز روزان یِم ارنون کِس ساحلس نِش ٲسۍ، تریہ ہتھ ؤری۔ تَمہِ وِزِ کیازِ گٔیہِ نہٕ تَمہِ وقتَس اَتھ مَنٛز بازیافت کٔرِتھ؟\n27. اَمہِ مۄکھٕ چُھہ نہٕ مےٚ سٍتـ̡ گۅناہ کورمُت، مگر ژے چُھہ میانہِ سٍتـ̡ جنگ کٔرِتھ میہ سٍتـ̡ ظلم کٔرِتھ: خداوند منصف گژھہِ از دۅہہٕ بنی اسرٲیلِس تہٕ عمونن ہٕندِس بُلِس درمِیان فٲصلہٕ۔\n28.\\tتاہم کٔر نہ عمون سٕندِس اولادَن ہٕندِس بادشاہس یفتاح سٕندِس کلامَس بوزنہٕ۔\n29.\\tپتہٕ آو خداوند سُند روح یفتاہس پیٹھ، تہٕ سُہ آو جلعاد تہٕ منسی پیٹھ، تہٕ گُلعاد کِس مزپہہ پیٹھ، تہٕ گلعاد کِس مزپہہ پیٹھٕ ووت عمون کِس شُرین نِش۔\n30. تہٕ یفتاہن کٔر خداوند سُند عہد تہٕ وونُن، یێلہِ تہٕ یێلہِ ژے عمون سٕندِ اولاد میانین اَتھن مَنٛز دِیُو،\n31. تیلہِ گژھہِ یہِ زِ یُس تہِ میانہِ گرٕ کِس دروازس منزٕ نیرِ، یێلہِ بہٕ عمون سٕندِ شُرین نِش امن سان واپس یِیہ، سُہ گژھہِ یقینا رب سُند، تہٕ بہٕ کرٕ سُہ زالنہٕ خٲطرٕ پیش کرنہٕ۔ {کنہِ تہِ...: ہیب۔ یُس نیرِ، یُس نیرِ} {تہٕ...: یا، یا بہٕ دِیہٕ سُہ پیش کرنہٕ، وغیرہ}\n32. یِتھٕ پٲٹھـ̡ ووت یفتاح عمون سٕندِس شُرین نِش تِمن خلاف لڑنہٕ خٲطرٕ۔ تہٕ خداوند دِژ تِم پننِس اتھس مَنٛز۔\n33.\\tتہٕ تٔمۍ دِژ تِم اَروِر پؠٹھٕ یِمن ہٕندِس مِنِتھس تام تہٕ وُہن شہرن تہٕ انگورن ہٕندِس مٲدانس مَنٛز، سٮ۪ٹھاہ بٔڈ ذبح کٔرِتھ۔ یِتھ کٔنۍ گٔیہِ عمونٕکۍ اولاد بنی اسرٲیلِس برونہہ کنہِ زیر کرنہٕ۔ {میدان: یا، ہابل}\n34.\\tتہٕ یفتاح آو مزپہ سٕندِس گرس منز، تہٕ وُچھ تٔمۍ سٕنز کورِ گٔیہِ أمِس نِش نِنہٕ خٲطرٕ تہٕ نژنہٕ خٲطرٕ، تہٕ سۅ ٲس تٔمۍ سٕندِس کُنی شُرۍ۔ أمِس علاوٕ اوس نہٕ أمِس نیٚچُو تہٕ کوٗر۔ {امہ علاوٕ...: یا، أمس اوس نہٕ پنن نیچو یا کور: ہیب۔ پانس سٍتۍ}\n35.\\tتہٕ ییلہ أمِس وُچھِ، تٔمۍ پَنٕنۍ پَلو پھٔٹِتھ تہٕ وونُن، ہا میٲنۍ کورِ! ژے چُھہ میہ سٮ۪ٹھاہ پست کورمُت، تہٕ تہٕ چُھکھ تِمو منزٕ اکھ یُس میہ پریشان کران چُھ، کیازِ بہٕ چُھس نہٕ واپس گژھِتھ تہٕ بہٕ چُھس نہٕ واپس گژھِتھ۔\n36. تہٕ تٔمۍ ووٚن أمِس زِ میانہِ بابا، اگر ژے خداوند سٕندِ خٲطرٕ پنُن بوش کھولمُت چُھ، تیٚلہِ کٔرِو میانہِ سٍتـ̡ یُس پننہِ ٲسہِ منزٕ نیران چُھ۔ یێلہِ زن خداوند چُھہ تُہٕندِس دُشمنن سٍتـ̡ تہِ انتقام ہیوٚتمُت، یێلہِ تہِ چُھہ عمون سٕندِس بچن سٍتـ̡ تہِ انتقام نِیومُت۔\n37.\\tتہٕ تٔمۍ ووٚن پننِس مٲلِس زِ یہ کتھ گژھہِ میانہِ خٲطرٕ کرنہٕ، بہٕ گژھ دۄن ریتن تام تہٕ بہٕ ہیوٚر تہٕ بۄن پہاڑن پیٹھ گژھتھ تہٕ بہٕ تہٕ پننین سٲتھین ہُند ماتم کٔرِتھ۔ {ہیوٚر گژھو...: ہیب۔ گژھ تہٕ بۄن گژھو}\n38. تہٕ تٔمۍ ووٚن، گژھ۔ تہٕ تٔمۍ سوٗز سۄ دۄن رٮ۪تن خٲطرٕ، تہٕ سۄ گٔیہٕ پننین سٲتھین سۭتۍ، تہٕ پہاڑن پیٹھ گٔیہٕ پننہٕ کنوارپن ہُنٛد ماتم کرنہٕ۔\n39.\\tتہٕ دۅن ریتن پتہٕ سپد سۅ پننِس مٲلس نِش واپس، یٔمۍ أمِس سٍتـ̡ وعدٕ کٔرِتھ یُس تٔمِس وعدٕ کورمُت اوس، تہٕ سُہ اوس نہٕ کٲنسہ تہِ مردس زانان۔ تہٕ یہ اوس اسرائیلس مَنٛز اکھ رواج، {کسٹم: یا، آرڈیننس}\n40. {یہ} اسرٲیلٕچ کورِ ٲس ؤریس منز ژۅن دۅہن یفتاح سٕنزِ کورِ ہُند ماتم کرنہٕ خٲطرٕ گژھان۔ {سالانہٕ: ہیب۔ ؤری پتہٕ ؤری} {ماتم کرنہٕ خٲطرٕ: یا، کتھ کرنہٕ خٲطرٕ}","1.\\tتہٕ افرائیم سٕندِ لُکھ جمع تہٕ گٔیہِ شمالس کُن تہٕ وونُن یفتاہس زِ ژے کیازِ ژے آمون سٕندٮ۪ن شُرین سٍتـ̡ لڑنہٕ خٲطرٕ آمُت، تہٕ اسہِ کٔرٕکھ نہٕ پانس سٍتـ̡ نیرنہٕ خٲطرٕ؟ أسۍ زٲلِو تُہند گرٕ نارٕ سٍتـ̡ ۔ {جمع...: ہیب۔ بُلاونہٕ آمُت}\n2. تہٕ یفتاہن ووٚن تِمن زِ بہٕ تہٕ میانہِ قوم ٲس عمون کِس شُرین سٍتـ̡ س تہٕ ییلہ میہ ژیہ بلاو، ژے کٔر نہ میہ تِہندِ اتھہ نِش نِش۔\n3. تہٕ ییلہ میہ وُچھ زِ ژے چُھہ نہٕ میہ دِژمُت، بہٕ تھوو پنُن زُو پننین اتھن منز، تہٕ عمون سٕندِس شُرین نِش ووت تہٕ خداوند دِژ تِم میٲنس اتھس منز۔ تیلہِ کیازِ چُھکھ ژے از میہ نِش لڑنہٕ خٲطرٕ آمٕتۍ۔\n4. پتہٕ کٔر یفتاہَن جلعادٕکۍ سارِنٕے نفر جمع تہٕ لوٚگ افرائیمس سٍتـ̡ تہٕ لوٚگ افرایمس سٍتـ̡ تہٕ یِمو ووٚن زِ یێلہِ تہٕ یێلہِ ہُند مَضموٗن چھُ افرایم سٕندِس مَنٛز ژلنہٕ آمُت۔\n5.\\tتہٕ جلعادیو رٔٹ اردنٕچ وتہٕ افریمیَن برونہہ کُن، تہٕ یہِ اوس {یِتھ}، یێلہِ یِم افریمی ژٔلِتھ ژٔلِتھ گٔیہِ، ووٚن بہٕ گژھُن۔ زِ گلعاد کین نفرن ووٚن أمِس {آرٹ} تہٕ کیا تُہۍ چھُکھ افرائیمی؟ اگر سہ ونان، نہ۔\n6.\\tتَمہِ وَنُن تِمو وَنُن شِبولتھ، تہٕ تٔمۍ ووٚن سِبولیت: تِکیازِ سُہ ہیوٚک نہٕ صحیح تلفظ کٔرِتھ۔ تمہ پتہ نیو تمو تہ مارُکھ اردن کِس وتہِ پیٹھ۔ تہٕ تمہ وقتہٕ پییہ افریمی ژتٲجی تہٕ زٕ ساس۔\n7. تہٕ یفتاہَن کٔر اسرٲیلُک فیصلہ شیٚن ؤرین ہُند فیصلہٕ۔ پتہٕ گۆو یفتاح گلعادی، تہٕ آو جلعاد کین شہرن مَنٛز دفن کرنہٕ۔\n8. تہٕ أمِس پَتہٕ کٔر بیت اللحمُک ابزان اسرٲیلُک فیصلہٕ۔\n9.\\tتہٕ أمِس ٲسۍ ترہ نیچوۍ تہٕ ترہ کورِ، یِم تٔمۍ نیبرِم کُن سوزمٕتۍ، تہٕ نیرِن نیچوٮ۪ن ہٕندِ خٲطرٕ ترٕہ کورِ۔ تہٕ تٔمۍ کوٚر اسرٲیلُک فیصلہ ستن ؤرین منٛز۔\n10.\\tاَمہِ پَتہٕ گۆو اِبزان، تہٕ سُہ آو بیت اللحمس مَنٛز دفن کرنہٕ۔\n11.\\tتہٕ أمِس پَتہٕ کٔر ایلون، یُس زبولونِس سٍتـ̡ اوس، اسرٲیلُک فیصلہ کٔرِتھ۔ تہٕ تٔمۍ کٔر اسرٲیلُک فیصلہ دہن ؤرین ہُند فیصلہٕ۔\n12.\\tتہٕ ایلون زبولونیت موٗد تہٕ آو زیبولون کِس مُلکس مَنٛز آیجالونس مَنٛز دفن کرنہٕ۔\n13.\\tتہٕ أمِس پَتہٕ کٔر ہلیل سٕندِس نیچوِس عبدون یُس اکھ پیراتھونی اوس، اسرٲیلُک فیصلہ کٔرِتھ۔\n14.\\tتہٕ أمِس ٲسۍ ژتٲجی نیچوۍ تہٕ ترہ بابتٕر، یِم تریہ تہٕ داہ گَرِ ہٕندِس گٔرِس پیٹھ سوار ٲسۍ، تہٕ تٔمۍ کٔر اسرٲیلُک فیصلہ ٲٹھن ؤرین ہُند فیصلہٕ۔ {بابتٕر: ہیب۔ نیچوین ہٕنٛدۍ نیٚچو}\n15.\\tتہٕ ہلیل سُند نیچو عبدون سپُد تہٕ سپُد اَفرایم کِس سرزمینس مَنٛز عمالیقی کِس پہاڑس مَنٛز دفن کرنہٕ۔","1. تہٕ بنی اسرائیلو کٔر خداوند سٕندِس نظرس منز بییہِ بدکار ۔ تہٕ خداوند دِژ تِم ژتٲجی وُہرۍ فلسطینن ہٕندِس اتھس مَنٛز۔ {بد کر...: ہیب۔ اؠڈِٹ کَرنہٕ آمُت کَرنہٕ آمُت، وَغٲرٕ}\n2.\\tتہٕ اوس زورہ ہُند اکھ شخٕص یُس دانیَن ہٕندِس خاندانس منز، یٔمۍ سُند ناو {اوس} مانواہ۔ تہٕ تٔمۍ سٕنز زنانہٕ ٲس بنجر، تہٕ ننگہٕ نہٕ۔\n3. تہٕ خداوند سُند فرشتہٕ آو زنانہِ نِش ظٲہر تہٕ وونُن تٔمِس وُچھِو، وُچھِو وُن، تہٕ چُھکھ نہٕ زیٚوُن، مگر ژٕ گٔیہِ حاملہٕ تہٕ زیٚوٕ نیٚچُو۔\n4. تێمہِ کِنۍ گژھہِ بہٕ ژے دُعا کٔرِتھ، تہٕ نہٕ چُھہ شراب، نہ چُھہ شراب، تہٕ کُنہِ تہِ ناپاک چیز کھیوٚن:\n5. تِکیازِ ژے گژھِ حاملہٕ تہٕ نیچو زیٚو۔ تہٕ تٔمۍ سٕندِس کلس پیٹھ گژھہِ نہٕ کانہہ استرا یِنہٕ، تکیازِ بچہ گژھہِ رحم پیٹھٕ خدایہ سٕندِ خٲطرٕ ناصری تہٕ سُہ کرِ اسرٲیلِس فلسطینن ہٕندِ اتھہٕ نِش نجات دِنہٕ۔\n6.\\tاَمہ پتہٕ آو زنانہٕ تہٕ ووٚن پننِس خاوندس نِش تہٕ وونُن خدایہِ سُند اکھ انسان تہٕ تٔمۍ سُند بُتھ اوس خدایہ سٕندِس فرشتہٕ سُند بُتھ ہیوٗ ، سٮ۪ٹھاہ خوفناک: مگر میہ پرژھ نہٕ تس کتہِ پیٹھہٕ اوس، تہٕ نہ وونُن میہ پنُن ناو۔\n7. مگر تٔمۍ ووٚن میہ زِ وُچھ، ژے گژھ حاملہ تہٕ زیٚوٕ اکھ نیٚچُو۔ تہٕ وۅنۍ گژھ نہ شراب تہٕ نہ تیز شراب، نہ کھیوٚن کانہہ ناپاک {چیز}، کیازِ بچہ گژھہِ رحمہ پیٹھٕ مرنہٕ کس دۅہس تام خدایہ سٕندِ خٲطرٕ ناصری۔\n8. اَمہِ پَتہٕ کٔر منواہن خدایہِ سٕندِس نِش التجا تہٕ وونُن، اے خدایہِ سُند انسان یُس ژے سوزمُت چُھ، سُہ گژھہِ اسہِ نِش دُبارٕ یُس زیٚنہٕ وٲلِس شُرِس سٍتـ̡ کرُن۔\n9. تہٕ خداین بوز منواہ سٕنز آواز۔ تہٕ خدایہِ سُند فرشتہ آو بییہ زنانہِ نِش ییلہ سۅ کھاہس منز بِہتھ ٲس، مگر منواہ اوس نہٕ أمِس سٍتـ̡ ۔\n10.\\tتہٕ زنانہِ کٔر جلدی تہٕ ژٔلِتھ تہٕ ہٲوٕن پنُن خانٛدار، تہٕ وونُن أمِس وُچھ، یُس مرد چُھس میہ برونہہ کُن ظٲہر گومُت، یُس دۅہہ میہ نِش آو۔\n11.\\tتہٕ منواہ ووٚتھ تہٕ ووت پننہِ زنانہِ پتہٕ، تہٕ ووت مردس نِش تہٕ وونُن أمِس زِ ژے چھُکھ سُہ مرد یُس زنانہِ سٍتۍ کتھ کران چھُ؟ تہٕ تٔمۍ ووٚن، بہٕ چھُس۔\n12.\\tتہٕ منواہ ووٚن، وۅنۍ گژھہِ چانہِ کلام۔ أسۍ کِتھ کٔنۍ کرو شُرِس حُکُم، تہٕ أسۍ کِتھ کٔنۍ کرو أمِس سٍتۍ؟ {أسۍ کتھہ پاٹھۍ کرو حکم...: ہیب۔ اسہِ کتھہ پاٹھۍ کرِ اسہِ کتھہ پاٹھۍ کرُن...: یا سہ کیا کرِ؟: ہیب۔ تہنز کٲم کیا آسہِ؟}\n13.\\tتہٕ خداوند سٕندِ فرشتن ووٚن منواہَس یُس میہ زنانہِ ہُند ووٚنمُت چھُ، سُہ گژھہِ خبردار روزُن۔\n14.\\tسُہ گژھِ نہٕ کُنہِ تہِ چیزس کھٮ۪ن، نہ گژھِ شراب، نہ چیٚنہٕ تہٕ نہ کانہہ ناپاک چیز کھٮ۪ن، یُس میہ أمس حکم دِتمُت اوس، سُہ گژھہِ وُچھُن۔\n15.\\tتہٕ منواہ ووٚن خداوند سٕندِس فرشتس سٍتـ̡ بہٕ چُھس دُعا کران زِ أسۍ تھاوو ژے رٔٹِتھ یوتام نہٕ أسۍ تۅہہِ خٲطرٕ اکھ شُر تیار کرِ۔ {تۅہہ خٲطرٕ: ہیب۔ ژے برٛونٛہہ}\n16.\\tتہٕ خداوند سٕندِ فرشتن ووٚن منواہَس زِ یێلہِ تہِ ژے مے رٔٹِتھ تہٕ بہٕ کھیوٚو نہٕ چانہِ روٹی تہٕ اگر ژٕ دزنہٕ نِش نذرانہ پیش کرٕن، تێلہِ پزِ سُہ خداوند سٕندِ خٲطرٕ پیش کرُن۔ تکیازِ منوہس ٲس نہٕ خبر زِ سُہ اوس خداوند سُند فرشتہٕ۔\n17.\\tتہٕ مانواہن ووٚن خداوند سٕندِس فرشتس سٍتـ̡ تُہند ناو کیا چُھ، یێلہِ تێلہِ یێلہِ تُہٕندِس کُنہِ تہِ یێلہِ أسـ̡ تۅہہِ ہُند احترام کٔرِتھ؟\n18.\\tتہٕ خداوند سٕندِ فرشتن ووٚن أمِس زِ ژے کیازِ چھُکھ میانہِ ناوٕ پتہٕ یِتھٕ پٲٹھۍ پرژھان، یہِ چھُ راز وُچھِتھ؟ {راز: یا، حیرت انگیز}\n19. چنانچہ منواہ نِیوو اکھ شُر ماز نذرانہ ہیتھ تہٕ دیتُن خداوند سٕندِ خٲطرٕ أکِس کنہِ پتھرس پیٹھ پیش تہٕ {فرشتہ} کٔر حیرت انگیز پٲٹھۍ۔ تہٕ مانواہ تہٕ تٔمۍ سٕنٛز زنانہٕ وٕچھان۔\n20. تکیازِ یہ سپد ییلہ شعلہ قربان گاہ پیٹھہ آسمانس کُن ووت تہ خداوند سُند فرشتہ ووت قربان گاہ کس نارس منز۔ تہٕ منواہ تہٕ تٔمۍ سٕنزِ زنانہِ وُچھان تہٕ پیوٚو بُتھِس پیٹھ زمینس پیٹھ۔\n21.\\tمگر خداوند سُند فرشتہ آو نہٕ مانواہ تہٕ تٔمۍ سٕنزِ زنانہِ نِش ظٲہر۔ امہ پتہ اوس منوہس پتہ زِ سُہ اوس خداوند سُند فرشتہٕ۔\n22.\\tتہٕ منواہ ووٚن پننہِ زنانہِ زِ أسۍ مرُن یٔقیٖنی پٲٹھۍ، کیازِ أسۍ چھِ خدایہ وُچھمُت۔\n23.\\tمگر تسٕنزِ زنانہِ ووٚن أمِس زِ اگر خداوند اسہِ مارنہٕ خٲطرٕ خۅش آسہِ، تٔمِس آسہ نہٕ سانہِ اتھہٕ سٍتـ̡ زٲلِتھ تہٕ ماز ہُند نذرانہ میلہِ، نَہ ہا سُہ اسہِ یِم سارِنٕے چیٖز ہٲوِتھ، تہٕ نہ ہا اسہِ یِتھۍ کتھٕ وَننہٕ آمٕتۍ۔\n24.\\tتہٕ زنانہِ زیو اکھ نیٚچُو، تہٕ وونُن أمِس سمنز ناو، تہٕ شُر بوٚڈ تہٕ خداوند دِژ أمِس برکت۔\n25.\\tتہٕ خداوند سٕندِ روحن ہیوٚت أمِس کُنہِ ساتہٕ زورہ تہٕ اشتاولس درمیان دان کِس خٲمس مَنٛز منتقل کرُن۔ {کیمپ...: ہیب۔ مہانہدان}","1.\\tتہٕ شمشون ووت تیمناتھس کُن، تہٕ وُچھُن تِمنتھس مَنٛز فلسطینن ہٕنزِ کورِ ہٕنزِ زنانہٕ۔\n2. تہٕ سُہ آو پننِس مٲلِس تہٕ ماجہِ ہٕندِس مٲلِس تہٕ ماجہِ وُچھمُت تہٕ وونُن، مے چھے تِمناتھ مَنٛز فلسطینن ہٕنزِ کورِ ہٕنز اکھ زنانہٕ وُچھمٕژ، تێمہِ مۄکھٕ أنِو سُہ میانہِ خٲطرٕ خانٛدارِنہِ۔\n3. اَمہِ پَتہٕ تٔمۍ سٕندِس مٲلِس تہٕ ماجہِ ووٚن أمِس زِ کیا چُھہ نہٕ پننین باین ہٕنزِ کورِ منز، یا میانین سارِنٕے لُکن مَنٛز، زِ ژٕ چُھہ نہٕ ختنہ کرنہٕ آمٕژ فلسطینن ہٕنزِ زنانہٕ نِنہٕ خٲطرٕ؟ تہٕ سمسن ووٚن پننِس مٲلِس زِ میانہِ خٲطرٕ أنِو سُہ ۔ تکیازِ سۅ چھیہ میہ خۅش کران۔ {پلیز...: ہیب۔ میانین اچھن منز چھہ صحیح}\n4. مگر تٔمۍ سٕندِس مٲلِس تہٕ ماجہ ٲس نہٕ پتاہ زِ یہِ اوس خداوند سٕندِ طرفہٕ، زِ تٔمۍ اوس فلسطینن خلاف موقعہٕ ژھاران، تکیازِ تمہِ وِزِ اوس فلسطینن ہٕندِس اسرٲیلِس پیٹھ غلبہٕ۔\n5. پتہٕ گوٚو سیمسن تہٕ أمۍ سُنٛد مول تہٕ أمۍ سٕنٛز موج تِمناتھ کُن، تہٕ آو تِمناتھ کِس انگورن کِس باغس منٛز، تہٕ وُچھِتھ آو أمِس خٕلاف اکھ جوان سٕہہ گرٛٮ۪کھ۔ {خلاف...: ہیب۔ أمِس سمکھنہٕ منٛز}\n6.\\tتہٕ خداوند سُند روح آو أمِس پیٹھ زورٕ پٲٹھۍ، تہٕ تٔمۍ دِژ أمِس یِتھٕ پٲٹھۍ اکھ شُر کرایہِ دِنہٕ، تہٕ أمِس اوس نہٕ پننِس مٲلِس تہٕ ماجہِ ہٕندِس اتھس مَنٛز کینہہ تہِ ووٚنمُت۔\n7.\\tتہٕ سُہ گوٚو بۄن تہٕ زنانہِ سٍتۍ کتھ کٔرٕن؛ تہٕ تٔمۍ کٔر سیمسن خۄش۔\n8.\\tکینژس کالس پَتہٕ آو سُہ أمِس نِنہٕ خٲطرٕ واپس، تہٕ سُہ پھیُر شیر سُند لاش وُچھنہٕ خٲطرٕ: تہٕ وُچھِتھ اوس شیر سٕندِس لاشس منز ماچھ تہٕ ماچھہِ ہُند اکھ جھنڈ۔\n9.\\tتہٕ تٔمۍ رٔٹ یہِ پننِس اتھس منٛز، تہٕ کھٮ۪وان تہٕ آو پننِس مٲلِس تہٕ ماجہِ نِش، تہٕ تِمو دِژ کھٮ۪ن، مگر تٔمۍ ووٚن نہٕ تِمن زِ أمۍ اوس شیر سٕندِ لاشہٕ منٛزٕ ماچھ کٔڑمُت۔\n10. تێمہِ سُند مول ووت زنانہِ نِش۔ تہٕ سمشنن بنوو اتہِ اکھ دعوت۔ تکیازِ نوجوان ٲسۍ یۅہے ورتاوان۔\n11.\\tتہٕ ییلہ تمو أمس وُچھ، تمو أنۍ ترہ سٲتھی أمس سٍتـ̡ روزنہٕ خٲطرٕ۔\n12.\\tتہٕ سیمسنن ووٚن تِمن وُن، بہٕ کرٕ وۅنۍ ژےٚ اکھ معمہ پیش کٔرِتھ، یێلہِ ژیہ یێلہِ یێلہِ تہٕ یێلہِ تہٕ ژےٚ دِیہِ ترٕہ ورق تہٕ ترٕہ پَلَو بدلاوُن:\n13.\\tمگر اگر نہ ژیہ میہ اعلان کٔرِتھ، تیلہِ دِیِو میہ ترہ ورق تہٕ ترہ پلو بدلاونہٕ۔ تہٕ تِمو ووٚن أمِس پَنُن معمہ برونہہ کُن، یُتھ أسۍ بوزِو۔ {شیٹس: یا، قمیض}\n14.\\tتہٕ تٔمۍ ووٚن تِمن کھٮ۪نہٕ وٲلِس منزٕ ماز دراو تہٕ موٚٹھس منزٕ دراو موٚدُر۔ تہٕ تِم ہیوٚک نہٕ ترٮ۪ن دۅہن منز یہ معمہ بیان کٔرِتھ۔\n15.\\tتہٕ سٔتِمہِ دۅہہٕ سپُد یِمو سمسن سٕنزِ خانٛدارِنہِ وَنُن زِ سُہ کرِ اسہِ معمہ بیان کرنہٕ، یُس اسہِ تہٕ تُہٕندِس مٲلہِ سُند گرٕ نارٕ سٍتـ̡ زٲلِتھ دِنہٕ: ژے چُھہ اسہِ بُلوومُت یُس اسہِ نِش چُھہ؟ {کیا یہ} چھُنہٕ {تَمہِ}؟ {نِیو...: ہیب۔ اسہِ پیٹھ قبضہ کرُن، یا اسہِ غریب؟}\n16.\\tتہٕ شمشون سٕنزِ زنانہِ روو أمِس برونہہ کُن، تہٕ ووٚنُن، تہٕ ژے چُھکھ میہ سٍتـ̡ نفرت کران، تہٕ چُھکھ نہٕ میہ محبت کران، تہٕ ژے چُھکھ نہٕ میانین لوکن ہٕندِس بچن خٲطرٕ اکھ معمہ پیش کٔرمٕژ، تہٕ چُھکھ نہٕ مے وَنُن۔ تہٕ تٔمۍ ووٚن أمِس، وُچھ، مے ووٚن نہٕ پننِس مٲلس تہٕ نہ ماجہِ، تہٕ کیا بہٕ وَنُن ژےٚ؟\n17.\\tتہٕ سُہ روو أمِس برونہہ کُن، یێلہِ تِہُند دعوت روٗد تہٕ سٔتِمہِ دۅہہٕ سپُد أمِس وونُن، تکیازِ سُہ اوس أمِس دَگ دِوان، تہٕ تٔمۍ ووٚن پنہٕ نِس لُکن ہٕندِس شُرِس پٲٹھۍ۔ {ستھ ...: یا، باقی ستن دۅہ}\n18.\\tتہٕ شہرٕکۍ مردو ووٚن أمِس سٔتِمہِ دۅہہ آفتاب لوسنہٕ برونہہ، ماچھہِ کھۅتہٕ کیا چُھہ موٚدُر؟ تہٕ شیر کھوتہٕ کیا چُھ {چُھ} مضبوط؟ تہٕ تٔمۍ ووٚن تِمَن زِ اگر نہٕ ژےٚ میانہِ گٲو ہل کٔرِتھ، تیٚلہِ آسہٕ نہٕ میٲنۍ معمہ لٔبِتھ۔\n19.\\tتہٕ خداوند سُند روح آو أمِس نِش، تہٕ سُہ ووت اشکلون کُن، تہٕ تِمو منزٕ مارِن ترٕہ نفر، تہٕ تِمن دِتُن پَلَو بدلاونہٕ یُس معمہ بیان کٔرِ۔ تہٕ تٔمۍ سُند شَرارتہٕ ژوٚل تہٕ سُہ گوٚو مٲلہِ سٕندِس گرس تام۔ {سپائل: یا، لباس}\n20.\\tمگر سیمسن سنز زنانہ آیہ پننس سٲتھیس دِنہٕ، یُس تٔمۍ پَنُن دوس استعمال کران اوس۔","1.\\tمگر یہ سپد کینژس کالس منز، کٕنکہِ فصلہٕ وِزِ زِ سمسن گۆو پننہِ زنانہِ نِش أکِس شُرِس سٍتـ̡ ۔ تہٕ أمۍ ووٚن، بہٕ گژھٕ پننہِ زنانہِ نِش کمرس منٛز۔ مگر تٔمۍ سُنٛد مول دِژ نہٕ أمِس اژنہٕ خٲطرٕ۔\n2.\\tتہٕ تٔمۍ سٕندِس مٲلہِ ووٚن، میہ اوس پٔزۍ پٲٹھۍ خیال زِ ژے ٲس أمس سٍتۍ سراسر نفرت۔ لہذا دیت میہ سۅ چانہِ سٲتھیس نِش: {کیا } چھے نہٕ تسٕنز لۄکٕٹ بینہِ أمِس کھۅتہٕ زیادٕ خوبصورت۔ أمِس نِن، بہٕ چھُس أمِس بدلہٕ دُعا کران۔ {نِیو...: ہیب۔ سۅ گژھہِ تۅہہ}\n3.\\tتہٕ سمسن ووٚن تِمن مُتعلِق زِ وُنہِ بہٕ گژھہٕ فلسطینی کھۅتہٕ زیادٕ بے عیب ، حالانکہ بہٕ چُھس تِمن ناراض کٔرِتھ۔ {بییہِ...: یا، فلسطینی نِش بے عیب وغیرہ}\n4.\\tتہٕ سمسن رٔٹِتھ ترے ہتھ پۅژھہٕ رٔٹِتھ تہٕ لٔج لٔٹ لٔٹ تہٕ لٔٹ لٔٹ دِژٕن، تہٕ تھووُن دۄن لٔچن درمیان اکھ آتش برانڈ۔ {فائر برانڈز: یا، ٹارچ}\n5.\\tتہٕ ییلہ تٔمۍ داغن نار دِژ، تمٔۍ دِژُن فلسطینن ہٕندِس کھڑا مکایہِ منز، تہٕ زٲلِن دۅشوے جھٹکہٕ تہٕ کھڑا مکایہ تہِ، انگور تہٕ زیتون سٍتۍ۔\n6.\\tاَمہِ پَتہٕ ووٚن فلسطینو زِ یہِ کٔمۍ چُھ کوٚرمُت؟ تہٕ تِمو دیُت جواب، تیمنیت سُند زامتُر، تکیازِ تٔمۍ ٲس پنٕنۍ زنانہٕ نِتھ پننِس سٲتھیس دِژمٕژ۔ تہٕ فلسطینی آیہ، تہٕ زٲلِکھ أمِس تہٕ تٔمۍ سُنٛد مول نارٕ سٍتۍ۔\n7. تہٕ شمسنن ووٚن تِمن زِ یێلہِ تہِ چُھہ یێلہِ تہِ چُھہ یێلہِ تہٕ بہٕ ہُند انتقام تہٕ اَمہِ پَتہٕ بہٕ چُھس بند کٔرِتھ۔\n8.\\tتہٕ تٔمۍ دِژ تِمن کولہٕ تہٕ رانن ہٕندِس سٮ۪ٹھاہ ذبحہٕ سٍتـ̡ تہٕ سُہ ووت بۄن تہٕ بٔنِتھ روزُن کٔنہِ کُ\n9. پَتہٕ گٔیہِ فلسطینی ہیوٚر تہٕ یہوداہَس مَنٛز پھٔہلِتھ تہٕ پھٔہلِتھ پَنُن پان لیہِس مَنٛز پھٔہلِتھ۔\n10. تہٕ یہوداہ کیو لوکو ووٚن، تہٕ ژیہ کیازِ چھِو اسہِ خلاف آمٕتۍ؟ تہٕ تِمو دِژ جواب، شمسنس پابند کرنہٕ خٲطرٕ چھا أسۍ وۅتھان تہٕ أمِس سٍتـ̡ یِتھٕ پٲٹھۍ تٔمۍ اسہِ سٍتـ̡ کورمُت۔\n11. پتہٕ گٔیہِ یہوداہٕکۍ ترے ساس نفر ایتم کِس تھزرس پیٹھ، تہٕ وونُن سیمسنس زِ ژیہ چھے نہٕ پتاہ زِ فلسطینی چِھ اسہِ پیٹھ حکمران؟ یہ {یہ} کیا چُھ ژے اسہِ سٍتۍ کورمُت؟ تہٕ تٔمۍ ووٚن تِمن یِتھٕ پٲٹھۍ تِمو مےٚ کٔر، تِتھے پٲٹھۍ کوٚر میہ تِمن سٍتۍ۔ {گٔیہ: ہیب۔ بۄن گٔیہ}\n12. تہٕ تِمو ووٚن أمِس زِ أسۍ چھِ ژے رٔٹنہٕ خٲطرٕ آمٕتۍ، یُتھ أسۍ ژے فلسطینن ہٕندِس اتھس مَنٛز واتناوٕنۍ۔ تہٕ سمسنن ووٚن تِمَن زِ مےٚ کٔرِو قَسم زِ تُہۍ کٔرِو نہٕ پانَے مےٚ پٲٹھۍ۔\n13.\\tتہٕ تِمو کٔر أمِس سٍتـ̡ کتھ باتھ کٔرِتھ ونُن، نہٕ۔ مگر أسۍ کرو ژے جلدی بند، تہٕ تِمن ہٕندِس اتھس منز واتناوُن، مگر یقینا أسۍ کرو نہٕ ژے مارٕ۔ تہٕ تِمو لٲگِتھ أمِس زٕ نٔوۍ رَزِ، تہٕ أنِن سُہ کَنہِ پیٹھ۔\n14.\\tییلہ سُہ لیحی نِش آو، فلسطینیو کٔر أمِس خلاف کرٛٮ۪کہٕ، تہٕ خداوند سُند روح آو أمِس پیٹھ زورٕ پٲٹھۍ، تہٕ یِم رزٕ تٔمۍ سٕندِس نرِ سٍتـ̡ نار سٍتـ̡ زٲلِتھ گٔیہِ، تہٕ تٔمۍ سٕندِس اَتھٕ نِش گٔیہِ تٔمۍ سٕندِس اَتھٕ سٍتـ̡ یلہٕ۔ {لولہٕ: ہیب۔ گٔمٕتۍ گٔمٕتۍ}\n15.\\tتہٕ أمِس لوٚب أکِس گَرٕ سٕنز نٔو جٲرِ، تہٕ کوٚرُن پنُن اَتھٕ تہٕ رٔٹِتھ تہٕ مارِن ساس نفر۔ {نٔو: ہیب۔ نم }\n16.\\tتہٕ سیمسن ووٚن زِ گَرٕ سٕندِ جٲرِ سٍتـ̡ چھُ میہ ساس نفر مارمُت۔ {ڈھیر پیٹھ...: ہیب۔ اکھ ڈھیر، زٕ ڈھیر}\n17.\\tتہٕ ییلہ تٔمۍ کتھ ختم کٔر، تٔمۍ کٔر اتھہٕ منزٕ جبڑ ہٕنز أڑج، تہٕ وونُن اتھ جایہ رمتلیہی۔ {رامتھلیہی: یعنی جبڑِ ہٕنز أڈجہِ تُلُن، یا جبڑِ ہٕنزِ أڈجہِ ہُند تُلُن}\n18.\\tتہٕ سُہ اوس سٮ۪ٹھاہ پیاس تہٕ خداوندَس مُتلق دِژُن تہٕ وونُن، ژے دِژ یہِ بٔڈ نجات پننِس خادم سٕندِس اتھس مَنٛز، تہٕ وۄنۍ بہٕ مَرٕ ترشہٕ سٍتـ̡ تہٕ پۯاوُن نہٕ ختنہٕ وٲلِس اتھس مَنٛز؟\n19.\\tمگر خداین کٔر اکھ کھوکھر جاے یُس جپھِ منز اوس، تہٕ تتہِ آو آب نیبر۔ تہٕ ییلہ سہ شراب، تٔمۍ سُند روح آو دُبارٕ تہٕ سُہ آو زندٕ: اوے ووٚن تٔمۍ اَمہ ہُند ناو انہاکُر، یُس از تام لیہی منز {چُھ}۔ {انہکور: یعنی سُہ کیور یُس بلاوُن یا روُن} {جبڑ: یا، لیہی، یتھ بابس منز وننہ چھہ آمت}\n20. تہٕ تٔمۍ کٔر فلسطینی سٕندِس دۅہس مَنٛز اسرٲیلُک فیصلہٕ۔","1.\\tپَتہٕ گوٚو سمسن غزہ کُن، تہٕ وُچھُن تتہِ اکھ بدکار تہٕ وُچھِن أمِس نِش۔ {ہرلوٹ: ہیب۔ اکھ زنانہٕ اکھ بدکار}\n2. {تہٕ یہ آو وننہٕ} غازی زِ سموسن آو یور ۔ تہٕ تِمو گٔیہِ أمِس انٛدرٕ تہٕ روٗدۍ سٲرۍسٕے رٲژ شہرٕ کِس دروازس پیٹھ أمِس پیارُن، تہٕ روٗدۍ سارِوٕے رٲژ ژھۄپہٕ، یہِ ونان زِ صبحٲے ییٚلہِ دۄہ گژھہِ، أسۍ مارٕ أمِس مٲرِتھ۔ {خاموش: ہیب۔ خاموشی}\n3.\\tتہٕ شمشون لوٚگ نصف رٲژ تام تہٕ ووت نصف رٲژ تہٕ شہرٕکہِ دروازٕکۍ دروازٕ تہٕ دۅشوٕے چوکہٕ رٔٹِتھ تہٕ تِمن سٍتـ̡ دِژُن تہٕ تِمن ہٕندِس پھیکس پیٹھ، تہٕ تُلُن أکِس بالہٕ کِس تینتٲلس تام یُس حبرونس برونہہ کُن چُھ۔ {بار...: ہیب۔ بار سۭتۍ}\n4.\\tتہ امہ پتہ سپد یہ زِ تس اوس وادی سوریک چہ زنانہِ سیتۍ محبت کران، یمۍ سُند ناو دلیلہ اوس۔ {منز...: یا، نالہِ کُن}\n5.\\tتہٕ فلسطینن ہٕندِ مالہٕ آیہِ أمِس نِش، تہٕ وُچھِو أمِس کُنہِ سٍتـ̡ تٔمِس بٔڈ طاقتہٕ تہٕ کمہِ سٍتـ̡ أسـ̡ أمِس خٕلاف، تہٕ أسـ̡ دِیُو تٔمِس سٍتـ̡ کاہ ہتھ رۄپہٕ۔ {مصیبت: یا، عاجز}\n6. تہٕ دلیلہ ووٚن سیمسنس زِ بہٕ چُھس ژے دُعا کران زِ تُہند بٔڈ طاقت کُس تہٕ یێمہِ سٍتـ̡ ژے ژے مُتٲثِر کرُن۔\n7.\\tتہٕ سمسن ووٚن أمِس زِ اگر تِمو مےٚ سَتھ سبز سٍتـ̡ بٔنِتھ یِم نہٕ زانہہ ہۄکھمٕژ آسہِ، تیلہِ گژھہٕ بہٕ کمزور تہٕ بییِس انسانس ہٕندۍ پٲٹھۍ۔{سبز...: یا، نٔوۍ رَزِ: حب۔ نمی } {بیاکھ: ہیب۔ اَکہِ}\n8.\\tتمہِ پتہٕ أنۍ فلسطینن ہٕندِس مٲلکَن أمِس نِش سَتھ سبز یِم نہٕ ہۄکھمٕتۍ ٲسۍ، تہٕ تٔمۍ گٔیہِ أمِس سٍتـ̡ بٔنِتھ۔ {سبز...: یا، نٔو ڈور: ہیب۔ نم }\n9.\\tوۅنۍ ٲسۍ {اتہِ} مرد انتظارس منز، أمس سٍتۍ کمرس منز روزان۔ تہٕ تٔمۍ ووٚن أمِس زِ فلسطینی {be} چُھہ ژے پیٹھ، سیمسن۔ تہٕ سُہ چُھ بریک لگان، یِتھ کٔنۍ زِ ٹاوُک اکھ دھاگہٕ چُھ پھُٹمُت ییٚلہِ یہِ نارس اَتھٕ لاگان چھُ۔ لہذا اوس نہٕ تٔمۍ سٕنٛز طاقت معلوٗم۔ {ٹچ : ہیب۔ خوشبو}\n10.\\tتہٕ دلیلہ ووٚن سیمسنس زِ وچھ ژے چھے میہ ٹھٹھہٕ کٔرمٕژ، تہٕ وونُن اپُز۔\n11.\\tتہٕ تٔمۍ ووٚن أمِس زِ، اگر تِم مےٚ نٔوۍ رزِ سٍتۍ رٔٹِتھ رٔٹِتھ یِم نہٕ زانہہ رٔٹِتھ آسہِ، تیلہِ گژھہٕ بہٕ کمزور تہٕ بییِس انسانس ہٕندۍ پٲٹھۍ۔{یُس نہٕ زانہہ ...: ہیب۔ یتھ سٍتۍ چھیہ نہ کٲم سپزمژ}\n12.\\tدلیلہ رٔٹِتھ نٔوۍ رزٕ تہٕ رٔٹِتھ تہٕ وونُن أمِس سٍتـ̡ فلسطینی {be} ژے پیٹھ، سیمسن۔ تہٕ {تتہِ} ٲسۍ انتظارس منز روزان چیمبرس منز۔ تہٕ تٔمۍ کٔر تِم نرِ نِش پنہٕ پنہٕ پٲٹھۍ۔\n13.\\tتہٕ دلیلہ ووٚن سیمسنس زِ از تام چُھہ ژے میہ ٹھٹھہٕ کٔرِتھ تہٕ وَنُن اپُز: مے وَنُن کَمہِ سٍتـ̡ چُھکھ پابند گٔژھِتھ۔ تہٕ تٔمۍ ووٚن أمِس زِ اگر ژٕ میانہِ کلہٕ سٕندِ سَتھ تالہٕ جال سٍتۍ وُننہٕ۔\n14.\\tتہٕ تٔمۍ لوٚگ پِنہٕ سٍتـ̡ تہٕ وونُن أمِس سٍتـ̡ فلسطینی {be} ژے پیٹھ، سمشن۔ تہ سہ بیدار گوو نندر منزہ تہ بیمچ پِن ہیتھ تہ جال ہیتھ ژٔلتھ۔\n15.\\tتہٕ تٔمۍ ووٚن أمِس زِ ژٕ کِتھ کٔنۍ ہیکِو ؤنِتھ، بہٕ چُھس ژے محبت کران، ییٚلہِ زن تُہند دِل چُھنہٕ مےٚ سٍتـ̡ چُھہ؟ ژے چھے یِمن تریہ لٹہِ میہ ٹھٹھہٕ کٔرمٕژ، تہٕ مے ووٚنمُت نہٕ زِ تُہند زبردست طاقت کتہِ چھُ۔\n16.\\tتہ سپد یہ سپد ییلہ سۅ دۅہہ دۅہہ پننیو کلامو سیتۍ أمس دباو دِوان تہٕ تمس زور دِوان زِ تٔمۍ سُند روح گۆو مرنس تام پریشان۔ {پریشان: ہیب۔ ژھوٚٹ}\n17.\\tزِ تٔمۍ ووٚن أمِس سٲرۍسٕے دِل تہٕ وونُن زِ میٲنِس کلَس پیٹھ چُھنہٕ کانہہ ریزر آمُت۔ تکیازِ بہٕ چُھس پننہ ماجہ ہٕندِ رحمہٕ پیٹھٕ خدایہ سٕندِ خٲطرٕ ناصری بنیومُت: اگر بہٕ کھوٗر کرنہٕ ییہ، تیلہِ گژھہِ میون طاقت میانہِ نِش نیرِ، تہٕ بہٕ گژھہٕ کمزور، تہٕ بہٕ گژھہٕ کٲنٛسہِ {بییِہ} انسانس ہٕندۍ پٲٹھۍ۔\n18.\\tتہٕ ییلہ دلیلہ وُچھ زِ تٔمۍ چُھ أمِس سٲرۍسٕے دِل ووٚنمُت، تٔمۍ سوٗز تہٕ بُلووُن فلسطینن ہٕندِس مٲلکَس تہٕ وونُن زِ یێمہِ لٹہِ یێلہِ یِمو دِل دِژمُت چھُ۔ پتہٕ آیہِ فلسطینٕکۍ مٲلک أمِس نِش، تہٕ أنِکھ تِہنٛدِس اتھس منٛز پٲنسہٕ۔\n19. تہٕ تٔمۍ دِژ أمِس کۄٹھن پیٹھ شۄنگنہٕ۔ تہٕ تٔمۍ بُلوو أکِس مردس تہٕ تٔمۍ دِژ أمِس کلہٕ سَتھ تالہٕ کھوٗر۔ تہٕ تٔمۍ ہیوٚت أمس تنگ کرُن، تہٕ تٔمۍ سُند طاقت ہیوٚت أمس نِش۔\n20. تہٕ تٔمۍ ووٚن، فلسطینی {be} چُھہ ژے پیٹھ، سمسن۔ تہٕ سُہ ووٚتھ نندر منزٕ تہٕ ووٚنُن، بہٕ نیرٕ برونہمہِ وقتٕکۍ پٲٹھۍ نٮ۪بر تہٕ پان ہلاوان۔ تہٕ سُہ اوس نہٕ یہِ وَنُن زِ خداوند چُھ أمِس نِش ژٔلِمُت۔\n21. مگر فلسطینیو نیو سُہ تہٕ أچھ کٔرِتھ أنِتھ غزہ کُن تہٕ أنِکھ سُہ پیتلٕچ زنجیر لٲگِتھ۔ تہٕ سُہ اوس جیل ہاؤسس منٛز گٔستھ۔ {آوٹ کٔرتھ: ہیب۔ بور آؤٹ}\n22.\\tبہرحال، کاسنہٕ پتہٕ ہیوٚتُن تٔمۍ سٕندِس کلُک مَس دُبارٕ بڑُن۔ {پتہٕ...: یا، یِتھ کٔنۍ زن أمِس کھوٗر اوس کرنہٕ آمُت}\n23. اَمہِ پَتہٕ کٔر فلسطینن ہٕندِس خداہس سٍتـ̡ سٍتـ�\n24.\\tتہٕ ییلہ لوکو أمس وُچھ، تِمو کٔر پننِس خدایہ سٕندِس خداہٕچ تعریف، تکیازِ تِمو ووٚن زِ سانہِ خداہَن چُھ سانہِ دُشمن تہٕ سانہِ ملکُک تباہ کرن وول سانہِ اتھس منز دِژمُت، یٔمۍ اسہِ منزٕ واریاہ مارۍ مٲرۍ۔ {کُس...: ہیب۔ تہٕ ییٚمۍ سٲنۍ مارنہٕ آمٕتۍ گٔیہِ}\n25.\\tتہٕ سپُد یێلہِ تِہُند دِل خۅش گۆو، تِمو ووٚن، سُہ کرِ اسہِ کھیل۔ تہٕ تِمو بُلوو سمسن جیلہٕ منزٕ نیبر۔ تہٕ تٔمۍ بنٲو تِم کھیل: تہٕ تِمو تھووُن سُہ تھمَن درمِیان ۔ {تِم: ہیب۔ تمن برٛونٛہہ}\n26.\\tتہٕ شمشنن ووٚن أمِس لڑکہٕ یُس أمِس اتھہٕ تھپھ کٔرِتھ اوس، بہٕ کرٕ تِمن تھمن ہُند احساس یُس گرٕ کھڑا چُھ، یُتھ بہٕ ہێکہٕ تِمن پیٹھ ٹیکہٕ کٔرِتھ۔\n27. وۅنۍ اوس گرٕ مردو تہٕ زنانو سٍتۍ بٔرِتھ۔ تہٕ فلسطینی ہٕندِ سارِنٕے مٲلکَن ہٕندِ مٲلکَن ٲس تتہِ۔ تہٕ چھتس پیٹھ ٲسۍ تقریباً تریہ ساس مرد تہٕ زنانہٕ، یِم وُچھان ٲسۍ ییلہ سیمسن کھیل کران اوس۔\n28.\\tتہٕ سیمسنن کٔر خداہس بُلاونہٕ تہٕ وونُن، اے خدایہ، میہ یاد تھاوُن، بہٕ چُھس ژے دُعا کران تہٕ بہٕ کرٕ ژے دُعا کرنہٕ، صرف اکہِ لٹہِ، اے خدایہ، یُتھ بہٕ ہێکہٕ پننین دون اچھن ہُند بدلہٕ نِنہٕ۔\n29.\\tتہٕ سمسنن روٚٹ دۅن درمیانی تھمن پیٹھ یتھ پیٹھ مکانہ کھڑا اوس، تہٕ یتھ پیٹھ یہ کھڑا اوس، اکھ دچھنہِ اتھہٕ سٍتۍ، تہٕ بییِس کھوورِ اتھہٕ سٍتۍ۔ {یتھ پیٹھ...: یا، سہ اوس تمن پیٹھ جھکاوان}\n30. تہٕ سمسن ووٚن، بہٕ مرُن فلسطینن سٍتـ̡ ۔ تہٕ تٔمۍ کٔر پنُن پان {پنٕنۍ} طاقتہٕ سٍتۍ نمُن۔ تہٕ گرٕ پیوٚو مالکن تہٕ تمن سارِنٕے لُکن پیٹھ یِم اتھ منز ٲسۍ۔ لہذا یم مردہ تم پننس مرنس پیٹھ مارۍ مٲرۍ، تم ٲسۍ تمہ کھوتہ زیادہ یم تمۍ پننہ زندگی منز مارۍ۔ {میں: ہیب۔ میون روح}\n31.\\tتٔمۍ سٕندِ بٲے تہٕ تٔمۍ سٕندِس مٲلہِ سُند سورُے گرٕ آو بۄن، تہٕ نِتھ أنِتھ تہٕ دفن کٔرِتھ زورہ تہٕ اشتاولس درمیان پننِس مٲلِس منواہ سٕندِس دفنس مَنٛز۔ تہٕ تٔمۍ کٔر اسرٲیلُک وُہن ؤرین ہُند فیصلہ ۔","1.\\tتہٕ اوس اَکھ شخٕص افرائیمُک یٔمِس ناوُک {اوس} میکاہ۔\n2.\\tتہٕ تٔمۍ ووٚن پننہِ ماجہِ سٍتـ̡ کاہ ہتھ رۄپہٕ یُس ژے نِش نِنہٕ آمُت اوس، یُس ژے بد دعا کورمُت اوس، تہٕ میانین کنن منز تہِ وُچھمُت، وچھ رۄپہٕ {چُھ} میانہِ نِش۔ مے نیو یہ۔ تہٕ تٔمۍ سٕنزِ ماجہ ووٚن، خداوند سٕندِ مُبارکت، میانہِ نیچو۔\n3. تہٕ ییلہ تٔمۍ پننہِ ماجہِ ہٕندِ خٲطرٕ کاہ ہتھ رۄپہٕ واپس دِژ، تٔمۍ سٕنزِ ماجہِ ووٚن زِ مے اوس پوٗرٕ پٲٹھۍ رۄپہٕ پننِس نیچوِس خٲطرٕ پننہِ اتھہٕ سٍتـ̡ خداوند سٕندِ خٲطرٕ وقف کورمُت، یُس اکھ کھٔنِتھ تہٕ پگلہٕ بُت بناوُن، تێمہِ مۅکھہٕ کٔرٕ بہٕ یہِ ژے واپس۔\n4.\\tتوتہِ دِژ تٔمۍ سٕندِس ماجہ ہٕندِس پٲنسہٕ واپس۔ تہٕ تٔمۍ سٕنزِ ماجہِ رٔٹۍ زٕ ہتھ رۄپہٕ، تہٕ دِژن بانیَس یٔمۍ اتھ سٍتـ̡ اکھ کھٔنِتھ تہٕ اکھ پگلہٕ بُت بنوُن: تہٕ تِم ٲسۍ میکاہ سٕندِس گرس منز۔\n5.\\tتہٕ میکاہ سُند اکھ گرٕ اوس، تہٕ بنووُن اکھ ایفود تہٕ ترافیم تہٕ کوٚرُن پنُن اکھ نیچو مُقدس، یُس أمۍ سُند پادٕرۍ بنیوو۔ {مقدس: ہیب۔ اتھہٕ بٔرِتھ کٔرِتھ}\n6.\\tتِمن دۅہن اوس نہٕ اسرٲیلِس مَنٛز کانہہ بادشاہ، {مگر} اوس پرٮ۪تھ کانہہ انسان پننہِ نظرِ منز یُس صحیح اوس۔\n7.\\tتہٕ یہوداہ کِس خاندانس مَنٛز اوس بیت اللحم جوداہ سٍتـ̡ اکھ نوجوان، یُس اکھ لاوی اوس، تہٕ سُہ اوس اتہِ روزان۔\n8.\\tتہٕ یہِ شخٕص دراو بیت اللحم جوداہ پیٹھٕ شہرٕ نیبر روزنہٕ خٲطرٕ یتہِ أمِس {اکھ جاے} میلہِ، تہٕ سُہ آو سفرس دوران میکاہ سٕندِس گرس پیٹھ سوار گژھنہٕ خٲطرٕ۔ {یتھ کٔنۍ سُہ...: ہیب۔ تٔمۍ سٕنٛز وتھ بناونس منٛز}\n9.\\tتہٕ میکاہ ووٚن أمِس زِ ژٕ کتہِ آو ؟ تہٕ تٔمۍ ووٚن أمِس زِ بہٕ چُھس بیت اللحمجوداہُک اکھ لاوی، تہٕ بہٕ چُھس روزان یتہِ بہٕ {اکھ جاے} میلہِ۔\n10. تہٕ میکاہَن ووٚن أمِس زِ میانہِ سٍتـ̡ روزُن، تہٕ میانہِ خٲطرٕ بٔنِو مول تہٕ پادٕر، تہٕ بہٕ دِیہٕ ژے ؤریس تام داہ شیکل رۄپہٕ، تہٕ پَلَو تہٕ تُہٕندِس پوشہٕ سٍتـ̡ دِنہٕ۔ چنانچہ لیوی ژاو اندر۔ {اکھ سوٹ...: یا، اکھ ڈبل سوٹ، وغیرہ: ہیب۔ پلون ہُند اکھ آرڈر}\n11. تہٕ لاوی اوس انسانس سٍتـ̡ روزنہٕ خٲطرٕ مطمعین۔ تہٕ نوجوان اوس أمِس خٲطرٕ پننیو نیچویو ہٕندۍ پٲٹھۍ۔\n12. تہٕ میکاہَن کٔر لاوی مقدس ۔ تہٕ نوجوان بنیوو أمۍ سُند پادٕر، تہٕ اوس میکاہ سٕندِس گرس منز۔\n13.\\tپَتہٕ ووٚن میکاہ، وۅنۍ چُھس میہ زانان زِ خداوند کرِ میہ نیکی، یێلہِ چُھہ میہ پادٕرِس سٍتـ̡ لاوی سٍتـ̡ ۔","1.\\tتِمن دۅہن اوس نہٕ اسرٲیلِس مَنٛز کانہہ بادشاہ تہٕ تِمن دۅہن اوس ڈینی قبیلہٕ تِمن روزنہٕ خٲطرٕ وراثت ژھاران۔ تِکیازِ اَمہِ دۅہس تام اوس نہٕ تِمن سٍتـ̡ سٲرۍسٕے وراثتس سٍتـ̡ اِسرٲیلـ̡ قبیلن مَنٛز پۯاونہٕ آمُت۔\n2. تہٕ دان سٕندیو اولاوو سوٗزۍ پننِس خاندانس سٍتـ̡ پنہٕ نِس بٹھہٕ پیٹھٕ پانژھ نفر، بہادر شخص، زورہ پیٹھٕ تہٕ اشتاول پیٹھ، زمینٕچ جاسوسی کرنہٕ خٲطرٕ، تہٕ تلاشہٕ کرنہٕ خٲطرٕ۔ تہٕ تِمو ووٚن تِمَن زِ گژھِو زمینہِ ژھانڈِو، یُس ییلہ تِم افرائیم کِس پہاڑس پیٹھ آیہ، میکاہ سٕندِس مکانس منز، تِمو رودۍ اتہِ روزان۔ {مین آف: ہیب۔ سنز آف }\n3.\\tییلہ تِم میکاہ سٕندِس گرس نِش وٲتِتھ، تِمو گٔیہِ لووی سٕنز آواز زانان، تہٕ تِمو گٔیہِ تتہِ تہٕ وونُن تۅہہِ کُس اوٚن؟ تہٕ یَتھ جایہِ کیا چُھکھ تُہۍ بناوان؟ تہٕ ژیہ کیا چُھکھ یتہِ؟\n4. تہٕ تٔمۍ ووٚن تِمن تہٕ یِتھٕ پٲٹھۍ چُھس میکاہ سٍتـ̡ میانہِ سٍتـ̡\n5.\\tتہٕ تِمو ووٚن أمِس مشورٕ، أسۍ کٔرِو خدایہِ سٕنز دُعا یُس أسۍ پکان چھِ، یێلہِ أسۍ پکان چھِ۔\n6.\\tتہٕ پادٕرین ووٚن تِمن سٍتـ̡ امن سان گژھُن: خداوند سٕندِ برونہہ کُن چُھہ تُہٕنزِ وتہِ یێلہِ تێلہِ گژھِو۔\n7.\\tپَتہٕ گٔیہِ پانژھ نفر دراو تہٕ لیشس کُن وٲتِتھ وُچھِکھ تِم لُکھ یِم اَتھ مَنٛز ٲسۍ، تِم کِتھہ پٲٹھۍ، زِدونین ہٕندِس طریقس پٲٹھۍ، خاموش تہٕ محفوظ۔ تہٕ {اتہِ} اوس نہٕ زمینس منز کانہہ مجسٹریٹ، یُس {تِم} کُنہِ تہِ چیزس منز شرمسار کرِ۔ تہٕ تِم ٲسۍ زِدونین نِش دور، تہٕ تِمن اوس نہٕ {کٲنسہ تہِ} انسانس سٍتـ̡ کانہہ کارنامہٕ۔ {لیش: تہِ ونان چھِ، لیشیم} {مجسٹریٹ: حب۔ قبضہٕ، یا، پابندیوں ہُند وٲرِث}\n8.\\tتہٕ تِم آیہِ پننین باین نِش زورہ تہٕ اشتاولس کُن، تہٕ تِہندیو بٲے ووٚن تِمن کیا چُھہ؟\n9.\\tتہٕ تِمو ووٚن، وۅتھٕ وُچھِو، یُتھ أسۍ تِمن خلاف گژھِتھ، تکیازِ اسہِ چھُ زمین وُچھمٕژ، تہٕ وُچھِو یہِ {چُھ} واریاہ اصل: تہٕ کیا تُہۍ چھِو وُنہِ تہِ؟ گژھُن نہٕ سُست گژھُن، {تہٕ} زمینس پیٹھ قبضہ کرنہٕ خٲطرٕ اژُن۔\n10. ییلہ تم نیرِو، تم گژھو أکِس محفوظ لُکن نِش تہٕ أکِس بٔڈِس زمینس مَنٛز، کیازِ خداین چُھ یہِ تُہندس اتھس مَنٛز دِژمُت۔ اکھ یژھ جاے ییتہِ {اتہِ} زمینس منز کُنہِ چیزچ کمی آسہِ نہ۔\n11.\\tتہٕ تتہِ دراو دانین ہٕندِ خاندانہٕ منز، زورہ نیبر تہٕ اشتاول منز، شیہ ہتھ نفر جنگی ہتھیار ہیتھ مقرر کرنہٕ۔ {مُقرر: ہیب۔ گرڈڈ}\n12.\\tتہٕ تِم گٔیہِ ہیوٚر تہٕ یہوداہَس مَنٛز کِرجاتھجیرِمَس مَنٛز وَنُن: اَمہِ مۄکھٕ وُچھِو تِمو اَتھ جایہِ از تام مہنہدان وَننہٕ: وُچھِو {یہِ} کِرجاتھجیرِمَس پَتہٕ۔\n13. تہٕ تِم گٔیہِ اَمہِ پَتہٕ افرائیم کِس کُنہِ ک\n14.\\tاَمہ پتہٕ دِژ پانژو نفرن جواب یِم لیش کِس ملکٕچ جاسوسی کرنہِ گٔیہِ، تہٕ وونُن پننین باین زِ کیا تۅہہ چھے پتاہ زِ یِمن گرن مَنٛز چھُ اکھ ایفوڈ، تہٕ ٹیرافیم، تہٕ اکھ کھٔنِتھ بُت تہٕ اکھ پگلہٕ بُت؟ لہذا وۅنۍ غور کرو ژیہ کیا کرُن۔\n15.\\tتہٕ تِم گٔیہِ اَتہِ کُن تہٕ وٲتِتھ وٲتِتھ نوجوان لاوی سٕندِس گرس منز، تہٕ میکاہ سٕندِس گرس کُن تہٕ کٔرٕن أمِس سلام۔ {سلام...: ہیب۔ أمِس پرژھ امن}\n16.\\tتہٕ شیہ ہتھ نفر یِم جنگی ہتھیار ہیتھ مقرر کرنہٕ آمٕتۍ، یِم ڈین سٕندِ شُرۍ ٲسۍ، گٔیہِ دروازس منز اژنہٕ نِش۔\n17.\\tتہٕ یِم پانژھ نفر یِم زمینہِ ہٕنز جاسوسی کرنہِ گٔیہِ، {تہٕ} آیہِ تتہِ، {تہٕ} تُلِکھ کھٔنِتھ مجسمہٕ، تہٕ ایفود، تہٕ ٹیرافیم تہٕ پگلہٕ بُتُہ: تہٕ پادٕرۍ کھڑا دروازٕ کِس اژنس منز شیہ ہتھ نفرن سٍتـ̡ یِم جنگی ہتھیار ہیتھ مقرر کرنہٕ آمٕتۍ ٲسۍ۔\n18.\\tتہٕ یِم گٔیہِ میکاہ سٕندِس گَرَس منز، تہٕ کٔرِن تٔمِس بُتُھر، ایفود، تہٕ ترافیم تہٕ پگلِمٕژ بُتٕہ أنِتھ۔ اَمہِ پتہٕ ووٚن پادٕرۍ تِمَن، تُہۍ کیا چھِو؟\n19.\\tتہٕ تِمو ووٚن أمِس سٍتـ̡ پَنُن پَنُن اَتھٕ تھپھ کٔرِتھ تہٕ اَسہ سٍتـ̡ بٔنِتھ تہٕ اسہِ سٍتـ̡ بٔنِتھ تہٕ اَسہ سٍتـ̡ بٔنِتھ بٔنِتھ تہٕ بٔنِتھ بٔنِتھ کُنہِ قبیلہٕ سٕندِس گرس مَنٛز پادٕرۍ بنُن؟\n20.\\tتہٕ پادٕرۍ سُند دِل گوٚو خۅش، تہٕ تٔمۍ رٔٹِتھ ایفود، تہٕ ٹیرافیم تہٕ کھٔنِتھ بُت تہٕ لُکن ہٕندِس درمِس منز۔\n21.\\tتہٕ درٛاو تِم تہٕ لۅکٹۍ شُرۍ، چاروٲے تہٕ گاڈِ پانس برونہہ کُن۔\n22.\\tییلہ تِم میکاہ سٕندِس گرٕ نِش رٔٹِتھ وٲتِتھ گٔیہِ یِم مرد میکاہ سٕندِس گرس نکھٕ گَرَن مَنٛز ٲسِتھ جمع گٔیہِ، تہٕ گٔیہِ دان سٕندِس شُرِس پٲٹھۍ۔\n23.\\tتہٕ تِمو کٔر دان سٕندِس شُرین کُن۔ تہٕ تِمو پھیُر بُتھ تہٕ وونُن میکاہَس زِ ژےٚ کیا چُھہ یِتھِس صحبتس سٍتـ̡ یِتھٕ سٍتـ̡ یِوان دِنہٕ۔ {comest...: Heb. آرٹ آو اکوٹہٕ جمع کرنہٕ؟}\n24.\\tتہٕ ووٚن تٔمۍ نِش میٲنۍ دیوتا یُس میہ بنوومت اوس، تہٕ پادٕرۍ تہٕ تہٕ ژے گٔیہِ: تہٕ میہ کیا چُھ؟ تہٕ یہِ {یہ} کیا چُھہ ژیہ وَنُن، ژیہ کیا چُھہ؟\n25.\\tتہٕ دان سٕندٮ۪و بچیو ووٚن أمِس زِ چانۍ آواز گژھہِ نہٕ اسہِ مَنٛز بوزنہٕ، نتہٕ گژھہِ ژےٚ شَرارتہٕ دار نفر ژٔلِتھ تہٕ ژٕ گٔیہِ پنٕنۍ زُو تہٕ پَنٕنِس گرٕ سٕندِس زُوٕ سٍتـ̡ رٲوِتھ ۔ {ناراض: ہیب۔ روحُک تلخ}\n26.\\tتہٕ دٲن سٕندِ شُرۍ گٔیہِ پننہِ وتہِ تہٕ ییلہ میکاہ وُچھ زِ تِم چھِ أمِس خٲطرٕ واریاہ مضبوط، سُہ گوٚو واپس پننِس گرس کُن۔\n27.\\tتہٕ تِمو نِش یِم چیز میکاہَن بنٲومٕتۍ ٲسۍ، تہٕ پادٕرۍ یُس أمِس ٲس، تہٕ آیِکھ لیشس کُن، أکِس لُکن نِش یِم ژھۄپہٕ تہٕ محفوٗظ ٲسۍ، تہٕ تِمو لٔگِتھ تلوار ہٕندِ دھار سٍتـ̡ تہٕ شہر زٲلِتھ نارٕ سٍتـ̡ ۔\n28.\\tتہٕ {اتہِ} اوس نہٕ کانہہ نجات دِنہٕ وول ، کیازِ یہِ اوس {زیدون} نِش دور، تہٕ تِمن اوس نہٕ {کٲنسہِ} انسانس سٍتـ̡ کانہہ کاروبار۔ تہٕ یہ اوس وادی منز یُس {lieth} بیت ریہوب۔ تہٕ تمو بنوو اکھ شہر، تہٕ اَتھ منٛز روز۔\n29.\\tتہٕ تِمو ووٚن شہرُک ناو دان سٕندِس ناوس پیٹھ، یُس اسرٲیلِس منز زامُت اوس۔\n30.\\tتہٕ دانس سٕندیو اولاوو کٔر کھٔنِتھ شُمار تہٕ مناسہ سُند نیچو گرشوم سُند نیچو، سُہ تہٕ تٔمۍ سٕندِ نیچوۍ رودۍ زمینہِ ہٕندِس قید سپدنس تام دان سٕندِس قبیلس ہٕندِس پادٕرۍ۔\n31.\\tتہٕ تِمو کٔر تِمن میکاہ سٕنز کھٔنِتھ بَنٲومٕژ، یُس تٔمِس سارِوٕے وقتس سٍتـ̡ خدایہِ سُند گرٕ شیلوہس مَنٛز اوس۔","1.\\tتہٕ تِمن دۅہن سپد ییلہ نہٕ اسرٲیلِس مَنٛز کانہہ بادشاہ اوس، اَمہ کُنہِ سٍتـ̡ روزان اوس، یُس أمِس نِش بیت اللحمہجودہ پى {اکھ لونڈی: ہیب۔ زنانہٕ اکھ لونڈی، یا اکھ زنانہٕ اکھ لونڈی}\n2.\\tتہٕ تٔمۍ سٕنزِ لونڈی گِندٕن أمِس خٕلاف طوائف، تہٕ گٔیہِ أمِس نِش مٲلہِ سٕندِس گَرٕ بیت اللحم جوداہ کُن، تہٕ روٗد پوٗرٕ ژور ریٚتھ۔ {ژور پورٕ ریتھ: یا، اکھ ؤری تہٕ ژور ریتھ: ہیب۔ دۅہہ، ژور ریتھ}\n3.\\tتہٕ تٔمۍ سُند خانٛدار ووٚتھ، تہٕ أمِس پَتہٕ لوٚگ أمِس سٍتۍ دوستانہٕ کتھ کرنہٕ خٲطرٕ، تہٕ أمِس دُبارٕ أنِتھ تہٕ أمِس سٍتۍ پنُن نوکر تہٕ زٕ گَرٕ أنِتھ، تہٕ سُہ أنِن أمِس مٲلہِ سٕندِس گَرَس منز، تہٕ ییلہ أمِس مٲلہِ ہٕندِس مٲلہِ سٕندِس مٲلِس وُچھِتھ گٔیہِ أمِس مِلنہٕ خٲطرٕ خۅش۔ {دوستانہ...: ہیب۔ تٔمۍ سٕنٛدس دلس منٛز}\n4.\\tتہٕ تٔمۍ سٕندِس مٲلہِ سٕندِس مٲلِس تھووُن سُہ قٲیِم۔ تہٕ سُہ روٗد أمِس سٍتـ̡ تریہ دۅہن روزان: یێمہِ سٍتـ̡ رودۍ تِمو کھٮ۪وان چیوان تہٕ اتہِ روزُن۔\n5. تہٕ ژوٗرمہِ دۅہہ ییلہ تِم صُبحے سُلہِ وۅتھان ووٚتھ، سُہ ووٚتھ نیرنہٕ خٲطرٕ، تہٕ کورِ ہٕندِس مٲلہِ ووٚن پننِس زامتٕرِس زِ پَنُن دِل دِل رٔٹِتھ رٔٹِتھ تہٕ پَتہٕ پَتہٕ پَنٕنہِ وتہِ۔ {آرام: ہیب۔ مضبوٗط کٔرِو}\n6.\\tتہٕ بیوٹھ تہٕ کھیوٚکھ دۅشوے یکوٹہ کھیوٚن تہٕ چیوٚن، تکیازِ کورِ ہٕندِس مٲلہِ اوس أمِس مردس ووٚنمُت، مُطمعیٖن روزُن، بہٕ چھُس ژے دُعا کران تہٕ سارِوٕے راتس روزُن، تہٕ پنُن دِل روزُن خۅش روزُن۔\n7.\\tتہٕ ییلہ مرد نیرنہٕ خٲطرٕ ووٚتھ، تٔمۍ سٕندِس مٲلس دِژ أمِس دُبارٕ۔\n8.\\tتہٕ سُہ ووت پوٗنٛژمہِ دۅہہ صُبحٲے نیرنہٕ خٲطرٕ، تہٕ کورِ ہٕندِس مٲلہِ ووٚن، پنُن دِل دِل دِیُن، بہٕ چھُس ژےٚ دُعا کران۔ تہٕ تِم رودۍ دُپہرس تام تہٕ تِمو کھیوٚو دۄشوے کھٮ۪وان۔ {دوپہرس تام: ہیب۔ یوتام دوہ زوال پذیر گوو}\n9.\\tتہٕ ییلہ مرد نیرنہٕ خٲطرٕ ووٚتھ، سُہ تہٕ أمۍ سٕنزِ لونڈی تہٕ أمۍ سٕندِس خادم، أمِس ہٕندِس مٲلِس سٍتـ̡ وۆنُن، وُچھ، وُنہِ دۅہ چُھہ شامس کُن یِوان، بہٕ چُھس ژے سارِوٕے رٲژ روزُن، وُچھ، دۅہ چُھہ ختم سپدُن، یێتہِ روزُن، یُتھ تُہند دِل خۅش روزُن۔ تہٕ پگہہ گژھ ژیہ سُلی وتہِ پیٹھ، تاکہ ژیہ گژھ گرہ گژھن۔ {ڈرایوتھ: ہیب۔ کمزور} {دۅہ چھہ ختم سپدان: ہیب۔ یہِ چُھ دۄہُک پِچِنگ ٹایِم} {ہوم: Heb. پننِس خیمہٕ کُن}\n10.\\tمگر سُہ اوس نہٕ تَمہِ رٲژ رُکُن، مگر سُہ ووٚتھ تھوٚد تہٕ درٛاو تہٕ ووت یبوسس کُن، یُس {یروشلم} چھُ۔ تہٕ {اتہِ}أمِس سٍتۍ ٲس زٕ گَرٕ کٔرِتھ، تٔمۍ سٕنز لونڈی تہِ ٲس أمِس سٍتۍ۔ {اوور خلاف: ہیب۔ ٹو اوور اِنسٹ}\n11.\\t{تہٕ}ییلہ تِم {ٲس} جیبس سٍتـ̡ دۅہ گُزراونہٕ آمُت۔ تہٕ خادمَن ووٚن پننِس مٲلکَس زِ آو، بہٕ چُھس ژےٚ دُعا کران، تہٕ أسۍ یبوسیَن ہٕندِس یتھ شہرس مَنٛز اژُن تہٕ اَتھ مَنٛز روزُن۔\n12. تہٕ تٔمۍ سٕندِس آقا ووٚن تٔمِس زِ أسۍ کٔرِو نہٕ اَتھ کُنہِ اجنبی سٕندِس شہرس مَنٛز، یُس نہٕ بنی اِسرٲیلِس سٍتـ̡ چُھہ نہٕ۔ أسۍ گِبیاہ کُن گٔژھِو۔\n13.\\tتہٕ تٔمۍ ووٚن پننِس خادمس زِ یِمو منزٕ کُنہِ جایہ یِمو منزٕ کُنہِ کُنہِ جایہ یِمو رٲژ گِبعاہس مَنٛز یا راماہس مَنٛز روزُن۔\n14.\\tتہٕ تِم گٔیہِ پَنٕنہِ وَتہِ پٲٹھۍ۔ تہٕ آفتاب ووت تمن پیٹھ {ییلہ تم ٲس} گیبیاہ سٕندِ ذریعہٕ، یُس {بنیامین سُند} تعلق تھاوان چُھ۔\n15.\\tتہٕ تِم گٔیہِ اَتہِ گِبعاہس مَنٛز روزنہٕ خٲطرٕ، تہٕ ییلہ سُہ اژان اوس، سُہ بیوٹھ سُہ شہرٕ کِس أکِس سڑکہِ مَنٛز، تکیازِ {اتہِ} اوس نہٕ کانٛہہ تہِ شخٕص یُس تِم پننِس گَرَس مَنٛز روزنہٕ خٲطرٕ نِوان۔\n16.\\tتہٕ وُچھ اَکھ بُزرگ دراو پننہِ کامہِ منزٕ کھہٕ منز، یُس تہِ افرائیم پہاڑُک اوس۔ تہٕ سُہ روٗد گبیعہس مَنٛز روزان: مگر امہِ جایہِ ہٕندِ مرد ٲسۍ بنیجمی۔\n17.\\tتہٕ ییلہ تٔمۍ أچھ تُل، تٔمۍ وُچھ شہرٕ چہِ سڑکہِ منز اکھ وتہٕ وَتھ: تہٕ بُزرگ ووٚن، کوٚت چھُکھ ژیہ گٔژھمُت؟ تہٕ تُہۍ کتہِ چھِو آمٕتۍ؟\n18.\\tتہٕ تٔمۍ ووٚن أمِس زِ أسۍ چھِ بیت اللحمہجودہ پیٹھٕ افرائیم کِس کُن نیران۔ تتہِ پیٹھہ گۆو بہٕ بیت اللحم جوداہ کُن، مگر بہٕ چھُس وۅنۍ خداوند سٕندِس گرس کُن گژھان۔ تہٕ کانہہ تہِ انسان چھُنہٕ یُس میہ گرس منز رٔٹِتھ آسہِ۔ {رسیوتھ: ہیب۔ جمع کٔرِتھ}\n19.\\tتوتہِ چھہ سانہِ گۅرِ ہٕندِ خٲطرٕ گاسہ تہٕ پروونڈر دۅشوے موجود۔ تہٕ میانہِ خٲطرٕ تہٕ چُھس تہٕ چانہِ نوکرِ خٲطرٕ، تہٕ نوجوانس خٲطرٕ تہٕ یُس تہندٮ۪ن خادمَن سٍتۍ چُھ، {اتہِ} چُھنہٕ کُنہِ چیزٕچ کُنہِ تہِ کمی۔\n20.\\tتہٕ بُزرگ ووٚن ژے سٍتـ̡ سلام۔ بہرحال {گژھہ} چانۍ سٲری خواہشات {میہ پیٹھ}۔ صرف روزُن نہٕ سڑکہِ منٛز۔\n21.\\tتہ اوٚن سُہ پننِس گَرَس منز، تہٕ دِتُن گَرَن تہٕ تِمو کٔرٕن کھۅر چھلنہٕ تہٕ کھٮ۪وان چیٚنہٕ۔\n22.\\t{وُن} ییلہ تِم دِل خۅش کران ٲسۍ، وُچھِتھ شہرٕکۍ مرد، بِلیال سٕندِس کینہہ نیچو، ژٔٹِتھ ژٔٹِتھ گَرٕ کٔرِتھ دِژٕن، تہٕ وَنُن مکانہٕ کِس مٲلکِس بُزرگس سٍتـ̡ وَنُن یُس تُہٕندِس گَرَس مَنٛز آمُت اوس، یُس أسـ̡ أمِس زانہٕ دِنہٕ یِوان۔\n23.\\tتہٕ گرُک مٲلک، یُس گرُک مٲلک، دراو تِمن نِش، تہٕ وونُن تِمن نِش، نہٕ میٲنۍ بٲے، {نَے}، بہٕ چُھس دُعا کران زِ یێلہِ نہٕ بدکار کٔرِو۔ یہِ وُچھِتھ زِ یہِ نفر چُھ میٲنِس مکانس منز آمُت، یہِ کٔرِو نہٕ یہِ بیوقوفی۔\n24.\\tوُچھ، {یِتھ} چھے میٲنۍ کورِ اکھ کوٗر تہٕ تٔمۍ سٕنز لونڈی۔ بہٕ کٔرٕ وۅنۍ تِم نیبر تہٕ تِمن عاجز کٔرِتھ، تہٕ تِمن سٍتۍ کٔرٕ یُس تۅہہ جان باسان چھُ، مگر أمِس شخصس کٔرِو نہٕ یُتھ بد کُن۔ {تیوٗت بدکار...: ہیب۔ اَمہ حماقتُک معاملہٕ}\n25.\\tمگر مرد ہیوٚک نہٕ أمِس بوزُن، تہٕ أمِس نِش نِنہٕ۔ تہٕ تِم ٲسۍ أمِس زانان تہٕ صبحس تام ٲسۍ أمِس سٲرۍسٕے رٲژ بدسلوکی کران: تہٕ ییٚلہِ دۄہ بہار شروع گٔیہ، تِمو ترٛٲو أمِس یِوان۔\n26.\\tتمہ پتہ آیہ زنانہِ دۅہہ صبحس منز، تہ پیوٚو مردہ سٕندِس مکانہ کس دروازس پیٹھ ییتہِ تسند مالک اوس، یوٚت تام گاش اوس۔\n27.\\tتہٕ تٔمۍ سُند مالہٕ ووٚتھ صبحٲے ووٚتھ، تہٕ گرٕکۍ دروازٕ کھولٕن، تہٕ درٛاو پننہِ وتہِ نیرنہٕ خٲطرٕ، تہٕ وُچھ زنانہٕ تٔمۍ سٕنٛز لونڈی گٔیہٕ مکانہٕ کِس دروازس پیٹھ پیوٚو، تہٕ تٔمۍ سٕنٛدۍ اتھہٕ گٔیہٕ دروازس پیٹھ۔\n28.\\tتہٕ تٔمۍ ووٚن أمِس تھوٚد تہٕ أسۍ گژھو نیرُن۔ مگر کٲنسہ تہِ دیُت جواب۔ تمہ پتہ لوٚگ مردس اکس گٲرس پیٹھ، تہ مرد ووٚتھ تھوٚد تہ لوٚگ أمس پننہِ جایہ۔\n29.\\tییلہ سُہ پننِس گرس منز آو، تٔمۍ رٔٹ اکھ شراپ، تہٕ تھپھ کٔرِن پننہِ لونڈی تہٕ کوٚرُن سۅ أڈجہِ سٍتـ̡ بَہہ ٹُکرٕ تہٕ سوٗزُن سُہ سارِنٕے بٔٹھِس مَنٛز۔\n30.\\tتہٕ یِتھٕ پٲٹھۍ اوس یہِ وُچھمُت زِ یێمہِ دۅہہٕ پیٹھٕ یێلہِ بنی اسرائیلٕچ از تام یُتھ کٲم سپٕز تہٕ وُچھنہٕ آمُت: اَتھ کُن غور کرُن، مشورٕ رٔٹِو تہٕ کتھ کٔرِو {پنٕنـ̡ ذہن}۔","1. پَتہٕ گٔیہِ سارِنٕے بنی اِسرٲیلِی، تہٕ جماعت گٔیہِ أکِس شخٕصس سٍتـ̡ جمع کرنہٕ، دان پیٛٹھٕ بیرشیبع تام، گلعاد کِس سرزمینس سٍتـ̡ تہٕ مِزپہ کِس خداہس تام۔\n2. تہٕ سارِنٕے لُکن ہٕندِس سردارس سٍتـ̡ سپُد خدایہِ سٕندِس مجلسس مَنٛز، ژور لچھ ساس پیدل یِمو تلوار تُلِتھ ٲس۔\n3. (وۅنۍ بنیامین سٕندیو اولادو بوز زِ بنی اسرائیل گٔیہِ مزپہ تام گٔمٕتۍ۔) اَمہِ پتہٕ ووٚن بنی اسرٲیل، یہِ کِتھہٕ کٔنۍ ٲس بدکاری؟\n4.\\tتہٕ مارنہٕ آمٕژ زنانہِ ہٕندِس خانٛدارس دِژ جواب تہٕ وونُن، بہٕ آو گِبعاہس مَنٛز یُس بنیامین سُند {چُھ} اوس، بہٕ تہٕ میٲنۍ لونڈی روزنہٕ خٲطرٕ۔ {دی لیویٹ: ہیب۔ دی مین دی لیوی}\n5.\\tتہٕ گِبیاہ ہٕندِس مردس گٔیہِ میہ خٕلاف، تہٕ رٲژ کٔرٕکھ میہ اندۍ پکھۍ گرس گھیرٕ، تہٕ کوٚرُکھ خیال زِ سُہ چُھس مٲرِتھ مٲرِتھ۔ {زبردستی: ہیب۔ عاجز}\n6.\\tتہٕ مے رٔٹِتھ پنٕنۍ لونڈی تہٕ ژٔٹِتھ ژٔٹِتھ تہٕ سوٗزُن سٲرۍسٕے مُلکس منز اسرٲیلٕچ وراثت کِس سٲرۍسٕے مُلکس منز، کیازِ یِمو چھِ اسرٲیلِس مَنٛز بے حیائی تہٕ حماقت کٔرمٕژ۔\n7. وچھو، تم چِھہ اسرائیلٕکۍ تمام اولاد۔ ییتہِ دِیو پنُن مشورٕ تہٕ مشورٕ۔\n8.\\tتہٕ سارِوٕے لُکھ ووٚتھ أکِس شخٕص سٕندِس خیمہٕ مَنٛز گٔژھِتھ زِ أسۍ کُنہِ تہِ گٔیہِ نہٕ تٔمۍ سٕندِس خیمہٕ مَنٛز گٔژھِتھ تہٕ نہ أسۍ کُنہِ تہِ تٔمۍ سٕندِس گَرَس مَنٛز گٔژھِتھ۔\n9.\\tمگر وۅنۍ گژھہِ یۅہے چیز یُس أسۍ گبیعہس سٍتۍ کرِ۔ {أسۍ گژھو اتھ خلاف لوٹ سٍتۍ ہیوٚر}۔\n10.\\tتہٕ أسۍ نِو اسرٲیلِہ کین سارنٕے قبیلن مَنٛز ہتھ نفر، تہٕ ساسہٕ منزٕ اکھ ہتھ تہٕ ساس منزٕ اکھ ساس، یُس تِم اسرٲیلِس مَنٛز کٔرمٕژ چھِ، یُس تِم سارِنٕے بیوقوفی مُطٲبِق یِمن ہٕندِس سٍتـ̡ بنیامین سٕندِس گیبعہس نِش یِن، یُس تِمو اسرٲیلِس مَنٛز کٔرمٕژ چھُ۔\n11.\\tتہ گٔیہِ سارِنٕے اسرٲیلٕکۍ مرد شہرس خلاف جمع گٔیہِ، أکِس نفرس سٍتـ̡ رٔلِتھ گٔیہِ۔ فیلوز}\n12. تہٕ اسرٲیلِیو قبیلو سوٗزۍ بنیامین سٕندِس سارِنٕے قبیلہٕ سٍتـ̡ انسان یہِ وَنُن زِ یہِ کیا بد کار چُھہ یُس تۅہہِ مَنٛز سپدان چُھ؟\n13. تێمہِ کِنۍ کٔرِو اسہِ بِلیال سٕندِس بُلِس یِم گِبعاہس مَنٛز چھِ، یُس أسۍ تِم مارِتھ تہٕ اسرٲیلِس نِش بُد دِنہٕ یِوان۔ مگر بنیامین سٕندِ بچہٕ بوز نہٕ پننین باین ہٕنز آواز یُس بنی اسرائیل سٕنز آواز بوزان اوس:\n14.\\tمگر بنیامین سٕندِ بچہٕ گٔیہِ شہرو منزٕ گِبیاہ کُن جمع یُس بنی اسرٲیلِس خلاف جنگ کرنہٕ خٲطرٕ نیرِ۔\n15.\\tتہٕ بنیامین سٕندِ بچہِ ہُند تعداد اوس تمہِ وِزِ شہرو منزٕ شیہ ساس نفر یِمو تلوار تُلِتھ ٲسۍ، یِمن ہُند تعداد ستھ ہتھ منتخب نفر اوس۔\n16.\\tیِمن سارِنٕے لُکن منز ٲسۍ ستھ ہتھ ژارنہٕ آمٕتۍ نفر کھوورِ اتھہٕ۔ پریتھ کانہہ ہیکہِ مس پیٹھ کنہِ کٔرتھ تہ مس کٔرتھ۔\n17.\\tتہٕ بنیامین سٍتـ̡ ٲس اسرٲیلٕکۍ نفر ژور لچھ ساس نفر یِمو تلوار تُلِتھ ٲسۍ۔\n18.\\tتہٕ بنی اسرائیل ووٚتھ، تہٕ گٔیہِ خدایہ سٕندِس گرس نِش تہٕ پرژھکھ خدایہ سٕندِس مشورس منز، تہٕ وونُن، اسہِ منزٕ کُس گژھہِ بنیامین سٕندِس بُنِس سٍتـ̡ جنگس مَنٛز گۅڈٕ نیرِ۔ تہٕ خداوند ووٚن، یہوداہ {گژھہِ گۅڈٕ تھوٚد}۔\n19. تہٕ بنی اسرائیل ووٚتھ صبحٲے تہٕ گبیعاہس خلاف لٔگۍ ڈیرٕ۔\n20.\\tتہٕ درٛاو اسرٲیلِکۍ مرد بنیمنَس خٕلاف جنگہٕ کرنہٕ خٲطرٕ۔ تہٕ اسرٲیلِیو لوٚگ گبیعاہس مَنٛز تِمن خٕلاف لڑنہٕ خٲطرٕ پان صفہٕ۔\n21.\\tتہٕ بنیامین سٕندِ بچہٕ دراو گِبیاہ منزٕ تہٕ دِژٕکھ اَمہِ دۅہہ وُہ زٕ ساس نفر اسرٲیلِس مٔنزِس مٔنزِس مٔنزِس سٍتـ̡ تباہ ۔\n22.\\tتہٕ لُکو کٔر اسرٲیلِیو پانس حوصلہٕ افزٲیی، تہٕ کٔر پنُن جنگ دُبارٕ تتھ جایہِ یێلہِ تِمو گۄڈنِکہِ دۅہہ صفس مَنٛز تھوو۔\n23. (تہٕ بنی اسرائیل ووت تہٕ روو خداوند سٕندِس برونہہ کُن، تہٕ پرژھکھ خداوند سُند مشورٕ، یہِ وونُن زِ بہٕ گژھہٕ پننِس بٲیِس بنیامین سٕندِس بُنِس سٍتـ̡ دُبارٕ جنگہٕ کرنہٕ خٲطرٕ؟ تہٕ خداوند ووٚن أمِس خلاف گژھُن۔)\n24. تہٕ بنی اسرائیل وٲتۍ دویمہِ دۅہہ بنیامین سٕندِس بچس نزدیک۔\n25. تہٕ بنیامین دراو دویمہِ دۅہہ گبعیہ منزٕ تِمن خلاف تہٕ کوٚرُن بنی اسرائیل سٕندِس زمینس تام اَردہ ساس نفر تباہ کرنہٕ۔ یِمو سارِوٕے کٔر تلوار۔\n26. اَمہِ پَتہٕ گٔیہِ سارِنٕے بنی اِسرٲیلِی، تہٕ سارِوٕے لُکھ گٔیہِ خدایہ سٕندِس گَرَس مَنٛز، تہٕ روُکھ تہٕ بِہتھ تہٕ اَمہ دۅہہٕ روزٕ تھووُکھ تہٕ کٔرٕکھ خداوند سٕندِس برونہہ کُن زٲلِتھ تہٕ صلح کِس نذرانہ پیش کرنہٕ۔\n27. تہٕ بنی اسرٲیلِو پرژھ خداوند سٕندِس سٍتـ̡ (تِمن دۅہن اوس خدایہِ سٕندِ عہدُک صندوق {موجود}،\n28. تہٕ ہارون سُند نیچو الیعزر سُند نیچو فینہاس، یُس ہارون سُند نیچو اوس تمن دۅہن اتھ برونہہ کنہِ کھڑا گومُت،) وونُن، بہٕ گژھا بییہِ بییہِ پننِس بٲیِس بنیامین سٕندِس شُرین سٍتـ̡ جنگہٕ کرنہٕ خٲطرٕ نیرُن، کِنہٕ بہٕ رُکاونہٕ؟ تہٕ خداوند ووٚن، ہیوٚر گژھ۔ تکیازِ پگاہ بہٕ دِیہ تم چانہِ اتھس منز۔\n29.\\tتہٕ اِسرٲیلَن کٔر گِبعاہس اندۍ پٔکھۍ پٔکھۍ رٔٹِتھ رٔٹِتھ ۔\n30.\\tتہٕ بنی اسرائیل لوٚگ تریمہِ دۅہہ بنیامین سٕندِس بُلِس خٕلاف، تہٕ لٔگِکھ باقٕے وقتن ہٕندۍ پٲٹھۍ، گِبیاہ سٕندِس خٕلافس سٍتـ̡ صفہٕ کھڑا کرنہٕ۔\n31.\\tتہٕ بنیامین سٕندِ بچہٕ گٔیہِ لُکن ہٕندِس خٕلافس خٕلاف، {تہٕ} گٔیہِ شہرٕ نِشہ نِش۔ تہٕ تِمو لوگُکھ لُکن پیٹھ مارُن، یِتھ کٔنۍ باقین ساتہٕ شاہراہن مَنٛز مارُن، یِمو منزٕ اکھ خدایہ سٕندِس گرس تام گژھان چُھ، تہٕ بیٛاکھ میدانس مَنٛز گبیاہس کُن، تقریباً ترہ اسرٲیلٕکۍ نفر۔ {سِمِٹ کَرُن...: ہیب۔ زخمیَن ہٕندِس لُکن ہُند مارُن، وغیرہ} {گرٕ...: یا، بیتھل}\n32.\\tتہٕ بنیامین سٕندیو شُرٮ۪و ووٚن زِ تِم چھِ اسہِ برونہہ کُن مارنہٕ آمٕتۍ، یِتھ کٔنۍ گۅڈنِچہِ لٹہِ مارنہٕ آمٕتۍ۔ مگر بنی اسرٲیلیو ووٚن، أسۍ ژٔلِو تہٕ تِم شہر پیٹھٕ شاہراہن کُن نِنہٕ۔\n33.\\tتہٕ سارِوٕے اِسرٲیلٕکۍ مرد ووٚتھ پننہِ جایہِ نِش تہٕ بعلتمارس مَنٛز لٔگِتھ تہٕ دِژ اسرٲیلِس پى۪ٹھٕ پى۪ٹھہٕ پى۪ٹھ، گِبیاہ کِس مرگہٕ منزٕ نِش نِش۔\n34.\\tتہٕ سٲرۍسٕے اِسرٲیلِو منزٕ گِبعاہس سٍتـ̡ دَہ ساس ژارنہٕ آمٕتـ̡ تہٕ جنگ گۆو دَرٕ، مگر تِمن ٲس نہٕ خبر زِ تِمن نِش چُھ بُرٕ۔\n35.\\tتہٕ خداوند دِژ بنیامین اسرٲیلِس برونہہ کُن مار، تہٕ بنی اسرٲیلن کٔر تمہِ دۅہہ وُہ پنٛژاہ ساس تہٕ ہتھ نفر۔\n36. یێمہِ کِنۍ وُچھ بنیمن سٕندیو اولاوو زِ تِم گٔیہِ مارنہٕ، تکیازِ اسرٲیلِیو دِژ بنیمیَن ہٕنز جاے، تِکیازِ تِمو اوس گبیعہس نِش تھاونہٕ آمُت۔\n37.\\tتہٕ انتظارس منز لٔگِتھ ژٔلِتھ گِبعاہس کُن دٔسۍ۔ تہٕ انتظارس منز لٔگِتھ سارِنٕے شہرس تلوار ہٕندِ دھار سٍتۍ لٔگِتھ۔ {ڈریو...: یا، کٔر ٹرمپیٹ سٍتۍ اکھ زیوٹھ آواز}\n38.\\tوۅنۍ اوس اسرٲیلِس تہٕ انتظارس منز روزن والٮ۪ن درمِیان اکھ مقرر نشانہٕ زِ تِم گژھن شہرٕ منزٕ دوٚہہٕ سٍتـ̡ اکھ بٔڈ نار وُتھان۔ {نشان: یا، وقت} {تہٕ: ہیب۔ with} {flame: Heb. بلندی}\n39.\\tییلہ اسرٲیلکۍ مرد جنگس منز پتھ کُن گٔیہ، بنیامین ہیوٚت اسرٲیلِکۍ مرد مارُن تہٕ مارُن ہیوٚت، تکیازِ تِمو ووٚن زِ یِم چھِ اسہِ برونہہ کُن مارنہٕ آمٕتۍ، یِتھ کٔنۍ گۅڈنِچہِ جنگہٕ سٍتـ̡ مارنہٕ آمٕتۍ۔ {سِمِٹ کَرُن...: ہیب۔ زخمیَن مارنہٕ خٲطرٕ}\n40.\\tمگر ییلہ شہرہ منزہ شعلہ دوٚہہِ ہُند تھم ہیتھ وُتھُن ہیوٚت، بنیمییو وُچھن پانس پتھ کُن تہ وُچھتھ ووت شہرُک شعلہ آسمانس کُن۔ {شعلہٕ: ہیب۔ سورے کھپت}\n41.\\tییلہ اسرٲیلِکۍ مرد دُبارٕ پھیُر، بنیامین سٕندِ لُکھ گٔیہِ حٲران، تِکیازِ تِمو وُچھ زِ تِمن پیٹھ آو بُرٕ۔ {اوس آمُت...: ہیب۔ تمن چھہ اتھہ لگان}\n42.\\tتێلہِ پھیرۍ تِمو اِسرٲیلِس برونہہ کُن بیابان کِس وتہِ کُن۔ مگر جنگن لوٚگ تمن پتھ کُن۔ تہٕ تم یم شہرو منزٕ آیہ یم تمو منزٕ تباہ کٔرۍ۔\n43.\\t{یِتھٕ پٲٹھۍ} تِمو لٔگِتھ بنیامین اندۍ ، {تہٕ} لٔگِکھ تِمن سٍتـ̡ یِمن سٍتـ̡ پى۪ {آسٲنی سان...: یا، مینوچہ پیٹھ، بیترِ} {اوور...: ہیب۔ اوور اِنسٹ}\n44.\\tتہٕ اَتھ سٍتـ̡ گٔیہِ بنیامین سٕندِ ارداہ ساس نفر۔ یم سٲری ٲسۍ بہادر نفر۔\n45.\\tتہٕ تِم ژٔلِتھ ژٔلِتھ بیابانن کُن رِمن کِس کٔنہِ کُن، تہٕ تِمو گٔیہِ شاہراہن منز پانژھ ساس نفر۔ تہٕ لوٚگ تِمن پتہٕ گِدومس تام سٮ۪ٹھاہ پَتہٕ، تہٕ مٲرِکھ تِمو منزٕ زٕ ساس نفر۔\n46.\\tیێلہِ یێمہِ دۅہہ یُس سارِوٕے بنیامین سٕندِ دۅہہ پۯاونہٕ آمُت اوس، تِم ٲسۍ وُہ تہٕ پانٛژٕ ساس نفر یِمو تلوار تُلِتھ ۔ یم سٲری ٲسۍ بہادر نفر۔\n47.\\tمگر شیہ ہتھ نفر ژٔلِتھ ژٔلِتھ بیابانن کُن رِمون کُن تہٕ ژٔلِتھ ژ\n48.\\tتہٕ لٔج بنی بنیامین سٕندِس بُلِس پیٹھ دُبارٕ تہٕ لٔگِکھ تِمن تلوارِ ہٕندِس کُنہِ سٍتـ̡ تہٕ سارِنٕے شہرن تہٕ یِمن سارِنٕے شہرن تہٕ یِمن سارِنٕے شہرن نار دِنہٕ۔ {آو اتھس منز: ہیب۔ اوس لبنہٕ آمُت} {تِم آیہ ...: ہیب۔ آیہ لبنہٕ}","1. وۅنۍ اوس اسرٲیلِیو مردو مزپہ ہُند قَسم کٔرِتھ ووٚنمُت زِ اسہِ منزٕ گژھِ نہٕ کانہہ تہِ پننہِ کورِ بنیامنَس دِنہٕ۔\n2. تہٕ لُکھ آیہ خدایہ سٕندِس گرس منز، تہٕ رودُکھ خدایہ سٕندِس گَرَس مَنٛز، تہٕ کٔرٕکھ پنٕنۍ آواز تُلِتھ تہٕ روُن دَرٕ۔\n3. تہٕ وۆنُن، اے خداوند اسرٲیلُک خدا، اسرٲیلِس مَنٛز کیازِ سپُد یہِ سپدُن، یُس از کل اسرٲیلِس مَنٛز اکھ قبیلہٕ آسہِ؟\n4. تہٕ پَگہہ سپُد یہِ زِ لُکھ گٔیہِ سُلہِ وُتھ، تہٕ اَتہِ کٔرِکھ اکھ قربان گاہ تہٕ دِتُکھ دَزنہٕ تہٕ امن ہٕندِس نذرانہ پیشکش۔\n5.\\tتہٕ بنی اسرٲیلِو ووٚن، یُس نہٕ خداوند سٕندِس سٍتـ̡ جماعت ہیتھ آو۔ تِکیازِ تِمو اوس تٔمِس مُتعلِق اکھ بوٚڈ قسم کورمُت یُس نہٕ خداوند سٕندِس نِش مزپہٕ نِش ووت تہٕ ووٚنمُت زِ سُہ یِیہِ یٔقیٖنی طور مارنہٕ یُن۔\n6. تہٕ بنی اسرٲیلیو کٔر تِمن ہٕندِس بٲیِس بنیامین سٕندِ خٲطرٕ توبہ تہٕ وونُن، اَز چُھ اَکھ قبیلہٕ یُس اِسرٲیلِس نِش ژٹنہٕ آمُت چُھ۔\n7. أسۍ کِتھ کٔنۍ کرو تِمن ہٕندِ خٲطرٕ یِمن ہٕندِ خٲطرٕ یِم باقٕے روزان چھِ، یێلہِ أسۍ چھِ خداوند سُند قسم کھوٚتمُت زِ أسۍ دِیہ نہٕ تِمن پننہِ کورِ زنانہٕ دِنہٕ۔\n8.\\tتہٕ تِمو ووٚن، اِسرٲیلِیَن ہٕندِس قبیلس مَنٛز کُس چُھ یُس نہٕ مزپہ تام رب سٕندِس نِش ووتمُت چھُ؟ تہٕ وُچھِتھ آو نہٕ جابشگیلاد پٮ۪ٹھٕ مجلسہِ تام خٲمس منٛز۔\n9.\\tتکیازِ لُکن ہُند تعداد اوسُکھ تہٕ وُچھِتھ اوس نہٕ یَبِشِگلاڈٕکۍ بسکیٖن دَرن ہُند کانہہ تہِ۔\n10.\\tتہٕ جمٲژ سوٗزۍ بہادر ساس نفر تہٕ دِتُن تِمن حکم دِتھ زِ گژھ تہٕ جابیشگیلاد کین بسکینن تلوار ہٕندِ دھار سٍتۍ، زنانن تہٕ شُرین سٍتـ̡ مارُن۔\n11.\\tتہٕ یێلہِ چُھہ یُس تۅہہ کرُن، تہٕ پرتھ کانہہ مرد تہٕ پرتھ زنانہٕ یُس مردس سٍتـ̡ دِنہٕ آمُت چُھ، تُہۍ کرِ مکمل طور تباہ کرُن۔{ہُس لیِن...: ہیب۔ انسانس سٍتـ̡ چُھہ پۯاونہٕ آمُت}\n12.\\tتہٕ تِمو وُچھ جابشگیلد کین بسکینن منز ژور ہتھ جوان کُنوارۍ، یِم کٲنسہ تہِ مردس سٍتـ̡ کُنہِ تہِ مردس سٍتـ̡ زانان ٲس، تہٕ تِمو أنۍ تِم شیلوہ کِس خٲمس منز، یُس کنعان کِس سرزمینس مَنٛز چُھ۔ {نوجوان...: ہیب۔ نوجوان زنانہٕ کنواری}\n13.\\tتہٕ سٲرۍسٕے جمٲژ سوٗزۍ {کینٛہہ} بنیامین سٕندٮ۪ن شُرین سٍتـ̡ کتھ کرنہٕ خٲطرٕ یِم کٔنہِ کٔنہِ رِمنس منز ٲسۍ، تہٕ تِمن سٍتـ̡ امن سان بُلاونہٕ خٲطرٕ۔ {کتھ کرنہٕ خٲطرٕ...: ہیب۔ تہٕ کٔرٕن تہٕ بلاو} {بلاو...: یا، امن ہُند اعلان}\n14. تہٕ بنیامین آو تمہِ وِزِ دُبارٕ۔ تہٕ تِمو دِژ تِمن زنانہٕ یِم یِمو جبیشگیلاد سٕنزِ زنانہٕ نِش زِندٕ بچٲومٕژ ٲس، تہٕ توتہِ گٔیہِ نہٕ تِمن کافی۔\n15.\\tتہٕ لوکو کٔر تِمن بنیامین سٕندِ خٲطرٕ توبہٕ، تکیازِ خداوند اوس اسرائیلٕکین قبیلن مَنٛز دراندازی کٔرمٕژ۔\n16.\\tاَمہِ پَتہٕ ووٚن جمٲژ ہٕندِیو بزرگو زِ أسـ̡ کِتھہٕ کٔنۍ کٔرِو تِمن ہٕندِ خٲطرٕ یِمن ہٕندِ خٲطرٕ زنانہٕ یِم بنیامین سٍتـ̡ تباہ گٔیہِ؟\n17.\\tتہٕ تِمو ووٚن، {تِمن ہٕندِ خٲطرٕ گژھہِ اکھ وراثت آسُن یُس بنیامین نِش بچنہٕ یُن، یُس نہٕ کانہہ قبیلہ اسرٲیلِس منزٕ تباہ کرنہٕ یُن۔\n18.\\tبہٕ ہێکہِ أسۍ یِمن پننین کورِ ہٕنزِ زنانہٕ دِنہٕ یِوان، تِکیازِ اسرٲیلِیو ہٕندِس اولادَس چھُ قَسم کٔرمُت زِ یُس بنیامین سٕندِس خانٛدارِنۍ دِیہِ۔\n19.\\tاَمہ پتہٕ ووٚن تِمو زِ وُچھِو شِلوہس مَنٛز سالانہٕ سالانہٕ {أکِس جایہ} یُس بیت ایل کِس شمالس کُن، شاہراہ کِس مشرقس کُن یُس بیت ایل پیٹھہٕ شیکم تام گژھان چُھ، تہٕ لبنہٕ کِس جنوبس کُن چُھ۔ {سالانہٕ: ہیب۔ ؤری پتہٕ ؤری} {مشرقس پیٹھ...: یا، آفتابس کُن} {شاہراہ: یا، شاہراہس پیٹھ}\n20. تێمہِ کِنۍ دِژ تِمو بنیامین سٕندٮ۪ن شُرین حُکُم تہٕ وونُن زِ گژھ تہٕ انگورن مَنٛز پیارٕ کٔرِتھ۔\n21. تہٕ وُچھِو، تہٕ وُچھِو، یێلہِ شیلوہٕچ کورِ نژنہٕ خٲطرٕ نیرِ، تیلہِ گژھِو تُہۍ انگورو منزٕ نژان، تہٕ ژے رٔٹِو پرٮ۪تھ أکِس مردس شِلوہٕ سٕنزِ کورِ ہٕنزِ زنانہٕ، تہٕ گژھِو بنیامین سٕندِس ملکس کُن۔\n22.\\tتہٕ یێلہِ یێلہِ تِہُند مول یا تِہٕندِ بٲے اسہِ نِش شکایت کرنہٕ یِن، تہٕ أسۍ وَنُن تِمن ہٕندِ خٲطرٕ، تِکیازِ أسۍ کٔرِو نہٕ جنگس مَنٛز پرٮ۪تھ أکِس مردس سٕنزِ زنانہِ ہٕندِس خٲطرٕ رژھراونہٕ، کیازِ ژے دِژ نہٕ تِمن وِزِ دِژمٕژ، تہٕ یێلہِ گٔژھِو تُہۍ گُنہار۔ {سازگار روزُن...: یا، تمن منز کرو اسہِ تسلی بخش}\n23.\\tتہٕ بنیامین سٕندیو اولاوو کٔر یۅہے تہٕ رٔٹِکھ تِمن ہٕندِس تعدادس مُطٲبق زنانہٕ، یِمو نژان آسہٕ، یِمن رٔٹِتھ تہٕ تِمو گٔیہِ پننِس وراثتس منز واپس، تہٕ شہرن ہٕنز مرمت کٔرِکھ تہٕ تِمن منز روزُن۔\n24. تہٕ اَمہِ وِزِ گٔیہِ اَمہِ وِزِ اَمہِ وِزِ اِسرٲیلِکۍ بَے اَمہِ وِزِ پَنٕنِس قبیلس تہٕ پَنٕنِس عیالس کُن، تہٕ تِم گٔیہِ تتہِ نِش پرٮ۪تھ أکِس شخصس پَنٕنِس وراثتس کُن۔\n25.\\tتِمن دۅہن اوس نہٕ اسرٲیلِس مَنٛز کانہہ بادشاہ آسان: پرٮ۪تھ کانہہ انسان اوس سُہ کٔرِتھ یُس پننہِ نظرِ منز صحیح اوس۔"];
